      }
    }
    exchange(a,i+1,r)
    i+1
  }

  def quicksort(a:Array[(String,Int)],p:Int,r:Int):Unit = {
    if(p<r) {
      val q = partition(a,p,r)
      quicksort(a,p,q-1)
      quicksort(a,q+1,r)
    }
  }

