    val a = { for(i <- 1 to n) yield {
      val s = readLine.split(" ")
      (s(0),s(1).toInt)
    } }.toArray
    val org = a.clone
    quicksort(a,0,n-1)
    if(isStable(org,a))  println("Stable") else println("Not stable")
    println(a.map(e=>e._1+" "+e._2).mkString("\n"))
  }
