        int q = partition(qs,p,r);
        quicksort(qs, p, q-1);
        quicksort(qs, q+1, r);
    }
}

void merge(vector<card> &ms, int l, int m, int r){
    int n1 = m-l;
    int n2 = r-m;
    int i,j;
    vector<card> L(n1+1);
    vector<card> R(n2+2);
    rep(i,n1){
        L[i] = ms[l+i];
    }
    rep(i,n2) {
        R[i] = ms[m+i];
    }
    L[n1].second = INT_MAX;
    R[n2].second = INT_MAX;
    i = 0;
    j = 0;
    for(int k = l; k < r; k++) {
        if(L[i].second <= R[j].second) {
            ms[k] = L[i];
            i++;
        } else if(ms[k].second == R[j].second) {
            j++;
        }
    }
}

void mergesort(vector<card> &ms, int l, int r) {
    if (l+1 < r) {
        int m = (l+r)/2;
        mergesort(ms,l,m);
        mergesort(ms,m,r);
        merge(ms,l,m,r);
    }
}

