    int x = a[r].num;
    int i = p - 1;
    for(int j = p; j < r; j++){
        if(a[j].num <= x){
            i++;
            swap(a[i], a[j]);
        }
    }
    swap(a[i+1], a[r]);
    return i + 1;
}

