int partition(card A[], int p, int r){
	int memo=A[r].in;
	int i=p-1;
	for(int j=p; j<r; j++){
		int k=A[j].in;
		if(k<=memo){
			i++;
			card s=A[i];
			A[i]=A[j];
			A[j]=s;
		}
	}
	card m=A[i+1];
	A[i+1]=A[r];
	A[r]=m;
	return i+1;
}
