int partition(vector<pair<char,int>> &a,int p,int r){
    int x=a[r].second;
    int i=p-1;
    for(int j=p;j<(r);j++){
        if(a[j].second<=x){
            i++;
            pair<char,int> key=a[i];
            a[i]=a[j];
            a[j]=key;
        }
    }
    pair<char,int> key=a[i+1];
    a[i+1]=a[r];
    a[r]=key;
    return i+1;
}

