#include <bits/stdc++.h>

using namespace std;

typedef pair<int, char> P;

int partition(P* A, int p, int r){

    int x = A[r].first;
    int i = p - 1;

    for (int j = p; j < r; j++){

        if (A[j].first <= x){

            i++;
            swap(A[i], A[j]);
        }
    }

    i++;
    swap(A[i], A[r]);
    return i;
}

void quicksort(P* A, int p, int r){

    //p >= rとなったとき, すでにクイックソートは完了している
    //この条件がないと, 無限ループに陥る
    if (p < r){
        int q = partition(A, p, r);
        quicksort(A, p, q-1);
        quicksort(A, q+1, r);
    }

    //quicksortが完了した時点で,もとの配列内でのソートが完了している
    //mergeは必要ない.
}


