    bool flag = 1;

    for (int i = 0; i < n; i++){
        flag &= (m1[A[i].first] == m2[A[i].first]);
    }

    if (flag) cout << "Stable" << endl;
    else cout << "Not stable" << endl;

    for (int i = 0; i < n; i++){
        cout << A[i].second << " " << A[i].first << endl;
    }
}

