#include <iostream>
#include <cstdio>
using namespace std;
struct Element {
    char c;
    int number;
};

void swap(Element &a, Element &b) {
    Element temp = a;
    a = b;
    b = temp;
}

int _div(Element *A, int left, int right) {
    Element keyValue = A[left];
    int i = left;
    int j = right;
    while (i < j) {

        while (A[j].number > keyValue.number && j > i) {
            j--;
        }

        if (j > i) {
            A[i++] = A[j];
        }

        while (A[i].number <= keyValue.number && j > i) {
            i++;
        }

        if (j > i) {
            A[j--] = A[i];
        }
    }
    A[i] = keyValue;

    return i;
}

void qs(Element *A, int left, int right) {
    if (left < right) {
        int mid = _div(A, left, right);
        qs(A, left, mid - 1);
        qs(A, mid + 1, right);
    }
}

