template<typename T>
int partition(std::vector<T> &A, int p, int r, bool (*f)(T, T) ) {
	T x = A[r];
	int i = p - 1;
	for (int j = p; j < r; ++j) {
		if (f(A[j], x)) {
			i++;
			swap<T>(A[i], A[j]);
		}
	}
	swap<T>(A[i + 1], A[r]);
	return i + 1;
}

template<typename T>
void quicksort(std::vector<T> &A, int p, int r, bool (*f)(T, T) ) {
	if (p >= r) return;
	int q = partition<T>(A, p, r, f);
	quicksort<T>(A, p, q - 1, f);
	quicksort<T>(A, q + 1, r, f);
}


