int partition(int *a, char *s, int p, int r){
    int x = a[r];
    char y = s[r];
    int i = p - 1;
    int tmp1;
    char tmp2;
    for(int j=p;j<r;j++){
        if(a[j]<=x){
            i++;
            tmp1 = a[j];
            a[j] = a[i];
            a[i] = tmp1;
            tmp2 = s[j];
            s[j] = s[i];
            s[i] = tmp2;
        }
    }
    a[r] = a[i+1];
    a[i+1] = x;
    s[r] = s[i+1];
    s[i+1] = y;
    return i + 1;
}

