    int x = v[r].second;
    int i = l - 1;
    Pci t;
    for (int j = l; j < r; ++j) {
        if (v[j].second <= x) {
            ++i;
            t = v[i];
            v[i] = v[j];
            v[j] = t;
        }
    }
    t = v[i + 1];
    v[i + 1] = v[r];
    v[r] = t;
    return i + 1;
}
