	int x = A[r].first;
	int ind = p-1;
	for (int i = p; i < r; ++i) {
		if (A[i].first <= x) {
			++ind;
			swap(A[i].first,A[ind].first);
			swap(A[i].second,A[ind].second);
		}
	}
	swap(A[r].first,A[ind+1].first);
	swap(A[r].second,A[ind+1].second);
	return (ind+1);
