int Partition(vc& target, int iP, int iR)
{
    using namespace std;

    int x = target[iR].num;
    int i = iP - 1;

    for (int j = iP; j < iR; ++j)
    {
        if (target[j].num <= x)
        {
            swap(target[++i], target[j]);
        }
    }

    swap(target[++i], target[iR]);

    return i;
}

