void Swap1(int* a, int* b)
{
  int tmp = *a;
  *a = *b;
  *b = tmp;
}

void Swap2(char* a, char* b)
{
  char tmp = *a;
  *a = *b;
  *b = tmp;
}

int Partition(int p, int r)
{
  int x = A[r];
  int i = p - 1, j;
  for(j=p ; j<r ; j++)
  {
    if(A[j] <= x)
    {
      i++;
      Swap1(&A[i], &A[j]);
      Swap2(&X[i], &X[j]);
    }
  }
  Swap1(&A[i+1], &A[r]);
  Swap2(&X[i+1], &X[r]);
  return i+1;
}

void quic_sort(int p, int r)
{
  if(p < r)
  {
    int q = Partition(p, r);
    quic_sort(p, q-1);
    quic_sort(q+1, r);
  }
}

