      for(j=0 ; j<n ; j++)
      {
        if(A[i-1] == Number[j] && X[i-1] == C[j]) a = j;
        if(A[i] == Number[j] && X[i] == C[j]) b = j;
      }
      if(a > b) return 0;
    }
  }
  return 1;
}

