int partition(int* arr,char* ch, int head, int tail) {
	using namespace std;
	int stan = arr[tail];
	int board = head - 1;
	for (int j = head; j < tail; j++) {
		if (arr[j] <= stan) {
			board++;
			swap(arr[j], arr[board]);
			swap(ch[j], ch[board]);
		}
	}
	swap(arr[tail], arr[board + 1]);
	swap(ch[tail], ch[board + 1]);
	return board+1;
}

void quickSort(int* arr,char* ch, int head, int tail) {
	if (head < tail) {
		int ntail = partition(arr, ch, head, tail);
		quickSort(arr, ch, head, ntail-1);
		quickSort(arr, ch, ntail + 1, tail);
	}
}

void printAns(int* arr, char* ch, int len) {
	using std::cout;
	using std::endl;
	for (int i = 0; i < len; i++)
		cout << ch[i] << " " << arr[i]<<endl;
}

void insertionSort(int* arr, char* ch, int len) {
	using namespace std;
	for (int i = 0; i < len - 1; i++) {
		int temp = arr[i + 1];
		char tch = ch[i + 1];
		int j = i;
		while (j>=0 && arr[j] > temp) {
			swap(arr[j], arr[j + 1]);
			swap(ch[j], ch[j + 1]);
			j--;
		}
		arr[j] = temp;
		if (arr[j] != arr[j + 1])
			ch[j] = tch;
	}
}

