		if(A[i] < A[i-1]){
			swap(&A[i], &A[i-1]);
			swap(&S1[i], &S1[i-1]);
			flag = true;
			}
		}
	}
}

int partition(int A[], int p, int r){
	int x = A[r-1], cnt = p-1;
	for(int i=p;i<r;++i){
		if(A[i] <= x){
			cnt++;
			swap(&A[cnt], &A[i]);
			swap(&S2[cnt], &S2[i]);
		}
	}
	return cnt;
}

void quickSort(int A[], int p, int r){
	if(p < r){
		int q = partition(&A[0], p, r);
		quickSort(&A[0], p, q-1);
		quickSort(&A[0], q+1, r);
	}
}

void judge(int n){
	int flag = true;
	for(int i=0;i<n;++i){
		if(S1[i] != S2[i]){
			flag = false;
			break;
		}
	}
	if(flag)cout << "Stable" << endl;
	else cout << "Not stable" << endl;
}

