using namespace std;

struct card{
	char mark;
	int num;
};

void swap(card &a, card &b){
	card temp = a;
	a = b;
	b = temp;
}

int partition(vector<card> &A, int p, int r){
	card x = A[r]; 
	int	i = p-1;
	for(int j=p;j<r;j++){
		if(A[j].num <= x.num){
			i++;
			swap(A[i], A[j]);
		}
	}
	swap(A[i+1], A[r]);
	return i+1;
}

void bubbleSort(vector<card> &A){
	for(int i=0;i<A.size();i++)
		for(int j=A.size()-1;j>i;j--)
			if(A[j].num < A[j-1].num)
				swap(A[j], A[j-1]);
}

void quickSort(vector<card> &A, int p, int r){
	if(p < r){
		int q = partition(A, p, r);
		quickSort(A, p, q-1);
		quickSort(A, p+1, r);
	}
}

bool match(card a, card b){
	if((a.mark == b.mark) && (a.num == b.num))
		return true;
	else
		return false;
}

bool isStable(vector<card> a, vector<card> b){
	for(int i=0;i<a.size();i++)
		if(!match(a[i], b[i]))
			return false;

	return true;
}

