    unsigned int val;
    size_t order;
};

void quick_sort(Card *, size_t, size_t);

size_t partition(Card *cards, size_t l, size_t r)
{
    Card pivot = cards[r];

    while (l < r) {
        while (cards[l].val <= pivot.val)
            l++;
        while (cards[r].val > pivot.val)
            r--;
        if (l < r)
            swap(cards[l++], cards[r--]);
        else
            break;
    }

    return r;
}

void quick_sort(Card *cards, size_t l, size_t r)
{
    if (l < r) {
        size_t p = partition(cards, l, r);
        quick_sort(cards, l, p - 1);
        quick_sort(cards, p, r);
    }
}

