    int index = 0, current_n = 0;
    FOR(i, left, right) {
        auto cur = sorted[i];

        if (cur.second != current_n) {
            current_n = cur.second;
            index = 0;
        }

        FOR(j, left, right) {
            if (cur == original[j]) {
                if (index > j) {
                    cout << "Not stable" << endl;
                    return;
                }

                index = j;
            }
        }
    }

    cout << "Stable" << endl;
    return;
}

