int partition(vector<pair<string, int>> &a, int p, int r)
{
	pair<string, int> x = a.at(r);
	int id = p - 1;

	for (int i = p; i < r; i++)
	{
		if (a.at(i).second <= x.second)
		{
			id++;
			swap(a.at(i), a.at(id));
		}
	}
	swap(a.at(id + 1), a.at(r));

	return id + 1;
}

