            swap(A.at(i), A.at(j));
        }
    }
    swap(A.at(i + 1), A.at(r));

    return i + 1;
}

void quicksort(vector<TRUMP> &A, int p, int r)
{
    if (p < r)
    {
        int q = partition(A, p, r);
        quicksort(A, p, q - 1);
        quicksort(A, q + 1, r);
    }
}

