int partition(int l, int r){
    int pivot = a[r].first;
    int i = l-1;
    for (int j = l; j < r; j++){
        if(a[j].first <= pivot){
            i++;
            swap(a[i], a[j]);
        }
    }
    swap(a[i+1], a[r]);
    return i+1;
}

