    for(int i=0;i<n2;i++){
        R[i] = M[mid+i];
    }
    L[n1].value = INFI;
    R[n2].value = INFI;
    int i=0,j=0;
    for(int k=0;k<n1+n2;++k){
        if(L[i].value<=R[j].value){
            M[left+k].value = L[i].value;
            M[left+k].suit = L[i].suit;
            i++;
        }
        else{
            M[left+k].value = R[j].value;
            M[left+k].suit = R[j].suit;
            j++;
        }
    }
}

