typedef struct {
  char mark;
  int num;
} Card;

void countingSort(std::vector<Card>& A, std::vector<Card>* B, int k) {
  std::vector<int> C(k + 1, 0);
  for (int j = 0; j < (int) A.size(); ++j)
    C[A[j].num]++;

  for (int i = 1; i <= k; ++i)
    C[i] = C[i] + C[i-1];

  for (int j = (int) A.size() - 1; j >= 0; --j) {
    (*B)[C[A[j].num]] = A[j];
    C[A[j].num]--;
  }
}

int partition(std::vector<Card>* A, int p, int r) {
  int x = (*A)[r].num;
  int i = p - 1;
  for (int j = p; j < r; ++j) {
    if ((*A)[j].num <= x) {
      i = i + 1;
      std::swap((*A)[i], (*A)[j]);
    }
  }
  std::swap((*A)[i + 1], (*A)[r]);
  return i + 1;
}

void quickSort(std::vector<Card>* A, int p, int r) {
  if (p < r) {
    int q = partition(A, p, r);
    quickSort(A, p, q - 1);
    quickSort(A, q + 1, r);
  }
}

int main() {
