  std::cin >> n;
  std::vector<Card> cards;
  int max = 0;
  for (int i = 0; i < n; ++i) {
    Card c;
    std::cin >> c.mark >> c.num;
    cards.push_back(c);
    max = (c.num > max)? c.num : max;
  }
  std::vector<Card> count_sort(n + 1);
  countingSort(cards, &count_sort, max);
  quickSort(&cards, 0, n-1);
  bool flag = true;
  for (int i = 0; i < n; ++i) {
    if (cards[i].mark != count_sort[i + 1].mark ||
        cards[i].num != count_sort[i + 1].num) {
      flag = false;
      break;
    }
  }
  std::cout << (flag ? "Stable" : "Not stable") << std::endl;
  std::for_each(cards.begin(), cards.end(), [](Card c) {
      std::cout << c.mark << " " << c.num << std::endl;
    });
  return 0;
}

