{
    int size = cards.size();
    int i, j;

    for (i = 1; i < size; ++i) {
        Card* tmp = cards[i];
        for (j = i; j > 0; --j) {
            if (cards[j - 1]->number > tmp->number)
                cards[j] = cards[j - 1];
            else
                break;
        }
        cards[j] = tmp;
    }
}

