int partition(int *A, char *C, int p, int r) {
    int x = A[r];
    int i = p;

    for (int j = p; j < r; j++) {
        if (A[j] <= x) {
            std::swap(A[i], A[j]);
            std::swap(C[i], C[j]);
            i++;
        }
    }
    std::swap(A[i], A[r]);
    std::swap(C[i], C[r]);
    return i;
}

