            for (int j = 0; j < n; j++) {
                if (C[i] == Ct[j] && A[i] == At[j]) {
                    break;
                } else if (C[i + 1] == Ct[j] && A[i + 1] == At[j]){
                    return false;
                }
            }
        }
    }
    return true;
}


