void merge(struct Card A[], int left, int mid, int right) {
    int k;
    int n1 = mid - left;
    int n2 = right - mid;

    struct Card L[n1+1], R[n2+1];
    for(int i=0; i<n1; i++) L[i].value = A[left + i].value;
    for(int i=0; i<n2; i++) R[i].value = A[mid + i].value;
    L[n1].value = R[n2].value = INF;

    int i=0, j=0;
    for (int k=left; k<right; k++) {
        if (L[i].value <= R[j].value) {
            A[k] = L[i];
            i++;
        } else {
            A[k] = R[j];
            j++;
        }
    }
}

void mergeSort(struct Card *A, int left, int right) {
    if(left+1 < right) {
        int mid = (left+right)/2;
        mergeSort(A, left, mid);
        mergeSort(A, mid, right);
        merge(A, left, mid, right);
    }
}

int partition(struct Card *A, int p, int r) {
    struct Card x;
    x = A[r];
    int i = p-1;
    for (int j=p; j<r; j++) {
        if(A[j].value <= x.value) {
            i++;
            struct Card tmp=A[i];
            A[i] = A[j];
            A[j] = tmp;
        }
    }
    struct Card tmp;
    tmp = A[i+1];
    A[i+1] = A[r];
    A[r] = tmp;

    return i+1;
}

void quickSort(struct Card A[], int p, int r) {
    int q;
    if(p<r) {
        q = partition(A, p, r);
        quickSort(A, p, q-1);
        quickSort(A, q+1, r);
    }
}

