card deck[MAX_INPUT+1];
card deck_to_check[MAX_INPUT+1];//バブルソートを用いたクイックソートの安定性検証用配列
int n;//num of input


int partition(card A[],int p,int r){//rは配列の最後を指す添え字
	int x = A[r].number;
	int i = p;
	card tmp;

	for(int j=p;j<r;j++){
		if(A[j].number <= x){
			tmp = A[i];
			A[i] = A[j];
			A[j] = tmp;
			i++;
		}
	}
	tmp = A[i];
	A[i] = A[r];
	A[r] = tmp;

	return i;
}

//クイックソートの安定性のチェックのため
void bubbleSort(card A[],int N){
	bool flag = true;
	card tmp;

	while(flag){
		flag = false;

		//交換が一回も行われなかった場合flag = trueでforループを抜ける
		for(int j=N-1;j>0;j--){
			if(A[j].number < A[j-1].number){
				tmp = A[j];
				A[j] = A[j-1];
				A[j-1] = tmp;
				flag = true;
			}
		}
	}
}

void quickSort(card A[],int p,int r){
	int q;
	if(p < r){
		q = partition(A,p,r);
		quickSort(A,p,q-1);
		quickSort(A,q+1,r);
	}
}

