      if(input[i].value == ck) l.push_back(input[i].c);
    }
    for(int i = 0; i < sorted.size(); i++){
      if(sorted[i].value == ck){
        if(sorted[i].c == *(l.begin())){
          l.erase(l.begin());
        }else{
          return false;
        }
      }
    }
  }
  return true;
}

