int partition_tail_pivot(vector<Card>& a, int p, int r){
  auto piv = a[r];
  int i = p-1;
  for(int j = p; j < r; ++j){
    if(a[j] <= piv){
      ++i;
      swap(a[i], a[j]);
    }
  }
  swap(a[i+1], a[r]);
  return i+1;
}


