int partition(Card A[],int p,int r){
	int i = p-1;
	int x = A[r-1].number;
	for(int j=p;j<r-1;j++){
		if(x>=A[j].number){
			swap(A[++i],A[j]);
		}
	}
	swap(A[++i],A[r-1]);
	return i;
}

void quickSort(Card A[],int p,int r){
	if(p<r){
		int q = partition(A,p,r);
		quickSort(A,p,q-1);
		quickSort(A,q+1,r);
	}
}

void bubble(Card A[],int r){
	for(int i=0;i<r;i++){
		for(int j=r-1;j>i;j--){
			if(A[j].number<A[j-1].number){
				swap(A[j],A[j-1]);
			}
		}
	}
}

bool judgement(Card A[],Card B[],int n){
	for(int i=0;i<n;i++){
		if(A[i].name!=B[i].name){
			return false;
		}
	}
	return true;
}

