inline void swap(Card& a, Card& b) {
    Card tmp = a;
    a = b;
    b = tmp;
}

inline int partition(int p, int r) {
    int i = p - 1;
    for (int j = p, x = cards[r].rank; j < r; ++j) {
        if (cards[j].rank <= x) {
            swap(cards[j], cards[++i]);
        }
    }
    swap(cards[r], cards[++i]);
    return i;
}

void quicksort(int p, int r) {
    if (p < r) {
        int q = partition(p, r);
        quicksort(p, q - 1);
        quicksort(q + 1, r);
    }
}

