int Partition(int A[],char B[],int p,int r){
    int x = A[r];
    int i = p-1;
    FOR(j,p,r){
        if(A[j] <= x){
            i = i+1;
            swap(A[i],A[j]);
            swap(B[i],B[j]);
        }
    }
    swap(A[i+1],A[r]);
    swap(B[i+1],B[r]);
    return i+1;
}

void Quicksort(int A[100001],char B[100001],int p,int r){
    if( p < r){
