void merge(int A[100001],char B[100001],int l,int r){
    if(l >= r ) return;

    int i,j,k;
    int m = (l+r)/2;
    merge(A,B,l,m);
    merge(A,B,m+1,r);

    for(i = l;i <= m ;i++){
        temp[i] = A[i];
        ctemp[i] = B[i];
    }
    for(i=m+1,j=r;i<=r;i++,j--){
        temp[i] = A[i];
        ctemp[i] = B[i];
    }
    i = l;
    j = r;
    for(k=l;k<=r;k++){
        if(temp[i]<temp[j]){
            A[k] = temp[i];
            B[k] = ctemp[i++];
        }else{
            A[k] = temp[j];
            B[k] = ctemp[j--];
        }
    }

}

