template<typename T>
void swap(T* a, T* b){
	T tmp = *a;
	*a = *b;
	*b = tmp;
}

void bubble(int A[], int n){
	int flag;
	while(flag){
	flag = false;
	for(int i = n-1;i >= 1;--i){
		if(A[i] < A[i-1]){
			swap(&A[i], &A[i-1]);
			swap(&S1[i], &S1[i-1]);
			flag = true;
			}
		}
	}
}

