	int x = A[r], cnt = p-1;
	for(int i=p;i<r;++i){
		if(A[i] <= x){
			cnt++;
			swap(&A[cnt], &A[i]);
			swap(&S2[cnt], &S2[i]);
		}
	}
	swap(&A[cnt+1], &A[r]);
	swap(&S2[cnt+1], &S2[r]);
	return ++cnt;
}

