{
	char m1[9][4] = { "\0" };
	for (int i = 0; i < n; i++) {
		for (int j = 0; j < 4; j++) {
			if (m1[t1[i].num - 1][j] == '\0') {
				m1[t1[i].num - 1][j] = t1[i].mark;
				break;
			}
		}
	}

	char m2[9][4] = { "\0" };
	for (int i = 0; i < n; i++) {
		for (int j = 0; j < 4; j++) {
			if (m2[t2[i].num - 1][j] == '\0') {
				m2[t2[i].num - 1][j] = t2[i].mark;
				break;
			}
		}
	}

	for (int i = 0; i < 9; i++) {
		for (int j = 0; j < 4; j++) {
			if (m1[i][j] != m2[i][j]) return false;
		}
	}
	return true;
}

