    {
        if (data[i].num <= x)
        {
            swap(data[i], data[j]);
            j++;
        }
    }
    swap(data[j], data[r]);
    return j;
}

void QuickSort(int n, int r)
{
    if (n < r)
    {
        int t = Partition(n, r);
        QuickSort(n, t - 1);
        QuickSort(t + 1, r);
    }
}

void Merge(int left, int mid, int right)
{
    int n1 = mid - left;
    int n2 = right - mid;
    Data L[n1 + 1], R[n2 + 1];
    for (int i = 0; i < n1; i++)
    {
        L[i] = data2[left + i];
    }
    for (int i = 0; i < n2; i++)
