    }
    L[n1].num = INT_MAX;
    R[n2].num = INT_MAX;
    int i = 0;
    int j = 0;
    for (int k = left; k < right; k++)
    {
        if (L[i].num <= R[j].num)
        {
            data2[k] = L[i];
            i++;
        }
        else
        {
            data2[k] = R[j];
            j++;
        }
    }
}

