}

int partition(vector<card> &A, int p, int r){
	card x = A[r]; 
	int	i = p-1;
	for(int j=p;j<r;j++){
		if(A[j].num <= x.num){
			i++;
			swap(A[i], A[j]);
		}
	}
	swap(A[i+1], A[r]);
	return i+1;
}

void merge(vector<card> &A, int left, int mid, int right){
	int n1 = mid - left, n2 = right - mid;
	vector<card> L(n1), R(n2);

	for(int i=0;i<n1;i++)
		L[i] = A[left+i];
	for(int i=0;i<n2;i++)
		R[i] = A[mid+i];

	int i=0, j=0;
	for(int k=left;k<right;k++){
		if(i >= n1){
			A[k] = R[j];
			j++;
			continue;
		}

		if(j >= n2){
			A[k] = L[i];
			i++;
			continue;
		}

		if(L[i].num <= R[j].num){
			A[k] = L[i];
			i++;
		}else{
			A[k] = R[j];
			j++;
		}
	}
}

void mergeSort(vector<card> &A, int left, int right){
	if(left+1 < right){
		int mid = (left + right) / 2;
		mergeSort(A, left, mid);
