	int middle = (begin + end) / 2;
	mergeSort(data, begin, middle);
	mergeSort(data, middle + 1, end);

	int n1 = middle - begin + 1;
	int n2 = end - (middle + 1) + 1;
	for (int i = 0; i < n1; i++)
	{
		temp_l[i] = data[begin + i];
