	for (int k = begin; k <= end; k++)
	{
		if (compare(temp_l[i], temp_r[j]) <= 0)
		{
			data[k] = temp_l[i];
			i++;
		}
		else
		{
			data[k] = temp_r[j];
			j++;
		}
	}
}

