  int n2 = right - mid;

  for(int i = 0; i < n1; i++) {
    L[i] = array[left + i];
  }
  for(int i = 0; i < n2; i++) {
    R[i] = array[mid + i];
  }
  L[n1] = make_pair(DUMMY, INF);
  R[n2] = make_pair(DUMMY, INF);

  int i = 0;
  int j = 0;

  for(int k = left; k < right; k++) {
    if(L[i] <= R[j]) {
      array[k] = L[i];
      i++;
    }
    else {
      array[k] = R[j];
      j++;
    }
  }
}

void mergeSort(pair<char, int> array[], int left, int right) {
  if(left + 1 < right) {
    int mid = (left + right) / 2;
    mergeSort(array, left, mid);
