  for (int j = p; j < r; ++j) {
    if (A[j].val <= x) {
      ++i;
      swap(A[i], A[j]);
    }
  }
  swap(A[i + 1], A[r]);
  return i + 1;
}

void quickSort(vector<Card>& A, int p, int r) {
  if (p < r) {
