        R[i] = A[mid+i];
    }
    L[n1].second = INT_MAX; R[n2].second = INT_MAX;

    // 右側と左側の小さい方を取ってきて並べ替え
    int i = 0, j = 0;
    for(int k = left; k < right; k++){
        if(L[i].second <= R[j].second){
            A[k] = L[i];
            i++;
        }else{
            A[k] = R[j];
            j++;
        }
    }
}


