	int i = P - 1, j;
	struct Card X = A[R], t;
	for (int j = P; j < R; j++) {
		if (A[j].value <= X.value) {
			i++;
			t = A[i]; A[i] = A[j]; A[j] = t;
		}
	}
	t = A[i + 1]; A[i + 1] = A[R]; A[R] = t;
	return i + 1;
}
