    R[nr].value = SENTINEL;
    int li = 0, ri = 0;
    for (int i = l; i < r; i++) {
        if(L[li].value <= R[ri].value) {
            A[i] = L[li++];
        }else {
            A[i] = R[ri++];
        }
    }
}

