        int m = (r + l) / 2;
        mergeSort(A, l, m);
        mergeSort(A, m, r);
        merge(A, l, m, r);
    }
}



int partition(Card *A, int l, int r) {
    int p = A[r].value;
    int pi = l - 1;
    for (int i = l; i < r; i++) {
        if(A[i].value <= p) {
            pi++;
            std::swap(A[i], A[pi]);
        }
    }
    pi++;
    std::swap(A[r], A[pi]);
    return pi;
}

void quickSort(Card *A, int l, int r) {
    if (l < r) {
        int pi = partition(A, l, r);
        quickSort(A, l, pi-1);
        quickSort(A, pi+1, r);
    }
}

