        if (card[i].value <= card[end].value) 
        {
            j++;
            swap(card[i], card[j]);
        }
    }
    swap(card[j+1], card[end]);
    return j+1;
}

void QuickSort(Card* card, int start, int end) 
{
    if(start < end) 
    {
        int p = Partition(card, start, end);
        QuickSort(card, start, p-1);
        QuickSort(card, p+1, end);
    }
}

