    for (int i = 0; i < n2; ++i) R[i] = card[middle+i];
    L[n1].value = L[n2].value = H;
    int j = 0, k = 0;
    for (int i = start; i < end; ++i) 
    {
        if (L[j].value <= R[k].value) card[i] = L[j++];
        else card[i] = R[k++];
    }
}

