void quicksort(int a[],char s[],int p,int r){
	if(p<r){
		//partition(a,p,r)
		int x=a[r];
		int i=p;
		for(int j=p;j<r;j++){
			if(a[j]<=x){
				swap(a[i],a[j]);
				cswap(&s[i],&s[j]);
				i++;
			}
		}
		swap(a[i],a[r]);
		cswap(&s[i],&s[r]);
		//q=i(return);
		if(i-p>=2)	quicksort(a,s,p,i-1);
		if(r-i>=2)	quicksort(a,s,i+1,r);
	}
}

