    long n2=r-mid;
    vector<pair<char,long> > L(n1);
    vector<pair<char,long> > R(n2);
    for(long i=0;i<n1;i++) L.at(i)=a.at(p+i);
    for(long i=0;i<n2;i++) R.at(i)=a.at(mid+i);
    pair<char, long> data('a',mod);
    L.push_back(data);
    R.push_back(data);
    long i=0;
    long j=0;
    for(long k=p;k<r;k++) {
        if(L.at(i).second<=R.at(j).second){
            a.at(k)=L.at(i);
            i++;
        }
        else{
            a.at(k)=R.at(j);
            j++;
        }
    }
    return;
}

