    if(p+1<r){
        long mid=(p+r)/2;
        mergesort(a,p,mid);
        mergesort(a,mid,r);
        merge(a,p,mid,r);
    }
}


long partition(vector<pair<char,long> > &a,long p,long r){
    long i=p-1;
    for(long j=p;j<r;j++){
        if(a.at(j).second<=a.at(r).second) {
            i++;
            swap(a.at(i),a.at(j));
        }
    }
    swap(a.at(r),a.at(i+1));
    return i+1;
}

void quick(vector<pair<char,long> > &a,long f,long r){
    if(f<r){
        long mid=partition(a,f,r);
        quick(a,f,mid-1);
        quick(a,mid+1,r);
    }
}

