using namespace std;

int Partition(int A[],char B[],int p,int r){
    int x = A[r];
    int i = p-1;
    FOR(j,p,r){
        if(A[j] <= x){
            i = i+1;
            swap(A[i],A[j]);
            swap(B[i],B[j]);
        }
    }
    swap(A[i+1],A[r]);
    swap(B[i+1],B[r]);
    return i+1;
}

void Quicksort(int A[100001],char B[100001],int p,int r){
    if( p < r){
        int q = Partition(A,B,p,r);
        Quicksort(A,B,p,q-1);
        Quicksort(A,B,q+1,r);
    }
}

void insertionSort(int A[100001],char B[100001],int n){
    FOR(i,1,n){
        int pos = i;
        while(A[pos-1] > A[pos] && pos > 0){
            swap(A[pos-1],A[pos]);
            swap(B[pos-1],B[pos]);
            pos--;
        }
    }
}

bool isStable(char A[100001],char B[100001],int n){
    REP(i,n){
        if(A[i] != B[i]) return false;
    }
    return true;
}

int temp[100001];
char ctemp[100001];
void merge(int A[100001],char B[100001],int l,int r){
    if(l >= r ) return;

    int i,j,k;
    int m = (l+r)/2;
    merge(A,B,l,m);
    merge(A,B,m+1,r);

    for(i = l;i <= m ;i++){
        temp[i] = A[i];
        ctemp[i] = B[i];
    }
    for(i=m+1,j=r;i<=r;i++,j--){
        temp[i] = A[i];
        ctemp[i] = B[i];
    }
    i = l;
    j = r;
    for(k=l;k<=r;k++){
        if(temp[i]<=temp[j]){
            A[k] = temp[i];
            B[k] = ctemp[i++];
        }else{
            A[k] = temp[j];
            B[k] = ctemp[j--];
        }
    }

}

