		merge(a,c,left,mid,right);
	}
}

int partition(vector<int>&a,vector<char>&c,int p,int r){
	int x=a.at(r),i=p-1;
	for(int j=p;j<r;++j){
		if(a.at(j)<=x){
			swap(a.at(++i),a.at(j));
			swap(c.at(i),c.at(j));
		}
	}
	swap(a.at(++i),a.at(r));
	swap(c.at(i),c.at(r));
	return i;
}

void quicksort(vector<int>&a,vector<char>&c,int p,int r){
	if(p<r){
		int q=partition(a,c,p,r);
		quicksort(a,c,p,q-1);
		quicksort(a,c,q+1,r);
	}
}

