		if(cards[j].number<=cards[r].number){
			i++;
			t=cards[i];
			cards[i]=cards[j];
			cards[j]=t;
		}	
	}
	t=cards[i+1];
	cards[i+1]=cards[r];
	cards[r]=t;
	return i+1;
}

void QuickSort(struct Card cards[],int n, int p, int r){
	int q;
	if(p<r){
		q=partition(cards,n,p,r);
		QuickSort(cards,n,p,q-1);
		QuickSort(cards,n,q+1,r);
	}
}

