        L[i] = A[left + i];
    }
    for (int i = 0; i < n2; i++) {
        R[i] = A[mid + i];
    }

    L[n1].key = MAX_VAL;
    R[n2].key = MAX_VAL;

    int i = 0, j = 0;
    for (int k = left; k < right; k++) {
        if (L[i].key <= R[j].key) {
            A[k] = L[i];
            i++;
        } else {
            A[k] = R[j];
            j++;
        }
    }
    delete[] L;
    delete[] R;
    return right - left;
}

int mergeSort(Card* A, const int& left, const int& right) {
    int count = 0;
    if (left + 1 < right) {
        const int mid = (left + right) / 2;
        count += mergeSort(A, left, mid);
        count += mergeSort(A, mid, right);
        return count + merge(A, left, mid, right);
    }
    return 0;
}


