    }
}

void Marge(tCard c[], int left, int mid, int right){
    int n1 = mid - left;
    int n2 = right - mid;
    tCard L[n1], R[n2];
    int i, j, k;

    for(i = 0; i < n1; i++){
        L[i] = c[left+i];
    }
    for(i = 0; i < n2; i++){
        R[i] = c[mid+i];
    }

    L[n1].num = INFTY;
    R[n2].num = INFTY;
    i=0; j=0;

    for(k = left; k < right; k++){
        if(L[i].num <= R[j].num){
            c[k] = L[i];
            i++;
        }
        else{
            c[k] = R[j];
            j++;
        }
    }
}

void MargeSort(tCard c[], int left, int right){
    if(left + 1 < right){
        int mid = (left + right) / 2;
        MargeSort(c, left, mid);
        MargeSort(c, mid, right);
        Marge(c, left, mid, right);
    }
}

