    vector<pair<char,int>> L(n1+1);
    for(int i=0; i<n1; ++i){
        L[i] = A[left+i];
    }
    vector<pair<char,int>> R(n2+1);
    for(int i=0; i<n2; ++i){
        R[i] = A[mid+i];
    }
    L[n1].second = INF;
    R[n2].second = INF;
    int i=0;
