typedef pair<int, string> P;

void exchange(vector<P> &v, int a, int b) {
    P temp = v[a];
    v[a] = v[b];
    v[b] = temp;
}

int partition(vector<P> &v, int p, int r) {
    int x = v[r].first;
    int i = p-1;
    for (int j = p; j < r; j++) {
        if (v[j].first <= x) {
            i++;
            exchange(v, i, j);
        }
    }
    exchange(v, i+1, r);
    return i+1;
}

bool stable(vector<P> v, vector<P> w) {
    REP(i,v.size()) {
        if (v[i].first != w[i].first || v[i].second != w[i].second) return false;
    }
    return true;
}

void quicksort(vector<P> &v, int p, int r) {
    if (p < r) {
        int q = partition(v, p, r);
        quicksort(v, p, q-1);
        quicksort(v, q+1, r);
    }
}

