#define MAX 100000
#define SENTINEL 2000000000
Card L[MAX/2+2],R[MAX/2+2];
void merge(Card *a,int n, int l,int mid,int r) {
    int n1=mid-l;
    int n2=r-mid;
    rep(i,n1) L[i]=a[l+i];
    rep(i,n2) R[i]=a[mid+i];
    L[n1]=SENTINEL;
    R[n2]=SENTINEL;
    int i,j;
    i=j=0;
    for(int k=l;k<r;k++) {
        if(L[i]<=R[j]) a[k]=L[i++];
        else a[k]=R[j++];
    }
}
void merge_sort(Card *a,int n,int l,int r) {
    if(l+1<r) {
        int mid=(l+r)/2;
        merge_sort(a,n,l,mid);
        merge_sort(a,n,mid,r);
        merge(a,n,l,mid,r);
    }
}
int partition(Card *a,int p,int r) {
    int i,j;
    Card x;
    x=a[r];
    i=p-1;
    for(int j=p;j<r;j++) {
        if(a[j]<=x) {
            i++;
            swap(a[i],a[j]);
        }
    }
    swap(a[i+1],a[r]);
    return i+1;
}

void quick_sort(Card *a,int n,int p,int r) {
    int q;
    if(p < r) {
        q = partition(a,p,r);
        quick_sort(a,n,p,q-1);
        quick_sort(a,n,q+1,r);
    }
}

