};

int partition(vector<card> &A, int p, int r) {
    int x = A.at(r).num;
    int i = p - 1;
    for (int j = p; j < r; ++j) {
        if (A.at(j).num <= x) {
            ++i;
            swap(A.at(i), A.at(j));
        }
    }
    swap(A.at(i + 1), A.at(r));
    return i + 1;
}

void quickSort(vector<card> &A, int p, int r) {
    if (p < r) {
        int q = partition(A, p, r);
        quickSort(A, p, q - 1);
        quickSort(A, q + 1, r);
    }
    return;
}

