int partition(Card A[], int p, int r)
{
	int i = p - 1;
	int x = A[r].value;
	for (p; p <= r; p++)
	{
		if (A[p].value <= x)
		{
			swap(A[++i], A[p]);
		}
	}
	return i;
}

void quicksort(Card A[], int left, int right)
{
	if (right - left > 1)
	{
		int mid = partition(A, left, right);
		quicksort(A, left, mid - 1);
		quicksort(A, mid + 1, right);

	}
}

int isstable(Card A[], Card B[], int N)
{
	for (int i = 0; i < N; i++)
	{
		//int flag = 0;
		for (int j = 0; j < N; j++)
		{
			if (B[j].value == A[i].value&&B[j].suit != A[i].suit)
				return 1;
			else if (B[j].value == A[i].value&&B[j].suit == A[i].suit)
			{
				for (int s = j + 1; s < N; s++)
