        int mid = (left + right) / 2;
        mergesort(A, n, left, mid);
        mergesort(A, n, mid, right);
        merge(A, n, left, mid, right);
    }
}

int partition(Card A[], int p, int r) {
    Card x = A[r];
    int i = p - 1;
    for (int j  = p; j < r; j++) {
        if (A[j].val <= x.val) {
            i++;
            swap(A[i], A[j]);
        }
    }
    swap(A[i + 1], A[r]);
    return i + 1;
}

