void merge(Card A[],int n,int left,int mid, int right) {
  int n1=mid-left;
  int n2=right-mid;
  for (int i=0; i<n1; i++) {
    L[i]=A[left+i];
  }
  for (int i=0; i<n; i++) {
    R[i]=A[mid+i];
  }
  L[n1].value=R[n2].value=SENTNEL;
  int i=0, j=0;
  for (int k=left; k<right; k++) {
    if (L[i].value<=R[j].value) {
      A[k]=L[i++];
    } else {
      A[k]=R[j++];
    }
  }
}
void mergeSort(Card A[],int n,int left,int right) {
  int mid;
  if(left+1<right) {
    mid=(left+right)/2;
    mergeSort(A,n,left,mid);
    mergeSort(A,n,mid,right);
    merge(A,n,left,mid,right);
  }
}
int partition(Card A[],int n,int p,int r) {
  Card t, x;
  x=A[r];
  int i=p-1;
  for (int j=p; j<r; j++) {
    if (A[j].value<=x.value) {
      i++;
      t=A[i];
      A[i]=A[j];
      A[j]=t;
    }
  }
  t=A[i+1];
  A[i+1]=A[r];
  A[r]=t;
  return i+1;
}
void quickSort(Card A[],int n,int p,int r) {
  if (p<r) {
    int q=partition(A,n,p,r);
    quickSort(A,n,p,q-1);
