	int i=p-1;
	for(int j=p;j<=r-1;j++){
		if(A[j]<=x){
			i++;
			swap(A[i],A[j]);
			swap(B[i],B[j]);
		}
	}
	swap(A[i+1],A[r]);
	swap(B[i+1],B[r]);
	return i+1;
}

void Quicksort(int A[],char B[],int p,int r){
	if(p<r){
		int q=Partition(A,B,p,r);
		Quicksort(A,B,p,q-1);
		Quicksort(A,B,q+1,r);
	}
	return;
}

