  Card card1,card2;
  card2 = pre[r];
  i = p-1;
  for(j = p; j < r; j++){
    if(pre[j].num <= card2.num){
      i++;
      card1 = pre[i];
      pre[i] = pre[j];
      pre[j] = card1;
    }
  }
  card1 = pre[i+1];
  pre[i+1] = pre[r];
  pre[r] = card1;
  return i+1;
}


void quickSort(Card pre[],int n, int p, int r){
  int q;
  if(p < r){
    q = partition(pre,n,p,r);
    quickSort(pre,n,p,q-1);
    quickSort(pre,n,q+1,r);
  }
}

