  uint n;
  std::cin >> n;
  Card cards[n];
  for (uint i = 0; i < n; ++i) {
    cards[i].index = i;
    std::cin >> cards[i];
  }

  quick_sort(cards, 0u, n);

  if (is_stable(cards, n)) {
    std::cout << "Stable" << std::endl;
  } else {
    std::cout << "Not stable" << std::endl;
  }
  print_cards(cards, n);

  return 0;
}

