int partition1(vector<SSS> &data, int p, int r){
	int p1 = p - 1;
	int p2 = p;
	SSS v = data[r];

	while (p2 < r) {
		if (data[p2].val <= v.val)
			swap(data[++p1], data[p2]);
		p2++;
	}
	swap(data[++p1], data[r]);

	return p1;
}

int partition2(vector<SSS> &data, int l, int r){
	SSS tmp = data[r];
	while (l < r) {
		while (l < r && data[l].val <= tmp.val) l++;
		if (l >= r) break;
		data[r--] = data[l];

		while (l < r && data[r].val >= tmp.val) r--;
		if (l >= r) break;
		data[l++] = data[r];
	}
	data[r] = tmp;
	return r;
}

void quickSort(vector<SSS> &data, int l, int r){
	if (l < r){
		int pos = partition1(data, l, r);
		quickSort(data, l, pos - 1);
		quickSort(data, pos + 1, r);
	}
}



