void merge(Card A[], int left, int mid, int right)
{
	int len1 = mid - left + 1;
	Card *L = new Card[len1];
	for (int i = 0; i < len1; i++)
	{
		L[i] = A[left + i];
	}
	int len2 = right - mid;
	Card *R = new Card[len2];
	for (int i = 0; i < len2; i++)
	{
		R[i] = A[mid + 1 + i];
	}

	int k = mid, i = 0, j = 0;
	while (i < len1 && j < len2)
	{
		if (L[i].value <= R[j].value)
		{
			A[k++] = L[i++];
		}
		else
		{
			A[k++] = R[j++];
		}
	}
	while (i < len1)
	{
		A[k++] = L[i++];
	}
	while (j < len2)
	{
		A[k++] = R[j++];
	}

	delete[] L;
	delete[] R;
}

