}

int partition(Card A[], int p, int r)
{
	int i = p - 1;
	for (int j = p; j < r; j++)
	{
		if (A[j].value <= A[r].value)
		{
			i++;
			Card temp = A[j];
			A[j] = A[i];
			A[i] = temp;
		}
	}
	Card temp = A[r];
	A[r] = A[i + 1];
	A[i + 1] = temp;
	return i + 1;
}

void quicksort(Card A[], int p, int r)
{
	if (p < r)
	{
		int q = partition(A, p, r);
		quicksort(A, p, q - 1);
		quicksort(A, q + 1, r);
	}
}

