    int x = C[r].number;
    int i = p - 1;

    for (int j = p; j < r; j++) {
        if (C[j].number <= x) {
            i += 1;
            // swap
            Card val_i = C[i];
            C[i] = C[j];
            C[j] = val_i;
        }
    }
    i += 1;
    // swap
    Card val_i = C[i];
    C[i] = C[r];
    C[r] = val_i;
    return i;
}

void QuickSort(Card *C, int p, int r)
{
    if (p < r) {
        int q = Partition(C, p, r);
        QuickSort(C, p, q-1);
        QuickSort(C, q+1, r);
    }
}

