std::string CheckStable( const std::vector<std::pair<char, int>>& initial, const std::vector<std::pair<char, int>>& sorted ){
    int N = sorted.size();
    for( int i = 0; i < N; ++i ){
        for( int j = i+1; j < N; ++j ){
            for( int a = 0; a < N; ++a ){
                for( int b = a+1; b < N; ++b ){
                    if( initial[i].second == initial[j].second &&
                        initial[i] == sorted[b] &&
                        initial[j] == sorted[a] ){
                        return "Not stable";
                    }
                }
            }
        }
    }
    return "Stable";
}

