  L[nl].num = SENTINEL; R[nr].num = SENTINEL;
  for(int i=0;i<nl;i++) L[i] = A[left+i];
  for(int i=0;i<nr;i++) R[i] = A[mid +i];
  int il=0; int ir=0;
  for(int i=left;i<right;i++){
    if(L[il].num <= R[ir].num){
