int Partition(std::vector<Card>& List, int p, int r)
{
    int x = List[r].Value;
    int i = p - 1;
    Card Temp;

    for(int j = p; j < r; j++){
        if(List[j].Value <= x){
            i++;
            Temp    = List[i];
            List[i] = List[j];
            List[j] = Temp;
        }
    }
    Temp    = List[i + 1];
    List[i + 1] = List[r];
    List[r] = Temp;

    return i + 1;
}

void Quicksort(std::vector<Card>& List, int p, int r)
{
    if(p < r){
       int q = Partition(List, p, r);

       Quicksort(List, p, q - 1);
       Quicksort(List, q + 1, r);
    }
}

string IsStable(vector<Card> Org, vector<Card> After)
{
    for(int i = 0; i < Org.size(); i++){
        for(int j = i + 1; j < Org.size(); j++){
            for(int a = 0; a < Org.size(); a++){
                for(int b = a + 1; b < Org.size(); b++){
                    if(Org[i].Value == Org[j].Value && Org[i].Name == After[b].Name 
                    && Org[i].Value == After[b].Value && Org[j].Name == After[a].Name
                    && Org[j].Value == After[a].Value){
                        return "Not stable";
                    }
                }
            }
        }
    }
    return "Stable" ;
}

