struct Card{
    int index;
    char ch;
    int num;
};

void swap(Card c[], int i, int j){
    Card temp = c[i];
    c[i] = c[j];
    c[j] = temp;
}

int partion(Card c[], int low, int high){
    Card x = c[high];
    int i = low - 1;
    for (int j = low; j < high; ++j) {
        if (c[j].num <= x.num){
            ++i;
            swap(c, i, j);
        }
    }
    swap(c, i+1, high);
    return i+1;
}

int quickSort(Card c[], int low, int high){
    if (low < high){
        int index = partion(c, low, high);
        quickSort(c, low, index-1);
        quickSort(c, index+1, high);
    }
}

