    cin >> c >> x;
    vp.push_back(make_pair(c, x));

    if (!m.count(x)) m[x] = queue<char>();
    m[x].push(c);
  }

  quick_sort(vp, 0, n - 1);

  cout << (is_stable(m, vp) ? "Stable" : "Not stable") << endl; 

  for (auto p: vp) printf("%c %d\n", p.first, p.second);
}

