#define INF 1.0e9

void merge(vector<pair<char,int>> &A, int left, int mid, int right){
    int n1 = mid-left;
    int n2 = right - mid;
    vector<pair<char,int>> L(n1+1);
    for(int i=0; i<n1; ++i){
        L[i] = A[left+i];
    }
    vector<pair<char,int>> R(n2+1);
    for(int i=0; i<n2; ++i){
        R[i] = A[mid+i];
    }
    L[n1].second = INF;
    R[n2].second = INF;
    int i=0;
    int j=0;
    for(int k=left; k<right; ++k){
        if( L[i].second < R[j].second ){
            A[k] = L[i];
            ++i;

        }else{
            A[k] = R[j];
            ++j;
        }
    }
    return;
}

void mergesort(vector<pair<char,int>> &A, int left, int right){
    if( left+1 < right ){
        int mid = (left+right)/2;
        mergesort(A, left, mid);
        mergesort(A,mid,right);
        merge(A, left, mid, right);
    }

    return;
}


int partition(vector<pair<char,int>> &A, int p, int r){
    int x = A[r].second;
    int i = p-1;
    for(int j=p; j<=r-1; ++j){
        if(A[j].second <= x ){
            i = i+1;
            swap(A[i],A[j]);
        }
    }
    swap(A[i+1],A[r]);

    return i+1;
}

void quicksort(vector<pair<char,int>> &A, int p, int r){

    if( p<r ){
        int q = partition(A,p,r);
        quicksort(A,p,q-1);
        quicksort(A,q+1,r);
    }

}


