	int p1(l), p2(m);
	while (p1 < m && p2 < r) {
		if (tmp[p1][1] < tmp[p2][1]) data[l++] = tmp[p1++];
		else data[l++] = tmp[p2++];
	}
	while (p1 < m) data[l++] = tmp[p1++];
	while (p2 < r) data[l++] = tmp[p2++];
}

void mergeSort(vector<string> &data, int l, int r){
	if (l + 1 < r){
		int m = l + (r - l) / 2;
		mergeSort(data, l, m);
		mergeSort(data, m, r);
		merge(data, l, m, r);
	}
}




