int partition(vector<int>& A,vector<char>& C,int p,int r) {
  int x = A[r];
  int i = p - 1;
  for(int j=p;j<r;j++) {
    if(A[j] <= x) {
      i++;
      swap(A[i],A[j]);
      swap(C[i],C[j]);
    }
  }
  swap(A[i+1],A[r]);
  swap(C[i+1],C[r]);
  return i+1;
}
void quick_sort(vector<int>& A,vector<char>& C,int p,int r) {
  if(p < r) {
    int q = partition(A,C,p,r);
    quick_sort(A,C,p,q-1);
    quick_sort(A,C,q+1,r);
  }
}

