template<typename T> 
void buble_sort(int n, T ar[]){
    bool next = true;
    while (next) {
        next = false;
        for (int i = 0; i < n - 1; i++) {
            if(ar[i] > ar[i+1]){
                swap(ar[i], ar[i+1]);
                next = true;
            }
        }
    }
}

template<typename T>
int partition(T ar[], int p, int r){
    T pivot = ar[r];
    int i = p - 1;
    for (int j = p; j <= r - 1; j++) {
        if(ar[j] <= pivot){
            i++;
            swap(ar[i], ar[j]);
        }
    }
    i++;
    swap(ar[i], ar[r]);
    return i;
}

template<typename T>
void quicksort(T ar[], int p, int r){
    if(p < r){
        int q = partition(ar, p, r);
        quicksort(ar, p, q - 1);
        quicksort(ar, q + 1, r);
    }
}

