    for(int j = p; j < r; j++) {
        if(x >= A[j].num) {
            i++;
            swap(A[i], A[j]);
        }
    }
    swap(A[i + 1], A[r]);
    return i + 1;
}

void quickSort(Card A[], int p, int r) {
    if(p < r) {
        int x = partition(A, p, r);
        quickSort(A, p, x - 1);
        quickSort(A, x + 1, r);
    }
}

void merge(Card A[], int left, int mid, int right) {
    int n1 = mid - left;
    int n2 = right - mid;
    Card L[n1 + 1], R[n2 + 1];
    for (int i = 0; i < n1; i++) L[i] = A[left + i];
    for (int i = 0; i < n2; i++) R[i] = A[mid + i];
    L[n1].num = INT_MAX;
    R[n2].num = INT_MAX;
    int l = 0, r = 0;
    for (int i = left; i < right; i++) {
        if (L[l].num <= R[r].num) A[i] = L[l++];
        else A[i] = R[r++];
    }
}

