	int n2 = right - mid;
	for( i = 0; i<n1; i++)	L[i] = A[i+left];
	for( i = 0; i<n2; i++)	R[i] = A[i+mid];
	L[n1].value = R[n2].value = SENTINEL;
	i = j = 0;
	for( k = left; k < right; k++ )
	{
		if (L[i].value<=R[j].value)
		{
			A[k] = L[i++];
		}
		else 
		{
			A[k] = R[j++];
		}
	}
}

void mergeSort( card A[], int n, int left, int right)
{
	int mid;
	if(left + 1 < right)
	{
		mid = (left + right)/2;
		mergeSort(A, n, left, mid);
		mergeSort(A, n, mid, right);
		merge(A, n, left, mid, right);
	}
}

int partition(card A[], int n, int p, int r)
{
	int i, j;
	card t, x;
	x = A[r];
	i = p-1;
	for(j = p; j < r; j++)
	{
		if (A[j].value <= x.value)
		{
			i++;
			t = A[i];
			A[i] = A[j];
			A[j] = t;
		}
	}
	t = A[r];
	A[r] = A[i+1];
	A[i+1] = t;
	return i+1;
}

void quickSort( card A[], int n, int p, int r)
{
	int q;
	if(p<r)
	{
		q = partition(A, n, p, r);
		quickSort(A, n, p, q-1);
		quickSort(A, n, q+1, r);
	}
}

