int partition(char* M, int* A, int p, int r) {
    int div = A[r], i=p;
    for (int j=p; j<=r; j++) {
        if (A[j] <= div) {
            i++;
            swap(M, A, i-1, j);
        }
    }
    return i-1;
}

void quick(char* M, int* A, int p, int r) {
    if (p < r) {
        int q = partition(M, A, p, r);
        quick(M, A, p, q-1);
        quick(M, A, q+1, r);
    }
}

