template<class T>
int Partition(std::vector<T> & A, int p,int r)
{
	T x = A[r];
	int i = p-1;
	for (int j = p; j <=r-1;++j) {
		if (A[j].value <= x.value) {
			i = i+1;
			swap(A[i],A[j]);
		}
	}
	swap(A[i+1],A[r]);
	return i+1;
}
template<class T>
void QuickSort(std::vector<T> & A, int p,int r)
{
	if (p < r) {
		int q = Partition(A, p, r);
		QuickSort(A,p,q-1);
		QuickSort(A,q+1,r);
	}
}

