void quickSort(Card *a, int p, int r) {

    if(p < r) {

        int j = p-1;
        for(int i = p; i < r; i++) {
            if(a[i].number <= a[r].number) {
                j++;
                if(i != j) {
                    Card temp = a[i];
                    a[i] = a[j];
                    a[j] = temp;
                }
            }
        }
        Card tmp = a[j+1];
        a[j+1] = a[r];
        a[r] = tmp;

        int q = j+1;
        quickSort(a, p, q-1);
        quickSort(a, q+1, r);
    }
}

