vector<Card> ns;
map<int,vector<int>> idxs;

int partition(int p, int r)
{
  auto x = ns[r];
  int i = p-1;
  for (int j=p; j<r; ++j) {
    if (ns[j].rank <= x.rank) {
      ++i;
      swap(ns[i], ns[j]);
    }
  }
  swap(ns[i+1], ns[r]);
  return i+1;
}

void sort(int p, int r) {
  if(p<r) {
    int q = partition(p, r);
    sort(p, q-1);
    sort(q+1, r);
  }
}

