int partition(vector<int> &A, vector<int> &I, vector<char> &S, int p, int r)
{
	int x = A[r];
	int i = p - 1;
	for(int j = p; j < r; ++j) {
		if(A[j] <= x) {
			++i;
			swap(A[i], A[j]);
			swap(S[i], S[j]);
			swap(I[i], I[j]);
		}
	}
	swap(A[i + 1], A[r]);
	swap(S[i + 1], S[r]);
	swap(I[i + 1], I[r]);
	return i + 1;
}

void QuickSort(vector<int> &A, vector<int> &I, vector<char> &S, int p, int r)
{
	if(p < r) {
		int q = partition(A, I, S, p, r);
			QuickSort(A, I, S, p, q - 1);
			QuickSort(A, I, S, q + 1, r);
	}
}

bool isStable(vector<int> &A, vector<int> &I, int n)
{
	REP(i, n - 1) {
		if(A[i] == A[i + 1] && I[i] > I[i + 1])
			return false;
	}

	return true;
}

