int partition(vector<int> &A,vector<char> &B,vector<int> &C,int p,int r){ 
		int x = A[r];
		int i = p - 1;

		for (int j = p; j < r; j++){
				if (A[j] <= x){ 
						i++;
						int itmp = A[i];
						A[i] = A[j];
						A[j] = itmp;
						char ctmp = B[i];
						B[i] = B[j];
						B[j] = ctmp;
						int iitmp = C[i];
						C[i] = C[j];
						C[j] = iitmp;
				}   
		}   

		int itmp = A[i+1];
		A[i+1] = A[r];
		A[r] = itmp;
		char ctmp = B[i+1];
		B[i+1] = B[r];
		B[r] = ctmp;
		int iitmp = C[i+1];
		C[i+1] = C[r];
		C[r] = iitmp;

		return i+1;
}

void quicksort(vector<int> &A,vector<char> &B,vector<int> &C,int p,int r){
	if (p < r){
		int q = partition(A,B,C,p,r);
		quicksort(A,B,C,p,q-1);
		quicksort(A,B,C,q+1,r);
	}
}

