int partition(Card A[], int p, int r){
	int x = A[r].num, i = p - 1;
	Card tmp;
	FOR(j, p, r){
		if (A[j].num <= x){
			i++;
			tmp = A[i];
			A[i] = A[j];
			A[j] = tmp;
		}
	}
	tmp = A[i + 1];
	A[i + 1] = A[r];
	A[r] = tmp;
	return i + 1;
}

/*
1 quicksort(A, p, r)
2   if p < r
