    int n2 = right - mid;//右半分(正確に2等分ではない)
    for(i=0;i<n1;i++){
        L[i]=A[left + i];//左部分に要素を追加
    }
    for(i=0;i<n2;i++){
        R[i]=A[mid + i];//右部分に要素を追加
    }
    L[n1].value=R[n2].value=SENTINEL;
    i=j=0;
    for(k=left;k<right;k++){
        if(L[i].value<=R[j].value){//任意に定めた数字より小さい時
            A[k]=L[i++];
        }else{//任意の定めた数字より大きい時
            A[k]=R[j++];
        }
    }
}

