    }
}

int partition(struct Card A[], int n, int p, int r){
    int i,j;
    struct Card t,x;
    x=A[r];
    i=p-1;
    for(j=p;j<r;j++){
        if(A[j].value <= x.value){//要素同士で大小関係の比較
            i++;
            t=A[i]; A[i]=A[j]; A[j]=t;//値を入れ替える
        }
    }
    t=A[i+1]; A[i+1]=A[r]; A[r]=t;//処理速度を高速化するためにfor文にの外に出す
    return i+1;//int型だから返り値必要
}

