    rep(i, n1) l[i] = a[left + i];
    rep(i, n2) r[i] = a[i + mid];
    l[n1] = make_pair('s', SENTINEL);
    r[n2] = make_pair('s', SENTINEL);
    int i = 0, j = 0;
