  int n = (int)A.size();

  if(n <= 1) return;

  vector<P> L(A.begin(), A.begin() + n / 2);
  vector<P> R(A.begin() + n / 2, A.end());

  MergeSort(L);
  MergeSort(R);

  int l = (int)L.size(), r = (int)R.size();
  for(int i = 0,j = 0,k = 0 ; i < n ; i++){
    if(k == r){
      A[i] = L[j++];
    }else if(j == l){
      A[i] = R[k++];
    }else if(L[j].second <= R[k].second){
      A[i] = L[j++];
    }else{
      A[i] = R[k++];
    }
  }
}

