void marge(Card A[],int left,int mid,int right){
	int n1 = mid - left;
	int n2 = right - mid;
	int L[n1+1],R[n2+1];
	for(int i = 0;i < n1;i++){
		L[i] = A[left+i].num;
	}
	for(int j = 0;j < n2;j++){
		R[j] = A[mid+j].num;
	}
	L[n1] = 1000000001;
	R[n2] = 1000000001;
	int i = 0;int j = 0;
	for(int k = left;k < right;k++){
		if(L[i] <= R[j]){
			A[k].num = L[i];
			i++;
		}else{
			A[k].num = R[j];
			j++;
		}
	}
}

void margesort(Card A[],int left,int right){
	if(left + 1 < right){
		int mid = (left + right)/2;
		margesort(A,left,mid);
		margesort(A,mid,right);
		marge(A,left,mid,right);
	}
}

int partition(Card A[],int p,int r){
	int i = p;
	for(int j = p;j < r;j++){
		if(A[j].num <= A[r].num){
			swap(A[j],A[i]);
			i++;
		}
	}
	swap(A[r],A[i]);
	return i;
}

void quicksort(Card A[],int p,int r){
	if(p < r){
		int q = partition(A,p,r);
		quicksort(A,p,q-1);
		quicksort(A,q+1,r);
	}
}
