	merge(A,l,mid,r);
}

int partition(Card *A,int p,int r)
{
	int j=p;
	Card t;
	for (int i = p; i < r-1; ++i)
	{
		if (A[i].value<=A[r-1].value)
		{
			t=A[i];
			A[i]=A[j];
			A[j++]=t;
		}
	}
	t=A[j];
	A[j]=A[r-1];
	A[r-1]=t;
	return j;
}

void quickSort(Card *A,int p,int r)
{
	if (r<=p)
	{
		return;
	}

	int pivot=partition(A,p,r);
	quickSort(A,p,pivot);
	quickSort(A,pivot+1,r);
}

