struct Card {
	char suit;
	ll number;
};

// p < r < A.size()
// after this operation: p,...,q-1, q, q+1, ..., r
// A[p],...,A[q-1] <= A[q]
// A[q] < A[q+1], ..., A[r]
// returns q
// r = p+1であれば, かならず整列される.
//
ll Partition(vector<Card> &A, ll p, ll r, bool &is_stable) {
	Card x = A[r];// pivot 
	ll i = p-1;
	for (ll j=p; j<r; ++j) {
		if (A[j].number <= x.number) {
			if ( (i+1 != j) && A[j].number == x.number && A[j].suit != x.suit) {
				is_stable = false;
			}
			i++;
			Card t = A[j];
			A[j] = A[i];
			A[i] = t;
		}
	}
	A[r] = A[i+1];
	A[i+1] = x; 
	return i+1;
}

void QuickSort(vector<Card> &A, ll p, ll r, bool &is_stable) {
	if (p < r) {
		ll q = Partition(A, p, r, is_stable);
		QuickSort(A, p, q-1, is_stable);
		QuickSort(A, q+1, r, is_stable);
	}
}

