			swap(data[++p1], data[p2]);
		p2++;
	}
	swap(data[++p1], data[r]);

	return p1;
}

int partition2(vector<string> &data, int l, int r){
	string tmp = data[r];
	while (l < r) {
		while (l < r && data[l][1] <= tmp[1]) l++;
		if (l >= r) break;
		data[r--] = data[l];

		while (l < r && data[r][1] >= tmp[1]) r--;
		if (l >= r) break;
		data[l++] = data[r];
	}
	data[r] = tmp;
	return r;
}

