using namespace std;
struct Card {
  int rank;
  char suit;
};

vector<Card> ns;
bool stable = true;

int partition(int p, int r)
{
  auto x = ns[r];
  int i = p-1;
  int max_swapped=p-1;  // greatest index to which we've swapped
                        // r's value
  for (int j=p; j<r; ++j) {
    if (ns[j].rank <= x.rank) {
      ++i;
      // swapping same value from earlier index to later index
      if(i!=j and ns[i].rank == ns[j].rank)
        stable=false;
      // swapping value appearing before A[r] *after* where
      // we place A[r] -- not stable if greater than i+1
      if(ns[i].rank==x.rank) max_swapped=j;
      swap(ns[i], ns[j]);
    }
  }
  if(i!=r-1 and ns[i+1].rank==ns[r].rank) stable=false;
  swap(ns[i+1], ns[r]);
  if(max_swapped>i+1) stable=false;
  return i+1;
}

void sort(int p, int r) {
  if(p<r) {
    int q = partition(p, r);
    sort(p, q-1);
    sort(q+1, r);
  }
}

