{
  int n; cin >> n;
  for(int i=0; i<n;++i) {
    Card c;
    cin >> c.suit;
    cin >> c.rank;
    ns.push_back(c);
  }
  sort(0, n-1);
  if(stable) cout << "Stable" << endl;
  else cout << "Not stable" << endl;
  for(int i=0; i<n; ++i) {
    cout << ns[i].suit << ' ' << ns[i].rank << endl;
  }
}

