	int index1 = 0,index2 = 0;
	Card * L = new Card[n1];
	Card * R = new Card[n2];
	for (int i = left;i<right;i++) {
		if (i < m) {
			L[index1++] = arr[i];
		} else {
			R[index2++] = arr[i];
		}
	}
	index1 = 0;
	index2 = 0;
	for (int i = left;i<right;i++) {
		if (index1 >= n1) {
			arr[i] = R[index2++];
		} else if (index2 >= n2) {
			arr[i] = L[index1++];
		} else {
			if (L[index1].val <= R[index2].val) {
				arr[i] = L[index1++];
			} else {
				arr[i] = R[index2++];
			}
		} 
	}
	delete[] L;
	delete[] R;

}

void mergeSort(Card *arr,int left,int right) {
	if (right - left > 1) {
		int m = (left + right) / 2;
		mergeSort(arr,left,m);
		mergeSort(arr,m,right);
		merge(arr,left,m,right); 
	} 
}

