using namespace std;

class Card{
public:
	char suit;
	int num;
};

int n;

void marge(Card A[],int left,int mid,int right){
	int n1 = mid - left;
	int n2 = right - mid;
	int L[n1+1],R[n2+1];
	for(int i = 0;i < n1;i++){
		L[i] = A[left+i].num;
	}
	for(int j = 0;j < n2;j++){
		R[j] = A[mid+j].num;
	}
	L[n1] = 1000000001;
	R[n2] = 1000000001;
	int i = 0;int j = 0;
	for(int k = left;k < right;k++){
		if(L[i] <= R[j]){
			A[k].num = L[i];
			i++;
		}else{
			A[k].num = R[j];
			j++;
		}
	}
}

void margesort(Card A[],int left,int right){
	if(left + 1 < right){
		int mid = (left + right)/2;
		margesort(A,left,mid);
		margesort(A,mid,right);
		marge(A,left,mid,right);
	}
}

int partition(Card A[],int p,int r){
	int i = -1;
	int j = -1;
	for(int k = 0;k < n-1;k++){
		if(A[k].num <= A[r].num){
			if(i == j){
				i++;
				j++;
			}else{
				Card tmp = A[k];
				A[k] = A[i+1];
				A[i+1] = tmp;
				i++;
				j++;
			}
		}else{
			j++;
		}
	}
	Card tmp = A[r];
	A[r] = A[i+1];
	A[i+1] = tmp;
	return i+1;
}

void quicksort(Card A[],int p,int r){
	if(p < r){
		int q = partition(A,0,n-1);
		quicksort(A,p,q-1);
		quicksort(A,q+1,r);
	}
}
int main(){
	char S[10];
	int v;
	bool stable = true;
	cin >> n;
	Card S1[n],S2[n];

	for(int i = 0;i < n;i++){ 
		scanf("%s %d",S,&v);
		S1[i].suit = S2[i].suit = S[0];
		S1[i].num = S2[i].num = v;
	}	

	margesort(S1,0,n);
	quicksort(S2,0,n-1);

	for(int i = 0;i < n;i++){
		if(S1[i].suit != S2[i].suit) stable = false;
	}

	if(stable == false){
		cout << "Not stable" << endl;
	}else{
		cout << "Stable" << endl;
	}
	for(int i = 0;i < n;i++){
		cout << S2[i].suit << " " << S2[i].num << endl;
	}
	return 0;
}

