// クイックソートを実施する関数
// p : 範囲の先頭
// q : 範囲の最後尾
void quickSort(CARD A[], int p, int r)
{
    int q;

    if( p < r )
    {
        // パーティション ソート で, インデックスを求める
        q = partition(A, p, r);
        // 前半の部分配列に対して, クイックソートする
        quickSort(A, p, q - 1);
        // 後半の部分配列に対して, クイックソートする
        quickSort(A, q + 1, r);
    }

    return;
}

// パーティション ソート の実施
// A[r]を基準として, 小さい要素は左側, 大きい要素は右側に並ぶ
// p : 範囲の先頭
// q : 範囲の最後尾
int partition(CARD A[], int p, int r)
{
    int i = 0;
    CARD x, tmp;

    x = A[r];
    i = p - 1;

    for(int j = p; j < r; j++)
    {
        if( A[j].number <= x.number )
        {
            i++;

            // A[i] と A[j]を交換
            tmp = A[i];
            A[i] = A[j];
            A[j] = tmp;
        }
    }

    // A[i + 1] と A[r]を交換
    tmp = A[i + 1];
    A[i + 1] = A[r];
    A[r] = tmp;

    return i + 1;
}

