    for(int j = i+1; j < r; j++){
        if(A[j].value <= x){
            i++;
            swap(A[i], A[j]);
        }
    }
    swap(A[i+1], A[r]);
    return i+1;
}

void quickSort(struct Card A[], int p, int r){
    if(p < r){
        int q = partition(A, p, r);
        quickSort(A, p, q-1);
        quickSort(A, q+1, r);
    }
}

void merge(struct Card A[], int left, int mid, int right){
    int n1 = mid-left;
    int n2 = right-mid;
    struct Card L[n1+1];
    struct Card R[n2+1];
    for(int i = 0; i < n1; i++) L[i] = A[left+i];
