template<typename T> size_t merge(vector<T>& A, int left, int mid, int right) {
	size_t numCmp = 0;
	int n1 = mid - left;
	int n2 = right - mid;
	vector<T> L(n1 + 1), R(n2 + 1);
	for (int i = 0; i < n1; i++)
		L[i] = A[left + i];
	for (int i = 0; i < n2; i++)
		R[i] = A[mid + i];
	L[n1] = R[n2] = numeric_limits<T>::max();
	int i = 0, j = 0;
	for (int k = left; k < right; k++) {
		numCmp++;
		if (L[i] <= R[j]) {
			A[k] = L[i];
			i++;
		}
		else {
			A[k] = R[j];
			j++;
		}
	}
	return numCmp;
}

template<typename T> size_t mergeSort(vector<T>& A, int left, int right) {
	size_t numCmp = 0;
	if (left + 1 < right) {
		int mid = (left + right) / 2;
		numCmp += mergeSort(A, left, mid);
		numCmp += mergeSort(A, mid, right);
		numCmp += merge(A, left, mid, right);
	}
	return numCmp;
}

template<typename T> int partition(vector<T>& A, int p, int r) {
	T x = A[r];
	int i = p - 1;
	for (int j = p; j <= r - 1; j++) {
		if (A[j] <= x) {
			i = i + 1;
			swap(A[i], A[j]);
		}
	}
	swap(A[i + 1], A[r]);
	return i + 1;
}

template<typename T> void quickSort(vector<T>& A, int p, int r) {
	if (p < r) {
		int q = partition(A, p, r);
		quickSort(A, p, q - 1);
		quickSort(A, q + 1, r);
	}
}

