int part(Card* a, int left, int right, bool exchanged, bool& stable) {
   int pivot = right;
   int cur = left - 1;
   for (int i = left ; i <= right - 1; i ++) {   
      if (a[i].val <= a[pivot].val) {
         if (a[i].val == a[pivot].val && exchanged) {
            stable = false;
         }
         cur ++;
         swap(a[i], a[cur]);
      }
   }
   swap(a[pivot], a[cur + 1]);
   return cur + 1;
}
void quickSort(Card* a, int left, int right, bool exchanged, bool& stable) {
   if (left >= right) {
       return;
   }
   int mid = part(a, left, right, exchanged, stable);
   quickSort(a, left, mid - 1, false, stable);
   quickSort(a, mid + 1, right, true, stable);
}
