const int inf = 1000000000;

int part(int a[], char b[], int p, int r) {
	int x = a[r];
	int i = p - 1;
	for (int j = p; j < r; j++) {
		if (a[j] <= x) {
			i += 1;
			swap(a[i], a[j]);
			swap(b[i], b[j]);
		}
	}
	swap(a[i + 1], a[r]);
	swap(b[i + 1], b[r]);
	return i + 1;
}

void qsort(int a[], char b[], int p, int r) {
	if (p < r) {
		int q = part(a, b, p, r);
		qsort(a, b, p, q - 1);
		qsort(a, b, q + 1, r);
	}
}


void merge(int a[], char b[], int l, int m, int r) {
	int n1 = m - l;
	int n2 = r - m;
	int al[n1], ar[n2];
	char bl[n1], br[n2];
	for (int i = 0; i < n1; i++) {
		al[i] = a[l + i];
		bl[i] = b[l + i];
	}
	for (int i = 0; i < n2; i++) {
		ar[i] = a[m + i];
		br[i] = b[m + i];
	}
	al[n1] = inf;
	ar[n2] = inf;
	bl[n1] = 255;
	br[n2] = 255;
	int i = 0, j = 0;
	for (int k = l; k < r; k++) {
		if (al[i] <= ar[j]) {
			a[k] = al[i];
			b[k] = bl[i];
			i += 1;
		} else {
			a[k] = ar[j];
			b[k] = br[j];
			j += 1;
		}
	}
}

void mergesort(int a[], char b[], int l, int r) {
	if (l + 1 < r) {
