	int x = A[r].second;
	int i = p - 1;
	for (int j = p;j < r;j++) {
		if (A[j].second <= x) {
			i++;
			pair<char,int> tmp = A[i];
			A[i] = A[j];
			A[j] = tmp;
		}
	}
	pair<char,int> tmp = A[i + 1];
	A[i + 1] = A[r];
	A[r] = tmp;
	return i + 1;
}

