void comb(Card A[],int left,int mid,int right){
    int n1,n2;
    n1 = mid - left;
    n2 = right - mid;
    for (int i = 0; i < n1; i++) LEFT[i] = A[left + i];
    for (int i = 0; i < n2; i++) RIGHT[i] = A[mid + i];

    LEFT[n1].num = INF;
    RIGHT[n2].num = INF;

    int N = n1 + n2;
    int count_l=0,count_r=0;

