	int x = A[r].x;
	int i = l - 1;
	for(int j=l; j<r; j++) {
		if(A[j].x <= x) {
			i++;
			std::swap(A[i], A[j]);
		}
	}
	std::swap(A[i+1], A[r]);
	return i+1;
}

