int partition(Card c[],int p,int r){
  int x=c[r].value;
  int i=p-1;
  for(int j=p;j<=r-1;j++){
    if(c[j].value<=x){
      i++;
      Card t=c[i];
      c[i]=c[j];
      c[j]=t;
    }
  }
  Card t=c[++i];
  c[i]=c[r];
  c[r]=t;
  return i;
}

void quicksort(Card c[],int p,int r){
  if(p<r){
    int q=partition(c,p,r);
    quicksort(c,p,q-1);
    quicksort(c,q+1,r);
  }
}

