  int n1=mid-left;
  int n2=right-mid;
  Card L[n1+1],R[n2+1];
  for(int i=0;i<n1;i++) L[i]=c[left+i];
  for(int i=0;i<n2;i++) R[i]=c[mid+i];
  L[n1].value=INF; R[n2].value=INF;
  int i=0,j=0;
  for(int k=left;k<right;k++){
    if(L[i].value<=R[j].value){
      c[k]=L[i++];
    }else{
      c[k]=R[j++];
    }
  }
}

