	int l = 0, r = 0;
	for (int k=left; k<right; k++) {
		if (L[l] > R[r]) {
			A[k] = R[r]; S[k] = RS[r]; r++;
		} else {
			A[k] = L[l]; S[k] = LS[l]; l++;
		}
	}
	delete[] L;
	delete[] R;
	delete[] LS;
	delete[] RS;
}

void stable_mergeSort(char* S, int *A, int left, int right)
{
	if (left+1 < right) {
		int mid = (left + right) / 2;
		stable_mergeSort(S, A, left, mid);
		stable_mergeSort(S, A, mid, right);
		stable_merge(S, A, left, mid, right);
	}
}

int partition(char* S, int* A, int p, int r)
{
	int key = A[r];
	int i = p - 1;
	for (int j=p; j<r; j++) {
		if (A[j] <= key) {
			i++;
			swap(A[i], A[j]);
			swap(S[i], S[j]);
		}
	}
	swap(A[i+1], A[r]);
	swap(S[i+1], S[r]);
	return i+1;
}

void quickSort(char* S, int* A, int p, int r)
{
	if (p<r) {
		int q = partition(S, A, p, r);
		quickSort(S, A, p, q-1);
		quickSort(S, A, q+1, r);
	}
}

