#include <iostream>
#include <cstdio>
using namespace std;
struct Element {
    char c;
    int number;
};

void swap(Element &a, Element &b) {
    Element temp = a;
    a = b;
    b = temp;
}

int _div(Element *A, int left, int right) {
    Element keyValue = A[left];
    int i = left;
    int j = right;
    while (i < j) {

        while (A[j].number > keyValue.number && j > i) {
            j--;
        }

        if (j > i) {
            A[i++] = A[j];
        }

        while (A[i].number <= keyValue.number && j > i) {
            i++;
        }

        if (j > i) {
            A[j--] = A[i];
        }
    }
    A[i] = keyValue;

    return i;
}

void qs(Element *A, int left, int right) {
    if (left < right) {
        int mid = _div(A, left, right);
        qs(A, left, mid - 1);
        qs(A, mid + 1, right);
    }
}

const int kMaxValue = 1000000;
const int kMax = 500000;

//Element A[kMax] = {0};

Element L[kMax / 2 + 2];
Element R[kMax / 2 + 2];
int cmpCount = 0;

void _merge(Element *A, int n, int left, int mid, int right) {
    int n1 = mid - left;
    for (int i = 0; i < n1; i++) {
        L[i] = A[left + i];
    }

    int n2 = right - mid;
    for (int i = 0; i < n2; i++) {
        R[i] = A[mid + i];
    }
    Element temp;
    temp.number = kMaxValue;
    L[n1] = temp;
    R[n2] = temp;
    int l1 = 0;
    int l2 = 0;
    for (int k = left; k < right; k++) {
        ++cmpCount;
        if (L[l1].number <= R[l2].number) {
            A[k] = L[l1++];
        } else {
            A[k] = R[l2++];
        }
    }
}

void mergeSort(Element *A, int n, int left, int right) {
    if (left + 1 < right) {
        int mid = (left + right) / 2;
        mergeSort(A, n, left, mid);
        mergeSort(A, n, mid, right);
        _merge(A, n, left, mid, right);
    }
}

bool isStable(Element *e1, Element *e2, int n) {
    for (int i = 0; i < n; i++) {
        if (e1[i].c != e2[i].c) {
            return false;
        }
    }
    return true;
}


