void Merge(Card a[], int left, int mid, int right){
	int n1 = mid - left;
	int n2 = right - mid;
	Card* L = new Card[n1+1];
	Card* R = new Card[n2+1];
	for ( int i = 0; i < n1; i++) L[i] = a[left + i];
	L[n1].x = INT_MAX;
	for (int i = 0; i < n2; i++) R[i] = a[mid + i];
	R[n2].x = INT_MAX;
	int i = 0;
	int j = 0;
	while(i < n1 || j < n2){
		if (L[i].x <= R[j].x){
			a[left + i + j] = L[i];
			i++;
		}
		else{
			a[left + i + j] = R[j];
			j++;
		}
	}
}

