void MergeSort (card S[], int B, int T)
{
  if (B >= T)
    return;

  int mid = (B + T) / 2;
  MergeSort (S, B, mid);
  MergeSort (S, mid + 1, T);

  card *buf = new card[T - B + 1];

  int j = 0;
  for (int i = B; i <= mid; i++)
    buf[j++] = S[i];
  for (int i = T; i >= mid + 1; i--)
    buf[j++] = S[i];

  int l = 0;
  int r = T - B;
  int k = B;
  while (l <= r)
    {
      if (buf[l].value <= buf[r].value)
	S[k++] = buf[l++];
      else
	S[k++] = buf[r--];
    }
  delete[]buf;
}


