int card_equal(vector<card> &A,vector<card> &B,int n){
	int i;
	int flag=0;
	for(i=0;i<n;i++){
		if((A[i].suit != B[i].suit)||(A[i].num != B[i].num)){
			flag=1;
		}
	}
	return flag;
}

void BubbleSort(vector<card> &A, int n){
	int i,j;
	for (i=0;i<n;i++){
		for (j=n-1;j>i;j--){
			if (A[j].num < A[j-1].num){
				swap(A[j],A[j-1]);
			}
		}
	}
}

int partition(vector<card> &A, int p, int r){
	int x=A[r].num;
	int i=p-1;
	int j;
	for (j=p;j<r;j++){
		if (A[j].num<=x){
			i++;
			swap(A[i],A[j]);
		}
	}
	swap(A[i+1],A[r]);
	return i+1;
}

void QuickSort(vector<card> &A, int p, int r){
	if (p<r){
		int q=partition(A,p,r);
		QuickSort(A,p,q-1);
		QuickSort(A,q+1,r);
	}
	return;
}
