    merge[i].first = quick[i].first;
    merge[i].second = quick[i].second;
  }

  quickSort(quick, 0, n);
  mergeSort(merge, 0, n);

  bool stable = true;
  for (int i = 0; i < n; i++) {
    if (quick[i] != merge[i]) {
      stable = false;
      break;
    }
  }

  cout << (stable ? "Stable" : "Not stable") << endl;

  for (int i = 0; i < n; i++)
    cout << quick[i].first << ' ' << quick[i].second << endl;

  return 0;
}

