int partition(vector<pair<char, int>>& A, int p, int r) {
  int x = A[r].second;
  int i = p - 1;
  for (int j = p; j < r; j++) {
    if (A[j].second <= x) {
      i++;
      int tmp = A[j].second;
      A[j].second = A[i].second;
      A[i].second = tmp;
    }
  }
  int tmp = A[i + 1].second;
  A[i + 1].second = A[r].second;
  A[r].second = tmp;
  return i + 1;
};

