void Merge(char idID[],char ID[],long S[],int left,int mid,int right){
  int n1 = mid-left+1;
  int n2 = right-mid;
  l L[n1+3];
  l R[n2+3];
  char CL[n1+3];
  char CR[n2+3];

  for(int i=1;i<=n1;i++){
    L[i] = S[left+i-1];
    CL[i] = idID[left+i-1];
  }
  for(int j=1;j<=n2;j++){
    R[j]=S[mid+j];
    CR[j]=idID[mid+j];
  }
  L[n1+1]=R[n2+1]=SENTINEL;
  int i=1;
  int j=1;
  for(int k=left;k<=right;k++){
    if(L[i]<=R[j]){
      S[k]=L[i];
      idID[k] = CL[i];
      i=i+1;
    }
    else{
      S[k]=R[j];
      idID[k] = CR[j];
      j=j+1;
    }
  }
}

void Merge_Sort(char idID[],char ID[],long S[],int left,int right){
  if(left<right){
    int mid = (left+right)/2;
    Merge_Sort(idID,ID,S,left,mid);
    Merge_Sort(idID,ID,S,mid+1,right);
    Merge(idID,ID,S,left,mid,right);
  }
}




int Partition(char ID[],l A[],l p,l r){
  l x = A[r];
  l i = p-1;
  for(int j=p;j<r;j++){
    if(A[j] <= x){
      i = i+1;
      char ch = ID[i];
      ID[i] = ID[j];
      ID[j] = ch;
      l h=A[i];
      A[i] = A[j];
      A[j] = h;
    }
  }
  char ch = ID[i+1];
  ID[i+1] = ID[r];
  ID[r] = ch;
  l h = A[i+1];
  A[i+1] = A[r];
  A[r] = h;
  return i+1;
}

void Quicksort(char ID[],l A[],l p,l r){
  if(p<r){
    l q = Partition(ID,A,p,r);
    Quicksort(ID,A,p,q-1);
    Quicksort(ID,A,q+1,r);
  }
}


