int partition(int *A, int p, int r){
  int x = A[r];
  int i = p - 1;
  for(int j = p; j < r; j++){
    if(x >= A[j]){
      i++;
      int temp = A[j];
      A[j] = A[i];
      A[i] = temp;
    }
  }
  A[r] = A[++i];
  A[i] = x;
  return i;
}

