  for(int j=p;j<r;j++){
    if(A[j].value <= x.value){
      i++;
      swap(i,j);
    }
  }
  swap(i+1,r);

  return i+1;

}

void quickSort(int p,int r){
  if(p < r){
    int q = partition(p,r);
    quickSort(p,q-1);
    quickSort(q+1,r);
  }
}

