typedef struct {
    char type;
    long long value;
} Card;

void exchange(Card A[], int index, int r) {
    Card tmp = A[index];
    A[index] = A[r];
    A[r] = tmp;
}

int Partition(Card A[], int p, int r) {
    int x = A[r].value;
    int i = p - 1;
    for (int j = p; j<r; j++) {
        if (A[j].value <= x) {
            i++;
            exchange(A, i, j);
        }
    }
    exchange(A, i+1, r);
    return i + 1;
}

void Quicksort(Card A[], int p, int r) {
    if (p < r) {
        int q = Partition(A, p, r);
        Quicksort(A, p, q - 1);
        Quicksort(A, q + 1, r);
    }
}

void merge(Card A[], long long left, long long mid, long long right) {
    long long n1 = mid - left + 2;
    long long n2 = right - mid + 1;
    long long L[n1], R[n2];
    for (long long i=0; i<n1-1; i++) L[i] = A[left + i].value;
    for (long long i=0; i<n2-1; i++) R[i] = A[mid + 1 + i].value;

    L[n1-1] = MAX;
    R[n2-1] = MAX;

    long long l=0, r = 0;
    for (long long i=left; i<=right; i++) {
        if (L[l] <= R[r]) {
            A[i].value = L[l];
            l++;
        } else {
            A[i].value = R[r];
            r++;
        }
    }
}

void merge_sort(Card A[], long long left, long long right) {
    if (left < right) {
        long long mid = (left + right) / 2;
        merge_sort(A, left, mid);
        merge_sort(A, mid + 1, right);
        merge(A, left, mid, right);
    }
}

