		else data[l++] = tmp[p2++];
	}
	while (p1 < m) data[l++] = tmp[p1++];
	while (p2 < r) data[l++] = tmp[p2++];
}

void merS(vector<SSS> &data, int l, int r){
	if (l + 1 < r){
		int m = l + (r - l) / 2;
		merS(data, l, m);
		merS(data, m, r);
		mer(data, l, m, r);
	}
}

int part(vector<SSS> &data, int l, int r){
	SSS v = data[r];

	int p1 = l - 1;
	int p2 = l;
	while (p2 < r) {
		if (data[p2].val <= v.val) swap(data[++p1], data[p2]);
		p2++;
	}
	swap(data[++p1], data[r]);
	return p1;
}

void quiS(vector<SSS> &data, int l, int r){
	if (l < r){
		int piv = part(data, l, r);
		quiS(data, l, piv - 1);
		quiS(data, piv + 1, r);
	}
}

