typedef pair<int, int> P;

int partition(vector<P> &a, int p, int r) {
  P x = a[r];
  int i = p-1;
  for ( int j = p; j < r; j++ ) {
    if ( a[j].first <= x.first ) {
      i++;
      swap(a[i], a[j]);
    }    
  }

  swap(a[i+1], a[r]);
  return i+1;
}

void quickSort(vector<P> &a, int p, int r) {
  if ( p < r ) {
    int q = partition(a, p, r);
    quickSort(a, p, q-1);
    quickSort(a, q+1, r);
  }
}

