	if (p < r) {
		vi i = p, j = i;
		for (;j != r;j++)
			if ((*j).n <= (*r).n)
				swap(*j, *i++);
		swap(*i, *r);

		qs(p, i - 1);
		qs(i + 1, r);
	}
}

