void BubbleSort(int a[],char c[],int n){
  int st;
  char stc;
  for(int i=0;i<n;i++){
    for(int j=n-1;j>i+1;j--){
      if(a[j]<a[j-1]){
	st=a[j];
	a[j]=a[j-1];
	a[j-1]=st;
	stc=c[j];
	c[j]=c[j-1];
	c[j-1]=stc;
      }
    }     
  }
  }


