int partition(card A[], int p, int r)
{
    card x = A[r];
    int i = p;
    for(int j=p; j<r; j++) {
        if(A[j]<=x) swap(A[i++], A[j]);
    }
    swap(A[i], A[r]);
    return i;
}

void quickSort(card A[], int p, int r)
{
    if(p < r) {
        int q = partition(A, p, r);
        quickSort(A, p, q-1);
        quickSort(A, q+1, r);
    }
}

