    for (int i = 0; i < x; i++)
        L[i] = b[left + i];
    for (int i = 0; i < y; i++)
        R[i] = b[mid + i];

    L[x].val = R[y].val = MAX;
    int i = 0, j = 0;
    for (int k = left; k < right; k++)
    {
        if (L[i].val <= R[j].val)
            b[k] = L[i++];
        else
            b[k] = R[j++];
    }
}

void MergeSort(int left, int right)
{
    if (left + 1 < right)
    {
        int mid = (left + right) >> 1;
        MergeSort(left, mid);
        MergeSort(mid, right);
        merge(left, mid, right);
    }
}

