template<typename T>
T partition(T left, T right){
    T i = left;
    while (*i < *right) {
        i++;
    }
    T j;
    for (j = i+1; j < right; j++) {
        if(*j < *right){
            swap(*i, *j);
            i++;
        }
    }
    swap(*i, *right);
    return i;
}

template<typename T>
void _qsort(T left, T right){
    auto mid = partition(left, right);

    if(left + 1 < mid) _qsort(left, mid - 1);
    if(mid + 1 < right) _qsort(mid + 1, right);
}

