void stability(card before[],card after[]){
    bool stable = true;
    //table : 0:S 1:H 2:C 3:D
    int tableBefore[range][4];
    int numberOfAppearanceBefore[range];
    int tableAfter[range][4];
    int numberOfAppearanceAfter[range];
    for (int i=0; i<range; i++) {
        for (int j=0; j<4; j++) {
            tableBefore[i][j]=0;
            tableAfter[i][j]=0;
        }
        numberOfAppearanceBefore[i]=0;
        numberOfAppearanceAfter[i]=0;
    }
    for (int i=0; i<n; i++) {
        int numberOfCard = before[i].second;
        switch (before[i].first) {
            case 'S':
                numberOfAppearanceBefore[numberOfCard-1]++;
                tableBefore[numberOfCard-1][0] = numberOfAppearanceBefore[numberOfCard-1];
                break;
            case 'H':
                numberOfAppearanceBefore[numberOfCard-1]++;
                tableBefore[numberOfCard-1][1] = numberOfAppearanceBefore[numberOfCard-1];
                break;
            case 'C':
                numberOfAppearanceBefore[numberOfCard-1]++;
                tableBefore[numberOfCard-1][2] = numberOfAppearanceBefore[numberOfCard-1];
                break;

            case 'D':
                numberOfAppearanceBefore[numberOfCard-1]++;
                tableBefore[numberOfCard-1][3] = numberOfAppearanceBefore[numberOfCard-1];
                break;

            default:
                break;
        }
    }
    for (int i=0; i<n; i++) {
        int numberOfCard = after[i].second;
        switch (after[i].first) {
            case 'S':
                numberOfAppearanceAfter[numberOfCard-1]++;
                tableAfter[numberOfCard-1][0] = numberOfAppearanceAfter[numberOfCard-1];
                break;
            case 'H':
                numberOfAppearanceAfter[numberOfCard-1]++;
                tableAfter[numberOfCard-1][1] = numberOfAppearanceAfter[numberOfCard-1];
                break;
            case 'C':
                numberOfAppearanceAfter[numberOfCard-1]++;
                tableAfter[numberOfCard-1][2] = numberOfAppearanceAfter[numberOfCard-1];
                break;
            case 'D':
                numberOfAppearanceAfter[numberOfCard-1]++;
                tableAfter[numberOfCard-1][3] = numberOfAppearanceAfter[numberOfCard-1];
                break;

            default:
                break;
        }
    }
    for (int i=0; i<range; i++) {
        for (int j=0; j<4; j++) {
            if (tableBefore[i][j] != tableAfter[i][j]) {
                stable = false;
                break;
            }
        }
    }
