void bubleSort(int* arr, char* zimu, int len) {
	using std::swap;
	for (int i = 0; i < len - 1; i++) {
		for (int j = len - 1; j > i; j--) {
			if (arr[j] < arr[j - 1]) {
				swap(arr[j], arr[j - 1]);
				swap(zimu[j], zimu[j - 1]);
			}
		}

	}
}

