class Trump {
    friend std::ostream& operator<<(std::ostream& os, const Trump& trump);

public:
    enum class Mark {
        None = 0,
        Heart,
        Diamond,
        Spade,
        Clover,
        Size
    };

    static Mark to_mark(const char c);
    static const char to_char(const Trump::Mark& mark);

public:
    Trump();
    Trump(const Mark& mark, const int num);
    Trump(const std::string& str);
    Trump(const Trump& rhs);

    Trump& operator =(Trump&& rhs);

    void swap(Trump& rhs) noexcept;

    bool operator< (const Trump& rhs) const;
    bool operator> (const Trump& rhs) const;
    bool operator<=(const Trump& rhs) const;
    bool operator==(const Trump& rhs) const;
    bool operator!=(const Trump& rhs) const;

private:
    Mark _mark;
    int _num;
};

inline Trump::Mark Trump::to_mark(const char c)
{
    static const std::map<char, Mark> dict
        = {
            { 'H', Mark::Heart },
            { 'D', Mark::Diamond },
            { 'S', Mark::Spade },
            { 'C', Mark::Clover }
    };
    const auto it = dict.find(c);

    return it != dict.cend()
        ? it->second
        : Mark::None;
}

inline const char Trump::to_char(const Trump::Mark& mark)
{
    const char dict[] = { 'N', 'H', 'D', 'S', 'C', 'N' };
    return dict[static_cast<int>(mark)];
}


Trump::Trump()
    : _mark(Mark::None),
    _num('0')
{
}

inline Trump::Trump(const Mark & mark, const int num)
    : _mark(mark),
    _num(num)
{
}

Trump::Trump(const std::string & str)
    : _mark(Trump::to_mark(str[0])),
    _num(std::stoi(str.substr(2, str.size() - 2)))
{
}

Trump::Trump(const Trump& rhs)
    : _mark(rhs._mark),
    _num(rhs._num)
{
}

Trump & Trump::operator=(Trump&& rhs)
{
    this->swap(rhs);
    return *this;
}

void Trump::swap(Trump& rhs) noexcept
{
    std::swap(_mark, rhs._mark);
    std::swap(_num, rhs._num);
    return;
}

bool Trump::operator<(const Trump & rhs) const
{
    return _num < rhs._num;
}

bool Trump::operator>(const Trump & rhs) const
{
    return rhs._num < _num;
}

bool Trump::operator<=(const Trump & rhs) const
{
    return *this < rhs
        || (this->_num == rhs._num);
}

bool Trump::operator==(const Trump & rhs) const
{
    return _mark == rhs._mark
        && !(*this < rhs || rhs < *this);
}

bool Trump::operator!=(const Trump & rhs) const
{
    return !(*this == rhs);
}

std::ostream& operator<<(std::ostream& os, const Trump& trump)
{
    os << Trump::to_char(trump._mark) << " " << trump._num;
    return os;
}

int partition(Trump* trumps, const int n)
{
    const auto x = trumps[n - 1];   //pivot value
    int i = 0;  //increment if swaped
    int j = 0;  //increment every loop
    for (; j < n - 1; ++j) {   //scan start to end
        if (trumps[j] <= x) {
            trumps[i].swap(trumps[j]);
            ++i;
        }
    }
    trumps[i].swap(trumps[j]);
    return i;
}

void quick_sort(Trump* trumps, const int n)
{
    if (n <= 1) {
        return;
    }

    const int p = partition(trumps, n);
    quick_sort(&trumps[0], p);
    quick_sort(&trumps[p + 1], n - p - 1);
}

void bubble_sort(Trump* trumps, int n) {
    for (int l = 0; l < n - 1; ++l) {
        for (int r = l; r < n; ++r) {
            if (trumps[l] > trumps[r]) {    //predictor
                std::swap(trumps[l], trumps[r]);
            }
        }
    }
}

void print(Trump const* trumps0, Trump const* trumps1, int n) {
    bool is_stable = true;
    std::stringstream stream;
    for (int i = 0; i < n; ++i) {
        if (trumps0[i] != trumps1[i]) {
            is_stable = false;
        }
        stream << trumps1[i] << std::endl;
    }
    std::cout << (is_stable ? "Stable" : "Not stable") << std::endl;
    std::cout << stream.str();
}

