void QuickSort(T* A, int p, int r){
    int mid;
    if (p < r) { // when !(there are less than or equal to three elements)
        mid = Partition(A, p, r);
        QuickSort(A, p, mid-1);
        QuickSort(A, mid+1, r);
    }
}

// Partition from A[p] to A[r]
int Partition(T* A, int p, int r){
    int x = A[r].n, i = p-1, j;

    for (j = p; j < r; j++) {
        if (A[j].n <= x) {
            i++;
            Swap(&A[i], &A[j]);
        }
    }
    Swap(&A[i+1], &A[r]);

    return i+1;
}

void BubbleSort(T* A, int n){
    int i, j;
    for (i = 0; i < n; i++) {
        for (j = 0; j < n-1 - i; j++) {
            if (A[j].n > A[j+1].n) {
                Swap(&A[j], &A[j+1]);
            }
        }
    }
}

void Swap(T *x, T *y){
    T tmp;
    tmp = *y;
    *y = *x;
    *x = tmp;
}

