// http://judge.u-aizu.ac.jp/onlinejudge/description.jsp?id=ALDS1_6_C

int part(int a[], char b[], int p, int r) {
	int x = a[r];
	int i = p - 1;
	for (int j = p; j < r; j++) {
		if (a[j] <= x) {
			i += 1;
			swap(a[i], a[j]);
			swap(b[i], b[j]);
		}
	}
	swap(a[i + 1], a[r]);
	swap(b[i + 1], b[r]);
	return i + 1;
}

void qsort(int a[], char b[], int p, int r) {
	if (p < r) {
		int q = part(a, b, p, r);
		qsort(a, b, p, q - 1);
		qsort(a, b, q + 1, r);
	}
}

