using namespace std;

typedef vector<pair<char, int> > VPCI;

int
partition(VPCI &a, const int p, const int r)
{
    int x = a[r].second;
    int i = p - 1;
    for (int j = p; j < r; j++) {
        if (a[j].second <= x) {
            i++;
            swap(a[i], a[j]);
        }
    }
    swap(a[i + 1], a[r]);
    return i + 1;
}

void
quicksort(VPCI &a, const int p, const int r)
{
    if (p >= r) { return; }
    int q = partition(a, p, r);
    quicksort(a, p, q - 1);
    quicksort(a, q + 1, r);
}

void
checkstable(const VPCI &original, const VPCI &sorted)
{
    auto sit = sorted.begin();
    for (auto oit = original.begin(); oit != original.end(); oit++, sit++) {
        if (*oit != *sit) {
            cout << "Not stable" << endl;
            return;
        }
    }
    cout << "Stable" << endl;
}

