    }
}

int partition(Card A[], int p, int r) {
    Card x = A[r];
    int i = p - 1;
    Card temp;

    for (int j = p; j < r; j++) {
        if (A[j].value <= x.value) {
            i++;
            temp = A[j];
            A[j] = A[i];
            A[i] = temp;
        }
    }

    temp = A[i + 1];
    A[i + 1] = A[r];
    A[r] = temp;

    return i + 1;
}

void quickSort(Card A[], int p, int r) {
    if (p < r) {
        int q = partition(A, p, r);
        quickSort(A, p, q - 1);
        quickSort(A, q + 1, r);
    }
}

