int Partition(int A[],char B[],int p,int r){
    int x=A[r];
    int i=p-1;
    for(int j=p;j<=r-1;j++){
        if(A[j]<=x){
            i++;
            swap(A[i],A[j]);
            swap(B[i],B[j]);
        }
    }
    swap(A[i+1],A[r]);
    swap(B[i+1],B[r]);
    return i+1;
}

void Quicksort(int A[],char B[],int p,int r){
    if(p<r){
        int q=Partition(A,B,p,r);
        Quicksort(A,B,p,q-1);
        Quicksort(A,B,q+1,r);
    }
    return;
}

void merge(int A[],char B[],int left,int mid,int right){
    int n1=mid-left;
    int n2=right-mid;
    int L[NMAX],R[NMAX];
	char LL[NMAX],RR[NMAX];

    for(int i=0;i<=n1-1;i++){
        L[i]=A[left+i];
		LL[i]=B[left+i];
    }
    for(int i=0;i<=n2-1;i++){
        R[i]=A[mid+i];
		RR[i]=B[mid+i];
    }
    L[n1]=SENTINEL;
    R[n2]=SENTINEL;
    int i=0,j=0;
    for(int k=left;k<=right-1;k++){
        if(L[i]<=R[j]){
            A[k]=L[i];
			B[k]=LL[i];
            i++;
        }
        else{
            A[k]=R[j];
			B[k]=RR[j];
            j++;
        }
    }
}

