int Partition(card* array, int begin, int end){
	unsigned int mid = array[end].val;

	int i = begin;
	for(int j = begin; j < end; j ++ ){
		if(array[j].val <= mid){
			card buf = array[i];
			array[i] = array[j];
			array[j] = buf;
			i ++ ;
		}
	}
	{
