		array[end] = array[i];
		array[i] = buf;
	}

	return i;
}

void QuickSort(card* array, int begin, int end){
	if(begin >= end)return;

	int mid = Partition(array, begin, end);

	QuickSort(array, begin, mid - 1);
	QuickSort(array, mid + 1, end);
}

