    j = mid - start;
    k = (i > j) ? i : j;

    for (l = 0; l < k; l++) {
        tmp1[l] = elem[start+l];
        tmp2[l] = elem[mid+l];
    }
    tmp1[j].first = 0x7FFFFFF;
    tmp2[i].first = 0x7FFFFFF;

    j = 0;
    k = 0;
    for (i = start; i < end; i++) {
        if (tmp1[j].first <= tmp2[k].first) {
            elem[i] = tmp1[j];
            ++j;
        }
        else {
            elem[i] = tmp2[k];
            ++k;
        }
    }

    return;
}

void MargeSort(pair<int, char> elem[], int start, int end)
{
    int mid;

    if (start < end) {
        mid = (start + end) / 2;
        MargeSort(elem, start, mid);
        MargeSort(elem, mid, end);
        MargeElem(elem, start, mid, end);
    }

    return;
}

int PartitionSort(pair<int, char> elem[], int start, int end)
{
    int i;
    int target;
    int left;

    left = start - 1;
    target = elem[end-1].first;

    for (i = start; i < end - 1; i++) {
        if (target >= elem[i].first) {
            ++left;
            swap(elem[left], elem[i]);
        }
    }
    ++left;
    swap(elem[left], elem[end-1]);

    return left;
}


void QuickSort(pair<int, char> elem[], int start, int end)
{
    int mid;

    mid = PartitionSort(elem, start, end);

    if (start < mid - 1) {
        QuickSort(elem, start, mid);
    }
    if (mid < end - 1) {
        QuickSort(elem, mid, end);
    }

    return;
}

