  int n1 = m-l;
  int n2 = r-m;
  vector<card> v1(n1+1);
  vector<card> v2(n2+1);
  for (size_t i = 0; i < n1; i++) {
    v1[i] = v[l+i];
  }
  for (size_t i = 0; i < n2; i++) {
    v2[i] = v[m+i];    
  }
  v1.back() = CARD_MAX;
  v2.back() = CARD_MAX;
  int i = 0, j = 0;
  for (size_t k = l; k < r; k++) {
    if(v1[i] < v2[j]){
      v[k] = v1[i++];
    } else{
