bool is_order(std::vector<struct Card *> *A, int i, int j) {
  if (A->at(i)->order < A->at(j)->order) {
    return true;
  } else {
    return false;
  }
}

void swap(std::vector<struct Card *> *A, int i, int j) {
  struct Card *tmp = A->at(i);
  A->at(i) = A->at(j);
  A->at(j) = tmp;
}

int partition(std::vector<struct Card *> *A, int p, int r, bool *order) {
  struct Card *x = A->at(r);
  int i = p - 1;

  for (int j = p; j <= r - 1; j++) {
    if (A->at(j)->value <= x->value) {
      i++;

      swap(A, i, j);
    }
  }

  swap(A, i + 1, r);

  return i + 1;
}

bool quick_sort(std::vector<struct Card *> *A, int p, int r) {
  bool order1 = true;
  bool order2 = true;
  bool order3 = true;

  if (p < r) {
    int q = partition(A, p, r, &order1);

    order2 = quick_sort(A, p, q - 1);
    order3 = quick_sort(A, q + 1, r);
  } 

  return (order1 && order2 && order3);
}


