    Card x = A[r];
    int i = p -1;
    for(int j = p; j <= r-1; j++) {
        if(A[j].value <= x.value) {
            i = i + 1;
            swap(A, i, j);
        }
    }
    swap(A, i+1, r);
    return i+1;
}

