template<typename T>
int partition(vector<T> &a, int p, int r) {
  T x = a[r - 1];
  int i = p;
  for (int j = p; j < r - 1; ++j) {
    if (!(x < a[j])) {
      T t = a[i];
      a[i] = a[j];
      a[j] = t;
      ++i;
    }
  }
  T t = a[i];
  a[i] = a[r - 1];
  a[r - 1] = t;
  return i;
}

template<typename T>
void quick_sort(vector<T> &a, int p, int r) {
  if (p < r - 1) {
    int q = partition(a, p, r);
    quick_sort(a, p, q);
    quick_sort(a, q + 1, r);
  }
}

