    cin >> n;
    vector<pair<char, int>> A1(n);
    vector<pair<char, int>> A2(n);
    for (int i = 0; i < n; i++) {
        cin >> A1[i].first >> A1[i].second;
        A2[i] = A1[i];
    }
    quick_sort(A1, 0, n - 1);
