	for (j = p; j < r; j++){
		if (A[j].second <= x){
			i++;
			swap(A[i], A[j]);
		}
	}
	swap(A[i + 1], A[r]);
	return i + 1;
}

void quicksort(pair<char, long> A[], long p, long r){
	if (p < r){
		long q = partition(A, p, r);
		quicksort(A, p, q - 1);
		quicksort(A, q + 1, r);
	}
}

void merge(pair<char, long> A[], long left, long mid, long right){
	long n1 = mid - left;
	long n2 = right - mid;
	pair<char, long> L[100001], R[100001];
	for (long i = 0; i < n1; i++) L[i] = A[left + i];
	for (long i = 0; i < n2; i++) R[i] = A[mid + i];
	L[n1] = make_pair('Z', INFTY);
	R[n2] = make_pair('Z', INFTY);
	long i = 0;
	long j = 0;
	for (long k = left; k < right; k++){
		if (L[i].second <= R[j].second){
			A[k] = L[i];
			i++;
		}
		else {
			A[k] = R[j];
			j++;
		}
	}
}

void mergeSort(pair<char, long> A[], long left, long right){
	if (left + 1 < right){
		long mid = (left + right) / 2;
		mergeSort(A, left, mid);
		mergeSort(A, mid, right);
		merge(A, left, mid, right);
	}
}

