int Partition(V<PSI> *vec, int first, int last) {
	V<PSI> &v = *vec;
	int pivot = v[last].S;
	int lower = first;
	FOR(i, first, last){
		if (v[i].S <= pivot) {
			swap(v[lower], v[i]);
			lower++;
		}
	}
	swap(v[lower], v[last]);
	return lower;
}
void QuickSort(V<PSI> *vec, int first, int last) {
	if (first >= last)
		return;
	V<PSI> &v = *vec;
	auto q = Partition(&v, first, last);
	QuickSort(&v, first, q - 1);
	QuickSort(&v, q + 1, last);
	return;
}

int Merge(V<PSI> *vec, int left, int mid, int right) {
	V<PSI> &v = *vec;
	int n1 = mid - left;
	int n2 = right - mid;
	V<PSI> L(n1 + 1), R(n2 + 1);
	REP(i, n1) {
		L[i] = v[left + i];
	}
	REP(i, n2) {
		R[i] = v[mid + i];
	}
	L[n1].S = R[n2].S = numeric_limits<int>::max();
	int i = 0;
	int j = 0;
	int count = 0;
	FOR(k, left, right) {
		count++;
		if (L[i].S <= R[j].S) {
			v[k] = L[i];
			i++;
		} else {
			v[k] = R[j];
			j++;
		}
	}
	return count;
}
int MergeSort(V<PSI> *vec, int left, int right) {
	V<PSI> &v = *vec;
	int count = 0;
	if (left + 1 < right) {
		int mid = (left + right) / 2;
		count += MergeSort(&v, left, mid);
		count += MergeSort(&v, mid, right);
		count += Merge(&v, left, mid, right);
	}
	return count;
}

