    {
        if (Array[j].first <= Array[last].first)
        {
            i++;
            swap(Array[i], Array[j]);
        }
    }
    swap(Array[i + 1], Array[last]);
    return i + 1;
}
void quicksort(vector<pair<int, char> > &Array, int p, int last)
{
    if (p < last)
    {
