int partition_tail_pivot(vector<Card>& a, int p, int r){
  auto piv = a[r];
  int i = p-1;
  for(int j = p; j < r; ++j){
    if(a[j] <= piv){
      ++i;
      swap(a[i], a[j]);
    }
  }
  swap(a[i+1], a[r]);
  return i+1;
}

void q_sort(vector<Card>& a, int p, int r){
  int q = partition_tail_pivot(a, p, r);
  if(p < q-1) q_sort(a, p, q-1);
  if(q+1 < r) q_sort(a, q+1, r);
}


