void bubble(int A[], int n){
	int flag;
	while(flag){
	flag = false;
	for(int i = n-1;i >= 1;--i){
		if(A[i] < A[i-1]){
			swap(&A[i], &A[i-1]);
			swap(&S1[i], &S1[i-1]);
			flag = true;
			}
		}
	}
}

int partition(int A[], int p, int r){
	int x = A[r], cnt = p-1;
	for(int i=p;i<r;++i){
		if(A[i] <= x){
			cnt++;
			swap(&A[cnt], &A[i]);
			swap(&S2[cnt], &S2[i]);
		}
	}
	swap(&A[cnt+1], &A[r]);
	swap(&S2[cnt+1], &S2[r]);
	return ++cnt;
}

