{
	int mid;
	if (left + 1 < right) {
		mid = (left + right) / 2;
		mergeSort(A, left, mid);
		mergeSort(A, mid, right);
		merge(A, left, mid, right);
	}
}

int partition(Card A[], int left, int right){
	int i = left - 1;
	Card x = A[right];
	for (int j = left; j < right; j++) {
		if (A[j].num <= x.num) {
			i++;
			Card temp = A[i];
			A[i] = A[j];
			A[j] = temp;
		}
	}
	Card t = A[i+1];
	A[i+1] = A[right];
	A[right] = t;
	return i+1;
}

