int partition(vector<Node>& A, const int l, const int r) {
    const int pivot = A[r - 1].number;
    int head = l;
    for(int i = l; i < r; i++) {
        if(A[i].number <= pivot) {
            swap(A[head], A[i]);
            head++;
        }
    }
    return head - 1;
}

