        if(A[j].number <= x) {
            ++i;
            card cpy = A[i];
            A[i] = A[j];
            A[j] = cpy;
        }
    }
    card cpy = A[r];
    A[r] = A[i + 1];
    A[i + 1] = cpy;

    return i + 1;
