			id[j] = temp;
			char temp1 = c[i];
			c[i] = c[j];
			c[j] = temp1;
		}
	}
	int temp = a[i+1];
	a[i+1] = a[r];
	a[r] = temp;
	 temp = id[i+1];
	id[i+1] = id[r];
	id[r] = temp;
	char temp1 = c[i+1];
	c[i+1] = c[r];
	c[r] = temp1;
	return i+1;	
}
