{
    int i,j;
    P v;
    for(i=1;i<n;i++)
    {
        v = a[i];
        j = i-1;
        while(j>=0&&a[j].b>v.b)
        {
            a[j+1] = a[j];
            j--;
        }
        a[j+1] = v;
    }
