int partition(int A[], char B[], int C[], int p, int r){
	int x = A[r - 1];
	int i = p - 1;

	for(int j = p; j < r - 1; j ++){
		if(A[j] <= x){
			i ++;
			swap(A[i], A[j]);
			swap(B[i], B[j]);
			swap(C[i], C[j]);
		}
	}
	swap(A[++ i], A[r - 1]);
	swap(B[i], B[r - 1]);
	swap(C[i], C[r - 1]);
	return i;
}

