#define NUM 100000
#define INF 1000000000
pair<int,char> A[NUM];
pair<int,char> B[NUM];
pair<int,char> B_l[NUM];
pair<int,char> B_r[NUM];

int pickup_middle(int p, int q){
    int a = A[p].first;
    int b = A[(p + q) / 2].first;
    int c = A[q].first;

    if(a <= b && b <= c){
        return (p + q) / 2;
    }else if(a <= c && c <= b){
        return q;
    }else if(b <= a && a <= c){
        return p;
    }else if(b <= c && c <= a){
        return q;
    }else if(c <= a && a <= b){
        return p;
    }else{
        return (p + q) / 2;
    }
}

void swap_(int a, int b){
    pair<int,char> tmp = A[a];
    A[a] = A[b];
    A[b] = tmp;
}

int partition(int p, int q){
    int m = pickup_middle(p, q);
    swap_(m, q);

    int i = p;
    for(int j = p; j <= q - 1; j++){
        if(A[j] <= A[q]){
            swap_(i, j);
            i++;
        }
    }
    swap_(i, q);
    return i;
}

void quickSort(int p, int q){
    if(q <= p){
        return;
    }
    int r = partition(p, q);
    quickSort(p, r - 1);
    quickSort(r + 1, q);
}

void merge(int p, int r, int q){
    for(int i = p; i < r; i++){
        B_l[i - p] = B[i];
    }
    B_l[r - p] = make_pair(INF, 'A');

    for(int i = r; i <= q; i++){
        B_r[i - r] = B[i];
    }
    B_r[q + 1 - r] = make_pair(INF, 'A');

    int l_index = 0;
    int r_index = 0; 
    int B_index = p;
    while(B_index != q + 1){
        if(B_l[l_index].first <= B_r[r_index].first){
            B[B_index] = B_l[l_index];
            l_index++;
            B_index++;
        }else{
            B[B_index] = B_r[r_index];
            r_index++;
            B_index++;
        }
    }
}

void mergeSort(int p, int q){
    if(q <= p){
        return;
    }
    mergeSort(p, (p + q) / 2);
    mergeSort((p + q) / 2 + 1, q);
    merge(p, (p + q) / 2 + 1, q);
}

