struct SCard {
	char suit;
	int val;
	SCard() {}
	SCard(char suit, int val) : suit(suit), val(val) {}
	bool operator==(const SCard& rhs) const {
		return this->val == rhs.val;
	}
};
ostream& operator<<(ostream& os, const SCard& card) {
	os << card.suit << " " << card.val;
	return os;
}

size_t merge(vector<SCard>& A, int left, int mid, int right) {
	size_t numCmp = 0;
	int n1 = mid - left;
	int n2 = right - mid;
	vector<SCard> L(n1 + 1), R(n2 + 1);
	for (int i = 0; i < n1; i++)
		L[i] = A[left + i];
	for (int i = 0; i < n2; i++)
		R[i] = A[mid + i];
	L[n1].val = R[n2].val = INT_MAX;
	int i = 0, j = 0;
	for (int k = left; k < right; k++) {
		numCmp++;
		if (L[i].val <= R[j].val)
			A[k] = L[i++];
		else
			A[k] = R[j++];
	}
	return numCmp;
}

size_t mergeSort(vector<SCard>& A, int left, int right) {
	size_t numCmp = 0;
	if (left + 1 < right) {
		int mid = (left + right) / 2;
		numCmp += mergeSort(A, left, mid);
		numCmp += mergeSort(A, mid, right);
		numCmp += merge(A, left, mid, right);
	}
	return numCmp;
}

int partition(vector<SCard>& A, int p, int r) {
	SCard x = A[r];
	int i = p - 1;
	for (int j = p; j <= r - 1; j++) {
		if (A[j].val <= x.val) {
			i = i + 1;
			swap(A[i], A[j]);
		}
	}
	swap(A[i + 1], A[r]);
	return i + 1;
}

void quickSort(vector<SCard>& A, int p, int r) {
	if (p < r) {
		int q = partition(A, p, r);
		quickSort(A, p, q - 1);
		quickSort(A, q + 1, r);
	}
}



