  int nn = r-p;
  int c = 0;
  rep(i, nn-1){
    if (A.at(p+i).value <= x) {
      swap(A.at(p+i), A.at(p+c));
      c++;
    }
  }
  swap(A.at(r-1), A.at(p+c));
  return p+c;
}

void quickSort(int p, int r) {
  if (p < r) {
    int q = partition(p, r);
    quickSort(p, q);
    quickSort(q+1, r);
  }
