void merge(int l, int m, int r) {
  int n1 = m-l;
  int n2 = r-m;
  long INF= long(1e+9)+1;
  vector<N> L(n1+1);
  vector<N> R(n2+1);
  rep(i, n1) {
    L.at(i) = B.at(l+i);
  }
  rep(i, n2) {
    R.at(i) = B.at(m+i);
  }
  L.at(n1).value = INF;
  R.at(n2).value = INF;
  int lh, rh;
  lh = rh = 0;
  rep(i, n1+n2) {
    if (L.at(lh).value <= R.at(rh).value) {
      B.at(l+i) = L.at(lh);
      lh++;
    } else {
      B.at(l+i) = R.at(rh);
      rh++;
    }
  }
}

