int partition(Card A[], int p, int r)
{
    int x = A[r].value;
    int i = p - 1;
    for (int j = p; j < r ; j++){
        if (A[j].value <= x){
            i += 1;
            Card t = A[i];
            A[i] = A[j];
            A[j] = t;
        }
    }
    Card t = A[i+1];
    A[i+1] = A[r];
    A[r] = t;
    return i+1;
}

void quicksort(Card A[], int p, int r)
{
    if (p < r){
        int q = partition(A, p, r);
        quicksort(A, p, q - 1);
        quicksort(A, q + 1, r);
    }

}

