	for(int i=0;i<n;++i){
		cin >> S1[i] >> A1[i];
		S2[i] = S1[i], A2[i] = A1[i];
	}
	bubble(&A1[0], n);
	quickSort(&A2[0], 0, n-1);
	judge(n);

	for(int i=0;i<n;++i)
		cout << S2[i] << " " << A2[i] << endl;
	return 0;
}

