	b = t;
}

template<typename T>
int partition(vector<T> &A, int p, int r) {
	int i = p;
	for (int j = p; j < r; j++) {
		if (A[j] <= A[r]) {
			myswap(A[i], A[j]);
			i++;
		}
	}
	myswap(A[i], A[r]);
	return i;
}

template <typename T>
void quick_sort(vector<T> &A, int p, int r) {
	if (p < r) {
		int q = partition(A, p, r);
		quick_sort(A, p, q - 1);
		quick_sort(A, q + 1, r);
	}
	else
		return;
}

