int  P(pair<string,int>* A,int p,int r)
{
	int x=A[r-1].second;
	int i=p-1;
	for(int j=p;j<r-1;j++){
		if(A[j].second <= x){
            i++;
			swap(A[i],A[j]);
		}
	}
	swap(A[i+1],A[r-1]);
	return i+1;
}
void Quicksort(pair<string,int>* A,int p,int r)
{
	if(p<r){
		int q=P(A,p,r);
		Quicksort(A, p, q-1);
		Quicksort(A, q+1, r);
	}
}

