    int left = 0;
    int right = v.size();
    int mid;
    //std::cout << key << ": ";
    while( left < right ){
        mid = ( left + right ) / 2;
        if( v[mid].second == key ){
            //std::cout << key;
            return mid;
        }else if( key < v[mid].second ){
            right = mid;
        }else{
            left = mid + 1;
        }

        if( key == 1 ){
            //std::cout << v[mid] << " ";
        }
    }
    return mid;
}

