std::string CheckStable( std::vector<std::pair<char, int>>& initial, std::vector<std::pair<char, int>>& sorted ){
    int N = sorted.size();
    for( int i = 0; i < N; ++i ){
        for( int j = i+1; j < N; ++j ){
            if( initial[i].second == initial[j].second ){
                for( int a = BinarySearch( sorted, initial[i].second ); a < N; ++a ){
                    for( int b = a+1; b < N; ++b ){
