int partition(int p, int q) {
   int i = p - 1;
   int r = A[q].num;

   for (int j = p; j < q; j++) {
      if (A[j].num <= r) {
         i++;
         swap(A[i], A[j]);
      }
   }
   swap(A[i + 1], A[q]);
   return(i + 1);
}

void quickSort(int p, int q) {
   if (p < q) {
      int ans = partition(p, q);
