void merge(int head, int mid, int tail) {
   int  n1 = mid - head;
   int  n2 = tail - mid;
   Card L[n1 + 1], R[n2 + 1];

   rep(i, n1) L[i] = B[head + i];
   rep(i, n2) R[i] = B[mid + i];
   L[n1].num = R[n2].num = INF;

   int l = 0, r = 0;
   for (int i = 0; i < tail - head; i++) {
      if (L[l].num <= R[r].num) {
         B[head + i] = L[l];
         l++;
      }
      else{
         B[head + i] = R[r];
         r++;
      }
   }
}

void mergeSort(int head, int tail) {
   int mid = (head + tail) / 2;

   if (head + 1 < tail) {
