    for(int j = p; j < r; j++){
        if(A[j].number <= x){
            i++;
            swapCard(i, j);
        }
    }
    swapCard(i+1, r);
    return i+1;
}

void quickSort(int p, int r){
    if(p < r){
        int q = partition(p, r);
        quickSort(p, q-1);
        quickSort(q+1, r);
    }
}

