class cQuickSort
{
	int mn;
	vector<pair<char, int>> m_va;
	bool isStable;
public:
	cQuickSort(int n, vp &va)
		: mn(n), isStable(true)
	{
		m_va = va;
		sort(m_va, 0, m_va.size() - 1);
	}

	int partition(vp &, int, int);
	void sort(vp &, int, int);
	void output();
};

int cQuickSort::partition(vp &va, int p, int r)
{
	int x = va[r].second;
	int i = p - 1;
	for (int j = p; j <= r - 1; ++j)
	{
		if (va[j].second <= x)
		{
			++i;
			swap(va[i], va[j]);
		}
	}
	swap(va[i + 1], va[r]);
	if ((i + 1) != r)
		isStable = false;
	return i + 1;
}

void cQuickSort::sort(vp &va, int p, int r)
{
	if (p < r)
	{
		int q = partition(va, p, r);
		sort(va, p, q - 1);
		sort(va, q + 1, r);
	}
}

