#include <bits/stdc++.h>

using namespace std;

typedef long long  ll;

uint32_t xor128(void) {
  static uint32_t x = 123456789;
  static uint32_t y = 362436069;
  static uint32_t z = 521288629;
  static uint32_t w = 88675123;
  uint32_t t;

  t = x ^ (x << 11);
  x = y; y = z; z = w;
  return w = (w ^ (w >> 19)) ^ (t ^ (t >> 8));
}

int Partition(vector<tuple<char, int, int>> &a, int p, int r)
{
    int x = get<1>(a[(xor128() % (r - p + 1)) + p]);
    int i = p - 1;

    for (int j = p; j < r; ++j)
        if (get<1>(a[j]) <= x)
            swap(a[++i], a[j]);

    swap(a[i + 1], a[r]);

    return i + 1;
}

void QuickSort(vector<tuple<char, int, int>> &a, int p, int r)
{
    if (p < r) {
        int q = Partition(a, p, r);
        QuickSort(a, p, q - 1);
        QuickSort(a, q + 1, r);
    }
}

bool Check(vector<tuple<char, int, int>> &a)
{
    const int n = a.size();
    int left = 0, right = 1;

    while (left < n) {
        right = left + 1;
        while (right < n && get<1>(a[left]) == get<1>(a[right])) {
            if (get<2>(a[right]) < get<2>(a[left]))
                return false;
            ++right;
        }
        left = right;
    }

    return true;
}

