class card{
public:
	char suit;
	int val;
	card() {}
	card(char s,int v) {
		suit = s;
		val = v;
	}
	bool operator<=(card& e) {
			return this->val <= e.val;
		}
	bool operator<(card& e) {
		return this->val < e.val;
	}
	card& operator=(card& e) {
		this->suit = e.suit;
		this->val = e.val;
		return *this;
	}
};

int pt(vector<card>& a,int p,int r) {
	card x = a[r];
	int i = p-1;
	for(int j = p;j < r;j++) {
		if(a[j] <= x) {
			i++;
			auto l = a[i];
			a[i] = a[j];
			a[j] = l;
		}
	}
	auto l = a[r];
	a[r] = a[i+1];
	a[i+1] = l;
	return i+1;
}

void qs(vector<card>& a,int p,int r) {
	if (p < r) {
		int q = pt(a,p,r);
		qs(a,p,q-1);
		qs(a,q+1,r);
	}
}

