int partition(int* arr,char* ch, int head, int tail) {
	using namespace std;
	int stan = arr[tail];
	int board = head - 1;
	for (int j = head; j < tail; j++) {
		if (arr[j] <= stan) {
			board++;
			swap(arr[j], arr[board]);
			swap(ch[j], ch[board]);
		}
	}
	swap(arr[tail], arr[board + 1]);
	swap(ch[tail], ch[board + 1]);
	return board+1;
}

void quickSort(int* arr,char* ch, int head, int tail) {
	if (head < tail) {
		int ntail = partition(arr, ch, head, tail);
		quickSort(arr, ch, head, ntail-1);
		quickSort(arr, ch, ntail + 1, tail);
	}
}

