void insertionSort(int* arr, char* ch, int len) {
	using namespace std;
	for (int i = 0; i < len - 1; i++) {
		int temp = arr[i + 1];
		char tch = ch[i + 1];
		int j = i;
		while (j>=0 && arr[j] > temp) {
			swap(arr[j], arr[j + 1]);
			swap(ch[j], ch[j + 1]);
			j--;
		}
		arr[j] = temp;
		if (arr[j] != arr[j + 1])
			ch[j] = tch;
	}
}

