};

ORDER inputedORDER[MAX];
int order_index = 0;

int n;

void registerORDER(char mark,int number){
	int i;
	for(i = 0; i < order_index; i++){
		if(number == inputedORDER[i].number) break;
	}
	if(i == order_index){
		inputedORDER[order_index].number = number;
		inputedORDER[order_index].mark_array[inputedORDER[order_index].mark_array_index++] = mark;
		order_index++;
	}else{
		inputedORDER[i].mark_array[inputedORDER[i].mark_array_index++] = mark;
	}
}

bool compareToORDER(int cards_index){
	int i,k = 0,number = cards[cards_index].number;
	for(i = 0; i < order_index;i++){
		if(number == inputedORDER[i].number) break;
	}
	while(number == cards[cards_index].number && k < inputedORDER[i].mark_array_index){
		if(cards[cards_index].mark != inputedORDER[i].mark_array[k])
			return false;
		else{
			cards_index++;
			k++;
		}
	}
	return true;
}

bool isStable(){
	int history = 0;
	for(int i = 1; i < n; i++){
		if(cards[history].number != cards[i].number || i == n-1){
			if(!compareToORDER(history))
				return false;
			else{
				history = i;
			}
		}
	}
	return true;
}

int divideByPivot(int left,int right,int pivot){
	int start = left,end = right-1;
	TRAMP tmp;
	while(start < end){
		tmp = cards[start];
		cards[start] = cards[end];
		cards[end] = tmp;

		while(cards[start].number <= pivot && start < right) start++;
		while(cards[end].number > pivot && end >= left) end--;
	}
	for(int i = left; i < right; i++){
		if(cards[i].number > pivot){
			tmp = cards[i];
			cards[i] = cards[right];
			cards[right] = tmp;
			return i;
		}
	}
	return right;
}

int findPivot(int left,int right){
	int i,pivot = cards[right].number;
	for(i = left;i < right; i++){
		if(pivot != cards[i].number)break;
	}
	return (i == right)? -1 : pivot;
}

void quickSort(int left,int right){
	int pivot = findPivot(left,right);
	if(pivot != -1){
		int divide_point = divideByPivot(left,right,pivot);
		if(divide_point - left > 1)
			quickSort(left,divide_point-1);
		if(right - divide_point > 1)
			quickSort(divide_point+1,right);
	}
}


