#include <cstdint>
#include <cstdio>
#include <iostream>
#include <vector>

static const uint32_t kVeryLargeNumber = 0xffffffff;

class Card {
    public:
        char suit;
        uint32_t value;
        Card() {}
        void copy_to(Card*);
};

void Card::copy_to(Card* clone)
{
    clone->suit = this->suit;
    clone->value = this->value;
}

void swap(Card* card1, Card* card2)
{
    Card tmp;
    card1->copy_to(&tmp);
    card2->copy_to(card1);
    tmp.copy_to(card2);
}

void merge(std::vector<Card>& data, int begin1, int begin2, int end2)
{
    std::vector<Card> subdata1(begin2 - begin1 + 1);
    std::vector<Card> subdata2(end2 - begin2 + 1);

    for(int i = 0; i < subdata1.size(); i++) {
        data[begin1 + i].copy_to(&subdata1[i]);
    }
    subdata1[subdata1.size() - 1].suit = 'X';
    subdata1[subdata1.size() - 1].value = kVeryLargeNumber;

    for(int i = 0; i < subdata2.size(); i++) {
        data[begin2 + i].copy_to(&subdata2[i]);
    }
    subdata2[subdata2.size() - 1].suit = 'X';
    subdata2[subdata2.size() - 1].value = kVeryLargeNumber;

    int j = 0;
    int k = 0;
    for(int i = begin1; i < end2; i++) {
        if(subdata1[j].value <= subdata2[k].value) {
            subdata1[j].copy_to(&data[i]);
            j++;
        } else {
            subdata2[k].copy_to(&data[i]);
            k++;
        }
    }
}

void merge_sort(std::vector<Card>& data, int begin1, int end2)
{
    if(end2 - begin1 <= 1) {
        return;
    }
    int begin2 = (begin1 + end2) / 2;
    merge_sort(data, begin1, begin2);
    merge_sort(data, begin2, end2);
    merge(data, begin1, begin2, end2);
}

int do_partition(std::vector<Card>& data, int begin, int end)
{
    if(end - begin <= 1) {
        return begin;
    }
    Card pivot;
    data[end - 1].copy_to(&pivot);

    int pivot_index = 0;
    for(int i = 0; i < end - 1; i++) {
        if(data[i].value <= pivot.value) {
            swap(&data[pivot_index], &data[i]);
            pivot_index++;
        }
    }
    swap(&data[pivot_index], &data[end - 1]);
    return pivot_index;
}

void quick_sort(std::vector<Card>& data, int begin, int end)
{
    if(end - begin <= 1) {
        return;
    }
    int pivot_index = do_partition(data, begin, end);
    quick_sort(data, begin, pivot_index);
    quick_sort(data, pivot_index + 1, end);
}

bool is_stable(std::vector<Card>& data1, std::vector<Card>& data2)
{
    if(data1.size() != data2.size()) {
        return false;
    }
    for(int i = 0; i < data1.size(); i++) {
        if(data1[i].suit != data2[i].suit) {
            return false;
        }
    }
    return true;
}

int main()
{
    int input_size;
    std::cin >> input_size;
    std::vector<Card> data(input_size);
    for(int i = 0; i < data.size(); i++) {
        std::cin >> data[i].suit >> data[i].value;
    }
    std::vector<Card> clone_data(data);

    quick_sort(data, 0, data.size());
    merge_sort(clone_data, 0, clone_data.size());

    if(is_stable(data, clone_data)) {
        puts("Stable");
    } else {
        puts("Not stable");
    }

    for(int i = 0; i < data.size(); i++) {
        printf("%c %x\n", data[i].suit, data[i].value);
    }

    return 0;
}

