	for (int j=a;j<r;j++)
	{
		if (A[j].num<=v.num )
		{
			i++;
			temp=A[j];A[j]=A[i];A[i]=temp;
		}
	}
	temp=A[i+1];A[i+1]=v;A[r]=temp; 
