int partition(card *cards, int left, int right, int pivot_pos){
	int x = cards[pivot_pos].val;
	int i = left - 1;
	for(int j = left; j < right-1; ++j){
		if(cards[j].val <= x){
			++i;
			swap(cards[i], cards[j]);
		}
	}
	swap(cards[i+1], cards[pivot_pos]);
	return i+1;
}

void swap(card *a, card *b){
	card *temp = new card(b);
	b = a;
	a = temp;
	free(temp);
}

void quick_sort(card *cards, int left, int right){
	if(left < right){
		int q = partition(cards, left, right, right-1);
		quick_sort(cards, left, q-1);
		quick_sort(cards, q+1, right);
	}
}


