void mergeSort(vector<Card>& A, int l, int r)
{
  if (l + 1 < r)
  {
    int m = (l + r) / 2;
    mergeSort(A, l, m);
    mergeSort(A, m, r);
    merge(A, l, m, r);
  }
}

void merge(vector<Card>& A, int l, int m, int r)
{
  int n1 = m - l;
  int n2 = r - m;
  vector<Card> L(n1 + 1), R(n2 + 1);
  rep (i, n1) L[i] = A[l + i];
  rep (i, n2) R[i] = A[m + i];
  L[n1].data = make_pair('A', 1e9 + 1); R[n2].data = make_pair('A', 1e9 + 1);

  int i = 0, j = 0;
  for (int k = l; k < r; ++k)
  {
    if (L[i] <= R[j])
    {
      A[k] = L[i++];
    }
    else
    {
      A[k] = R[j++];
    }
  }
}

int partition(vector<Card>& A, int p, int r)
{
  Card x = A[r];
  int i = p - 1;

  for (int j  = p; j < r; ++j)
  {
    if (A[j] <= x)
    {
      ++i;
      swap(A[i], A[j]);
    }
  }
  swap(A[i + 1], A[r]);

  return i + 1;
}

void quickSort(vector<Card>& A, int p, int r)
{
  if (p < r)
  {
    int q = partition(A, p, r);
    quickSort(A, p, q - 1);
    quickSort(A, q + 1, r);
  }
}

