int Partition(vector<pair<char, int> >& A, int p, int r)
{
    int x = A[r - 1].second;
    int i = p - 1;

    for(int j = p; j < r - 1; ++j){
        if(A[j].second <= x){
            ++i;
            swap(A[i], A[j]);
        }
    }
    swap(A[i + 1], A[r - 1]);
    return i + 1;
}

void QuickSort(vector<pair<char, int> >& A, int p, int r)
{
    if(p < r){
        int q = Partition(A,p,r);
        QuickSort(A,p,q);
        QuickSort(A,q + 1,r);
    }
}

