void quicksort(Card A[], int p, int r){
    if (p >= r) return;
    int q = partition(A, p, r);
    quicksort(A, p, q-1);
    quicksort(A, p+1, r);
}

int partition(Card A[], int p, int r){
    int x = A[r].num;
    int i = p - 1;
    for(int j=p; j <= r-1; j++){
        if (A[j].num <= x) {
            i++;
            swap(A[i], A[j]);
        }
    }
    swap(A[i+1], A[r]);
    return i + 1;
}

