#include<iostream>

using namespace std;

int partition(pair<char,int>* a, int p, int r) {
	int x = a[r - 1].second;
	int cnt = p - 1;
	for (int i = p;i < r;i++) {
		if (a[i].second <= x) {
			cnt++;
			swap(a[cnt], a[i]);
		}
	}
	return cnt;
}

void quicksort(pair<char, int>* a, int l, int r) {
	if (l < r) {
		int q = partition(a, l, r);
		quicksort(a, l, q);
		quicksort(a, q + 1, r);
	}
}

