static const int MAX_NUM = 100000;

int PartitionSort(pair<int, char> elem[], int start, int end)
{
    int i;
    int target;
    int left;

    left = start - 1;
    target = elem[end-1].first;

    for (i = start; i < end - 1; i++) {
        if (target >= elem[i].first) {
            ++left;
            swap(elem[left], elem[i]);
        }
    }
    ++left;
    swap(elem[left], elem[end-1]);

    return left;
}


void QuickSort(pair<int, char> elem[], int start, int end)
{
    int mid;

    mid = PartitionSort(elem, start, end);

    if (start < mid - 1) {
        QuickSort(elem, start, mid);
    }
    if (mid < end - 1) {
        QuickSort(elem, mid, end);
    }

    return;
}

