void merge(vector<Card> &v, vector<Card> &vl, vector<Card> &vr) {
  int n = (int)v.size();
  int i, j, k;
  for (i = 0, j = 0, k = 0; i < n; ++i) {
    if (j >= (int)vl.size()) v[i] = vr[k++];
    else if (k >= (int)vr.size()) v[i] = vl[j++];
    else if (vl[j] <= vr[k]) v[i] = vl[j++];
    else v[i] = vr[k++];
  }
}

