  int n = (int)v.size();
  if (n > 1){
    vector<Card> vl(v.begin(), v.begin() + n/2);
    vector<Card> vr(v.begin() + n/2, v.end());
    mergesort(vl);
    mergesort(vr);
    merge(v, vl, vr);
  }
}

