int partition(CardData A[],int n,int min,int max) {
	int r = A[max].value;
	int i = min - 1;

	for (int j = min; j <max; j++) {
		if (A[j].value <= r) {
			swap(A[j], A[++i]);
		}
	}

	swap(A[max], A[i + 1]);

	return i+1;
}

void quickSort(CardData A[],int n, int min, int max) {
	int q;
	if (min < max) {
		int q = partition(A, n, min, max);
				quickSort(A, n, min, q - 1);
				quickSort(A, n, q + 1, max);
	}
}

void merge(CardData A[], int n,int left ,int mid ,int right) {
	int n1 = mid - left;
	int n2 = right - mid;
	for (int t = left; t < n1; t++)L[t] = A[left+t];
	for (int t = mid;  t < n2; t++)R[t] = A[mid +t];
	L[n1].value = R[n2].value = SENTINEL;

	int l = 0, r = 0;
	for (int t = 0; t < right-left; t++) {
		if (L[left + l].value > R[right + r].value) {
			A[t] = R[right + r];
			r++;
		}
		else {
			A[t] = L[left + l];
			l++;
		}
	}

}

