int merge(vector<P> &a, int left, int mid, int right) {
    int n1 = mid - left;
    int n2 = right - mid;
    vector<P> l(n1 + 1);
    vector<P> r(n2 + 1);

    for (int i = 0; i < n1; i++) {
        l[i] = a[left + i];
