int partition(Card A[], int p, int r) {
    int x = A[r].num;
    int i = p-1; // i以下がxより小さな値
    for (int j = p; j < r; j++) { // A[j]がxと比べる値
        if (A[j].num <= x) {
            i++;
            swap(A[i], A[j]);
        }
    }
    swap(A[i+1], A[r]);
    return i+1;
}

void quickSort(Card A[], int p, int r) {
    if (p < r) {
        int q = partition(A, p, r);
        quickSort(A, p, q-1);
        quickSort(A, q+1, r);
    }
