void swap(int A[], int i, int j){
    int q = A[i];
    A[i] = A[j];
    A[j] = q;
}

int partition(int A[], int i, int j){
    int t = i;
    while(i < j){
        if(A[j] > A[i]){
            swap(A, t, i);
            t++;
        }
        i++;
    }
    swap(A, t, j);
    return t;
}

