    Card Temp;

    for(int j = p; j < r; j++){
        if(List[j].Value <= x){
            i++;
            Temp    = List[i];
            List[i] = List[j];
            List[j] = Temp;
        }
    }
    Temp    = List[i + 1];
    List[i + 1] = List[r];
    List[r] = Temp;

    return i + 1;
}

void Quicksort(std::vector<Card>& List, int p, int r)
