struct tramp{
    char mark;
    int number;
    int order;
};

void sw(tramp *a,tramp* b){
    tramp temp = *a;
    *a=*b;
    *b=temp;
}
int partition(tramp* A,int p, int r){
    int x= A[r].number;
    int i=p-1;
    for(int j=p;j<r;j++){
        if(A[j].number<=x){
            i=i+1;
            sw(&A[i],&A[j]);
        }
    }
    sw(&A[i+1],&A[r]);
    return i+1;
}
void quick(tramp*A,int p,int r){
    if(p<r){
        int q=partition(A,p,r);
        quick(A,p,q-1);
        quick(A,q+1,r);
    }
}

