typedef pair<int, char> P;

void exchange(vector<P> &v, int a, int b) {
    P temp = v[a];
    v[a] = v[b];
    v[b] = temp;
}

int partition(vector<P> &v, int p, int r) {
    int x = v[r].first;
    int i = p-1;
    for (int j = p; j < r; j++) {
        if (v[j].first <= x) {
            i++;
            exchange(v, i, j);
        }
    }
    exchange(v, i+1, r);
    return i+1;
}

bool stable(vector<P> v, vector<P> w) {
    REP(i,v.size()) {
        if (v[i].second != w[i].second) return false;
    }
