using namespace std;
struct Element {
    char c;
    long number;
};

void swap(Element &a, Element &b) {
    Element temp = a;
    a = b;
    b = temp;
}


int partition(Element *A, int p, int r) {
    Element x = A[r];
    int i = p - 1;
    for (int j = p; j <= r - 1; j++) {
        if (A[j].number <= x.number) {
            i++;
            Element temp = A[j];
            A[j] = A[i];
            A[i] = temp;
        }
    }
    A[r] = A[i + 1];
    A[i + 1] = x;
    return i + 1;
}


void qs(Element *A, int left, int right) {
    if (left < right) {
        int mid = partition(A, left, right);
        qs(A, left, mid - 1);
        qs(A, mid + 1, right);
    }
}

