int part(vector<Card>& v, int l, int r)
{
    Card pivot = v[r];
    int i = l - 1;

    FOR(j, l, r) {
        if(A[j].num <= pivot.num) {
            ++i;
            swap(A[i], A[j]);
        }
    }
    swap(A[i+1], A[r]);

    return i + 1;
}

void qs(vector<Card>& v, int l, int r)
{
    if(l >= r) return;

    int mid = part(v, l, r);
    qs(v, l, mid-1);
    qs(v, mid+1, r);
}

