    }
    quicksort(b,0,n-1);
    guibing(a,0,n);
    for (int i=0;i<n;i++)
    {
        if(a[i].fu!=b[i].fu)
         biao=0;
    }
    if(biao==0) printf("Not stable\n");
    else printf("Stable\n");
    for (int i=0;i<n;i++)
    {
        printf("%c %d\n",b[i].fu,b[i].shu);
    }
    return 0;
}

