using namespace std;

template<typename T>
int partition(T ar[], int p, int r){
    T pivot = ar[r];
    int i = p - 1;
    for (int j = p; j <= r - 1; j++) {
        if(ar[j] <= pivot){
            i++;
            swap(ar[i], ar[j]);
        }
    }
    i++;
    swap(ar[i], ar[r]);
    return i;
}

template<typename T>
void quicksort(T ar[], int p, int r){
    if(p < r){
        int q = partition(ar, p, r);
        quicksort(ar, p, q - 1);
        quicksort(ar, q + 1, r);
    }
}

