#include<stdio.h>
#define MAX 100000
#define SENTINEL 2000000000

struct Card{
	char suit;
	int value;
};

struct Card L[MAX / 2 + 2], R[MAX / 2 + 2];

void merge(struct Card A[], int n, int left, int mid, int right){
	int i, j, k;
	int n1 = mid - left;//要素の中央値-左端
	int n2 = right - mid;//右端-要素の中央値
	for(i = 0; i < n1; i++) L[i] = A[left + i];
	for(i = 0; i < n2; i++) R[i] = A[mid + i];
	L[n1].value = R[n2].value = SENTINEL;//最大値の設定
	i = j = 0;
	for(k = left; k < right; k++){
		if(L[i].value <= R[j].value){
			A[k] = L[i++];
		}else{
			A[k] = R[j++];
		}
	}
}

void mergeSort(struct Card A[], int n, int left, int right){
	int mid;
	if(left + 1 < right){
		mid = (left + right) / 2;//平均値を求める
		mergeSort(A, n, left, mid);//rightにmidを代入
		mergeSort(A, n, mid, right);//leftにmidを代入
		merge(A, n, left, mid, right);
	}
}

int partition(struct Card A[], int n, int p, int r){
	int i, j;
	struct Card t, x;
	x = A[r];
	i = p - 1;
	for(j = p; j < r; j++){
		if(A[j].value <= x.value){//A[j]がA[r]よりも小さかった時の処理
			i++;
			t = A[i]; A[i] = A[j]; A[j] = t;//値の入れ替え
		}
	}
	t = A[i + 1]; A[i + 1] = A[r]; A[r] = t;//値の入れ替え
	return i + 1;
}

void quickSort(struct Card A[], int n, int p, int r){
	int q;
	if(p < r){
		q = partition(A, n, p, r);
