int partition(Card A[], int p, int r) {
    int x = A[r].num;
    int i = p - 1;
    for(int j = p; j < r; j++) {
        if(A[j].num <= x) {
            i = i + 1;
            swap(A[i], A[j]);
        }
    }
    swap(A[i + 1], A[r]);
    return i + 1;
}

void quicksort(Card A[], int p, int r) {
    if(p < r) {
        int q = partition(A, p, r);
        quicksort(A, p, q-1);
        quicksort(A, q+1, r);
    }
    return;
}

bool checkStable(Card A[], Card B[], int n){
    for(int i = 0; i < n; i++) {
        if(A[i].suit != B[i].suit) return false;
    }
    return true;
}

