void _merge(Card a[], int l, int m, int r)	//[l, r)
{
	int i, j, k;
	int n1 = m - l;
	int n2 = r - m;
	for (i = 0; i < n1; ++i)
		L[i] = a[l + i];
	for (i = 0; i < n2; ++i)
