int partition(card A[], int l, int r)
{
    card pivot = A[r - 1];
    int i, j;
    for(i = j = l; i < r - 1; i++) {
        if (A[i].num <= pivot.num) {
            card tmp = A[i];
            A[i] = A[j];
            A[j++] = tmp;
        }
    }
    A[r - 1] = A[j];
    A[j] = pivot;
    return j;
}


void quick_sort(card A[], int l, int r)
{
    if (r - l > 1) {
        int pivot_index = partition(A, l, r);
        quick_sort(A, l, pivot_index);
        quick_sort(A, pivot_index + 1, r);
    }
}

