bool match_cards(Card cards1[], Card cards2[], int n)
{
  for (int i = 0; i < n; ++i)
  {
    if (cards1[i].suit != cards2[i].suit ||
        cards1[i].number != cards2[i].number)
    {
      return false;
    }
  }
  return true;
}

