int make_partition(vector<pair<int, char>>& A, int p, int r) {
	int x = A[r].first;
	int i = p - 1;
	for (int j = p; j < r; ++j) {
		if (A[j].first <= x) {
			++i;
			swap(A[j], A[i]);
		}
	}
	swap(A[i + 1], A[r]);
	return i + 1;
}

void quickSort(vector<pair<int, char>>& A, int p, int r) {
	if (p < r) {
		int q = make_partition(A, p, r);
		quickSort(A, p, q - 1);
		quickSort(A, q + 1, r);
	}
}

