    int mid = (left + right)/2;
    if (right - left > 1) {
        MegeSort(A,left,mid);
        MegeSort(A,mid,right);
        comb(A,left,mid,right);
    }
}

int partition(Card A[],int left,int right){
    int index=0;
    int a = left;
    for (int i = left; i < right - left; i++) {
        if (A[i].num <= A[right - 1].num) {
            Card c;
            c = A[i];
            A[i] = A[a];
            A[a] = c;
            a++;
            index = a;
        }
