  for (int i=0; i<n1; i++) {
    L[i]=A[left+i];
  }
  for (int i=0; i<n; i++) {
    R[i]=A[mid+i];
  }
  L[n1].value=R[n2].value=SENTNEL;
  int i=0, j=0;
  for (int k=left; k<right; k++) {
    if (L[i].value<=R[j].value) {
      A[k]=L[i++];
    } else {
      A[k]=R[j++];
    }
  }
}
void mergeSort(struct Card A[],int n,int left,int right) {
  int mid;
  if(left+1<right) {
    mid=(left+right)/2;
    mergeSort(A,n,left,mid);
