void quicksort(std::vector<card> &A, int l, int r) {
	if(r - l <= 1) return;
	int ptr = l;
	for(int i = l; i < r - 1; ++i) {
		if(A[i].number <= A[r - 1].number) {
			std::swap(A[i], A[ptr++]);
		}
	}
	std::swap(A[ptr], A[r - 1]);
	quicksort(A, l, ptr);
	quicksort(A, ptr + 1, r);
}
