using namespace std;

template<typename T>
int partition(T ar[], int p, int r){
    T pivot = ar[r];
    int i = p - 1;
    for (int j = p; j <= r - 1; j++) {
        if(ar[j] <= pivot){
            i++;
            swap(ar[i], ar[j]);
        }
    }
    i++;
    swap(ar[i], ar[r]);
    return i;
}

template<typename T>
void quicksort(T ar[], int head, int last){
    stack<int, vector<int> > starg;
    starg.push(head);
    starg.push(last);

    while (!starg.empty()) {
        int p, r;
        r = starg.top();
        starg.pop();
        p = starg.top();
        starg.pop();

        if(p < r){
            int q = partition(ar, p, r);
            starg.push(q + 1);
            starg.push(r);

            starg.push(p);
            starg.push(q - 1);
        }
    }
}

