void Counting_Sort(char ID[],char idID[],int A[],int B[],int k){
  int *C = new int[k+1];
  for(int i=0;i<=k;i++)C[i]=0;
  for(int j=1;j<=n;j++)C[A[j]] = C[A[j]] + 1;
  for(int i=1;i<=k;i++)C[i]=C[i]+C[i-1];
  for(int j=n;j>=1;j--){
    B[C[A[j]]] = A[j];
    idID[C[A[j]]] = ID[j];
    C[A[j]] = C[A[j]]-1;
  }
  delete [] C;
}


int Partition(char ID[],int A[],int p,int r){
  int x = A[r];
  int i = p-1;
  for(int j=p;j<r;j++){
    if(A[j] <= x){
      i = i+1;
      char ch = ID[i];
      ID[i] = ID[j];
      ID[j] = ch;
      int h=A[i];
      A[i] = A[j];
      A[j] = h;
    }
  }
  char ch = ID[i+1];
  ID[i+1] = ID[r];
  ID[r] = ch;
  int h = A[i+1];
  A[i+1] = A[r];
  A[r] = h;
  return i+1;
}

void Quicksort(char ID[],int A[],int p,int r){
  if(p<r){
    int q = Partition(ID,A,p,r);
    Quicksort(ID,A,p,q-1);
    Quicksort(ID,A,q+1,r);
  }
}


