static bool isStable(Card in[], Card out[], int num) {
  for (int i = 0; i < num; i++) {
    for (int j = i + 1; j < num; j++) {
      for (int a = 0; a < num; a++) {
        for (int b = a + 1; b < num; b++) {
          if (in[i].value == in[j].value && in[i] == out[b] && in[j] == out[a]) {
            return false;
          }
        }
      }
    }
  }
  return true;
}

