void marge(int s[100000], char m[100000], int head, int mid, int tail) {

	int x[100000];
	char y[100000];
	int M = mid;

	for (int i = head; i < tail; i++) {
		x[i] = s[i];
		y[i] = m[i];
	}

	for (int i = head; i < tail; i++) {
		if (mid == tail) {
			s[i] = x[head];
			m[i] = y[head];
			head++;
		}
		else if (head == M) {
			s[i] = x[mid];
			m[i] = y[mid];
			mid++;
		}
		else if (x[head] <= x[mid]) {
			s[i] = x[head];
			m[i] = y[head];
			head++;
		}
		else {
			s[i] = x[mid];
			m[i] = y[mid];
			mid++;
		}
	}

}

