int partition(vector<pair<char, int>> &a, int p, int r) {
	int i = p-1, pivot = r;
	for (int j = p; j < r; j++) {
		if (a[j].S <= a[pivot].S) {
			swap(a[++i], a[j]);
		}
	}
	swap(a[pivot], a[++i]);
	return i;
}

