int Partition( std::vector<std::pair<char, int>>& v, int p, int r ){
    int x = v[r].second;
    int i = p - 1;
    for( int j = p; j < r; ++j ){
        if( v[j].second <= x ){
            v[++i].swap( v[j] );
        }
    }
    v[i+1].swap( v[r] );
    return i + 1;
}

void QuickSort( std::vector<std::pair<char, int>>& v, int p, int r ){
    if( p < r ){
        int q = Partition( v, p, r );
        QuickSort( v, p, q-1 );
        QuickSort( v, q+1, r );
    }
}

int BinarySearch( std::vector<std::pair<char, int>>& v, int key ){
    int left = 0;
    int right = v.size();
    int mid;
    //std::cout << key << ": ";
    while( left < right ){
        mid = ( left + right ) / 2;
        if( v[mid].second == key ){
            //std::cout << key;
            return mid;
        }else if( key < v[mid].second ){
            right = mid;
        }else{
            left = mid + 1;
        }

        if( key == 1 ){
            //std::cout << v[mid] << " ";
        }
    }
    return mid;
}

