    for (int j = p; j <= r - 1; j++) {
        if (A[j].number <= x.number) {
            i++;
            Element temp = A[j];
            A[j] = A[i];
            A[i] = temp;
        }
    }
    A[r] = A[i + 1];
    A[i + 1] = x;
    return i + 1;
}


