int get_uint() {
    int s = 0;
    int a = getchar_unlocked();
    if(a < 48 || 57 < a) return a;
    while(47 < a && a < 58) {
        s = 10 * s + (a & 0xf);
        a = getchar_unlocked();
    }
    return s;
}
void put_uint(int s) {
    if(!s) {
        putchar_unlocked('0');
        return;
    }
    char buf[11];
    int i = 0;
    while(s) buf[i++] = (char)(s % 10 + '0'), s /= 10;
    while(i--)putchar_unlocked(buf[i]);
}
