int partition(card *A,int p,int r)
{
  int x,i,j;
  card change;

  x = A[r].number;

  i = p-1;

  for(j = p ; j < r ; j++)
    {
      if(A[j].number <= x)
	{
	  i++;
	  change = A[i];
	  A[i] = A[j];
	  A[j] = change;
	}
    }
  change = A[i+1];
  A[i+1] = A[r];
  A[r] = change;

  return i+1;
}

void quicksort(card *A,int p,int r)
{
  int q;
  if(p < r)
    {
      q = partition(A,p,r);
      quicksort(A,p,q-1);
      quicksort(A,q+1,r);
    }
  return;
}

int Stable(card *in,card *out,int n)
{
  int i,j,a,b;

  for(i = 0 ; i < n-1 ; i++)
    {
      for(a = 0 ; a < n ; a++)
	{
	  if(out[i].number == out[i+1].number)
	    {　
		/* outの隣同士の数字が同じなら、inとoutの数字の一致する場所を探す */

	      if(in[a].number == out[i].number)
		{
		  　/* 数字が一致する場所を見つけたら、絵が同じか調べる */

		  if(in[a].mark == out[i].mark)
		    {
		      /* 絵も一致するなら今の所安定 */

		       /* このペアはもう使わないので判断の邪魔にならない数字を代入 */
		      in[a].number = -1;

		      break; /* inのループを脱出、次のoutの探索へ */
		    }
		  else return 0; /* 数字が一致するが絵が違うなら不安定 */
		}
	    }
	}

    }
  return 1;
}

