        if (A[j].value <= x) {
            i++;
            tmp_m = A[i].mark;
            tmp_v = A[i].value;
            A[i].mark = A[j].mark;
            A[i].value = A[j].value;
            A[j].mark = tmp_m;
            A[j].value = tmp_v;
        }
    }
    tmp_m = A[i + 1].mark;
    tmp_v = A[i + 1].value;
    A[i + 1].mark = A[r].mark;
    A[i + 1].value = A[r].value;
    A[r].mark = tmp_m;
    A[r].value = tmp_v;

    return i + 1;
}

