void swap( card *a, card *b ){

    char t = a->t;
    int v = a->v;
    int i = a->i;

    a->t = b->t;
    a->v = b->v;
    a->i = b->i;

    b->t = t;
    b->v = v;
    b->i = i;
}

int partition( card *a, int p, int r ){

    int i, j;
    int x;

    x = a[r].v;
    i = p-1;


    for( j=p; j<r; j++ ){

        if( a[j].v <= x ){
            i++;
            swap( &a[i], &a[j] );
        }
    }
    i++;
    swap( &a[i], &a[r] );


    return i;

}

void quicksort( card *a, int p, int r ){

    int q;

    if( p<r ){
        q = partition( a, p, r );
        quicksort( a, p, q-1 );
        quicksort( a, q+1, r );
    }
}



