/* Partition */
int partition(Card *A, int p, int r) {
  Card x, temp;
  int i, j;

  x = A[r];
  i = p - 1;

  for ( j = p; j < r; j++ ) {
    if ( A[j].num <= x.num ) {
      i++;
      temp = A[i];
      A[i] = A[j];
      A[j] = temp;
    }
  }
  temp = A[i+1];
  A[i+1] = A[r];
  A[r] = temp;

  return i + 1;
}

/* Quick Sort */
void quickSort(Card *A, int p, int r) {
  int q;
  if ( p < r ) {
    q = partition(A, p, r);
    quickSort(A, p, q - 1);
    quickSort(A, q + 1, r);
  }
}

/* Merge */
void merge(Card *B, int left, int mid, int right){
  int n1, n2;
  int i, j, k;

  n1 = mid - left;
  n2 = right - mid;

  for ( i = 0; i < n1; i++ ) L[i] = B[i+left];
  for ( i = 0; i < n2; i++ ) R[i] = B[i+mid];

  L[n1].num = 1000000500;
  R[n2].num = 1000000500;

  i = 0;
  j = 0;

  for ( k = left; k < right; k++ ) {
    if ( L[i].num <= R[j].num ) {
      B[k] = L[i];
      i++;
    }else {
      B[k] = R[j];
      j++;
    }
  }

}

/* Merge Sort */
void mergeSort(Card *B, int left, int right) {
  int mid;

  if ( left + 1 < right ) {
    mid = (left + right) / 2;
    mergeSort(B, left, mid);
    mergeSort(B, mid, right);
    merge(B, left, mid ,right);
  }
}

