  int i = p-1;
  int tmp=0,tmp2=0;
  char c;

  for(j=p;j <= r-1;j++){
    if(A[j] <= x){
      i=i+1;
      tmp = A[j];
      A[j] = A[i];
      A[i] = tmp;
      c = B[j];
