void merge(int left, int mid, int right) {
	int n1 = mid - left;
	int n2 = right - mid;
	Card cardR[N], cardL[N];
	int i, j, k;

	for (i = 0; i <= n1 - 1; i++)
		cardR[i] = card2[left + i];
	for (i = 0; i <= n2 - 1; i++)
		cardL[i] = card2[mid + i];

	cardR[n1].num = cardL[n2].num = SENTINEL;
	i = j = 0;

	for (k = left; k <= right - 1; k++) {
		if (cardL[i].num <= cardR[j].num) {
			card2[k] = cardL[i];
			i++;
		} else {
			card2[k] = cardR[j];
			j++;
		}
	}
}

void mergeSort(int left, int right) {
	int mid;

	if (left + 1 < right) {
		mid = (left + right) / 2;
		mergeSort(left, mid);
		mergeSort(mid, right);
		merge(left, mid, right);
	}

}
void swapOfInt(int *a, int *b) {
	int tmp;

	tmp = *a;
	*a = *b;
	*b = tmp;
}

void swapOfChar(char *a, char *b) {
	char tmp;

	tmp = *a;
	*a = *b;
	*b = tmp;
}

int partition(int p, int r) {
	int x, i, j;

	x = card1[r].num;
	i = p - 1;

	for (j = p; j < r; ++j) {
		if (card1[j].num <= x) {
			i++;
			swapOfInt(&card1[i].num, &card1[j].num);
			swapOfChar(&card1[i].c, &card1[i].c);
		}
	}
	swapOfInt(&card1[i + 1].num, &card1[r].num);
	swapOfChar(&card1[i + 1].c, &card1[r].c);
	return i + 1;
}

void quickSort(int p, int r) {
	int q;

	if (p < r) {
		q = partition(p, r);
		quickSort(p, q - 1);
		quickSort(q + 1, r);
	}
}

