typedef struct card {
	char suite[4];
	int value;
	int order;
} TYPE;

int
partition(TYPE *a, int p, int r)
{
	TYPE x = a[r];
	TYPE v;
	int i;

	for (i = p; i < r; i++) {
		if (PRED(&a[i], &x))
			continue;

		SWAP(a[p], a[i], v);
		p++;
	}

	SWAP(a[p], a[r], v);

	return p;
}

void
quick_sort(TYPE *a, int p, int r)
{
	if (p < r) {
		int q = partition(a, p, r);
		quick_sort(a, p, q - 1);
		quick_sort(a, q + 1, r);
	}
}

