    for( i = 0 ; i < n1 ; i++ ) L[i] = S[left+i];
    for( i = 0 ; i < n2 ; i++ ) R[i] = S[mid+i];

    L[n1].value = R[n2].value = INFTY;

    i = j = 0;

    for( k = left ; k < right ; k++ ){
        count++;
        if( L[i].value <= R[j].value ){
