int partition(Card A[], int p, int r)
{
  int i, j, x;
  Card tmp;

  x = A[r].value;
  i = p-1;

  for( j = p ; j < r ; j++ ){
    if( A[j].value <= x){
      i++;
      tmp = A[i];
      A[i] = A[j];
      A[j] = tmp;
    }
  }

  tmp = A[i+1];
  A[i+1] = A[r];
  A[r] = tmp;

  return i+1;
}

