void swap( Trump *a, Trump *b ){
    Trump tmp;

    tmp = *a;
    *a = *b;
    *b = tmp;

    return ;
}

int partition( Trump A[], int p, int r ){
    int i, j, x;

    x = A[r].x;
    for(i = p-1, j = p; j<r; j++){
	if(A[j].x <= x){
	    i++;
	    swap( &A[j], &A[i] );
	}
    }
    swap( &A[i+1], &A[r] );
    return i+1;
}

void quickSort( Trump A[], int p, int r ){
    int q;

    if ( p < r ){
	q = partition( A, p, r );
	quickSort( A, p, q-1 );
	quickSort( A, q+1, r );
    }
