void merge( Trump A[], int left, int mid, int right ){
    Trump *L, *R;
    int n1 = mid - left;
    int n2 = right - mid;
    int i, j, k;
    // allocate the memory for merge
    L = malloc(sizeof(Trump) * (n1+1)); //left side
    R = malloc(sizeof(Trump) * (n2+1)); //right side

    // substitute the value of A-array for each divided array 
    for (i = 0; i<n1; i++)
	L[i] = A[left + i];
    for (i = 0; i<n2; i++)
	R[i] = A[mid + i];
    //as sentinels
    L[n1].x = INFTY;
    R[n2].x = INFTY;
    //sort
    i = 0;
    j = 0;
    for (k = left; k<right; k++){
	if (R[j].x == INFTY){
	    A[k] = L[i];
	    i++;
	}
	else if (L[i].x == INFTY){
	    A[k] = R[j];
	    j++;
	}
	else if (L[i].x <= R[j].x){
	    A[k] = L[i];
	    i++;
	}
	else if (L[i].x > R[j].x){ 
	    A[k] = R[j];
	    j++;
	}
    }
    free(L);
    free(R);
    return ;
}

void MergeSort( Trump A[], int left, int right ){
    int mid;
    if (left+1 < right){
	mid = (left + right)/2;
	MergeSort(A, left, mid);
	MergeSort(A, mid, right);
	merge(A, left, mid, right);
    }
    return ;
}

