// Partition function
int Partition(Card A[], int p, int r){
  int x, i, j;
  // i is <, j is |

  // Set x, i
  x = A[r];
  i = p - 1;

  // Partition
  for(j = 0; j < r; j++){

    if(A[j] <= x){
      i++;
      SWAP(int, A[i], A[j]);
    }
  }
  SWAP(int, A[i + 1], A[r]);

  return i + 1;
}

