void BubbleSort(char BC[], char BN[], int len){

  int i,j;
  int tmpC, tmpN;

  for(i=1;i<=len;i++){
    for(j=len;j>=i+2;j--){
      if(BN[j] < BN[j-1]){
	tmpN = BN[j-1];
	tmpC = BC[i];
	BN[j-1] = BN[j];
	BC[j-1] = BC[j];
	BN[j] = tmpN;
	BC[j] = tmpC;
      }
    }
  }
}



