      i = i + 1;
      tmpN = A[j];
      tmpC = C[j];
      A[j] = A[i];
      C[j] = C[i];
      A[i] = tmpN;
      C[i] = tmpC;
    }
  }

  tmpN = A[i+1];
  tmpC = C[i + 1];
  A[i+1] = A[r];
  C[i + 1] = C[r];
  A[r] = tmpN;
  C[r] = tmpC;

  return i+1;
}


