int Stable(card *in,card *out,int n)
{
  int i,j,a,b;

  for(i = 0 ; i < n-1 ; i++)
    {
      for(a = 0 ; a < n ; a++)
	{
	  if(out[i].number == out[i+1].number)
	    {
		/* outの隣同士の数字が同じなら、inとoutの数字の一致する場所を探す */

	      if(in[a].number == out[i].number)
		{
		  /* 数字が一致する場所を見つけたら、絵が同じか調べる */

		  if(in[a].mark == out[i].mark)
		    {
		      /* 絵も一致するなら今の所安定 */

		       /* このペアはもう使わないので判断の邪魔にならない数字を代入 */
		      in[a].number = -1;

		      break; /* inのループを脱出、次のoutの探索へ */
		    }
		  else return 0; /* 数字が一致するが絵が違うなら不安定 */
		}
	    }
	}

    }
  return 1;
}

