    }
}

int partition(struct Card Quick[], int n, int p,int r){
    int i,j;
    struct Card t, x;
    x = Quick[r];
    i = p-1;
    for(j=p; j<r; j++){
        if(Quick[j].value <= x.value){//基準の値より小さい場合は大きいと分類された先頭の値を入れ替える
            i++;
            t = Quick[i];
            Quick[i] = Quick[j];
            Quick[j] = t;
        }
    }
    //基準の値と大きいと分類された先頭の値を入れ替える
    t = Quick[i+1];
    Quick[i+1] = Quick[r];
    Quick[r] = t;
    return i+1;
}

