int partition(char b[], int a[], int p, int r)
{
	int x, i, j, temp;
	char tempc;

	x = a[r];
	i = p - 1;

	for (j = p; j < r; j++) {
		if (a[j] <= x) {
			i++;
			temp = a[j];
			a[j] = a[i];
			a[i] = temp;
			tempc = b[j];
			b[j] = b[i];
			b[i] = tempc;
		}
	}
	temp = a[i + 1];
	a[i + 1] = a[r];
	a[r] = temp;
	tempc = b[i + 1];
	b[i + 1] = b[r];
	b[r] = tempc;

	return i + 1;
}


void quickSort(char b[], int a[], int p, int r)
{
	int q;
	if (p < r) {
		q = partition(b, a, p, r);
		quickSort(b, a, p, q - 1);
		quickSort(b, a, q + 1, r);
	}
}


