{
  int i,j;
  struct Card t,x;
  x=A[r];
  i=p-1;
  for(j=p;j<r;j++)
    {
      if(A[j].value <= x.value)
	{
	  i++;
	  t=A[i];A[i]=A[j];A[j]=t;
	}
    }
  t=A[i+1];A[i+1]=A[r];A[r]=t;
  return i+1;
}

