  int n1, n2, i, j, k;

  n1 = m - l;
  n2 = r - m;
  for(i = 0 ; i < n1 ; i++) L[i] = A[l + i];
  for(i = 0 ; i < n2 ; i++) R[i] = A[m + i];
  L[n1].num = R[n2].num = SENTI;

