int partition(card *A, int p, int r){
  int i, j, x;

  x = A[r].n;
  i = p-1;

  for(j=p; j<r; j++){
    if(A[j].n <= x){
      i = i+1;
      swap(&A[i], &A[j]);
    }
  }
  swap(&A[i+1], &A[r]);

  return i+1;
}

void swap(card *a, card *b){
  card temp;

  temp.n = a->n;
  a->n = b->n;
  b->n = temp.n;

  temp.c = a->c;
  a->c = b->c;
  b->c = temp.c;

}

