void bubblesort(Card A[],int n){
  int i,j,flag;

  flag = 1;

  while(flag){
    flag = 0;
    for(i=0;i < n;i++){
      for(j=n-1;j >= i+1;j--){

        if( A[j].num < A[j-1].num ){
          swap(&A[j],&A[j-1]);

          flag = 1;

        }
      }
    }
  }
}

void swap(Card *in,Card *out){
  Card temp;

  temp = *in;
  *in = *out;
  *out = temp;
}

int partition(Card A[],int p,int r){
  Card x;
  int i=0;
  int j;

  x = A[r];
  i = p-1;

  for(j=p;j<r;j++){
    if(A[j].num <= x.num){
      i = i+1;
      swap(&A[i],&A[j]);

    }
  }
  swap(&A[i+1],&A[r]);

  return i+1;
}

void quicksort(Card A[],int p,int r){
  int q;

  if(p<r){
    q = partition(A,p,r);
    quicksort(A,p,q-1);
    quicksort(A,q+1,r);
  }
}
