		q = partition( A, Order, p, r );
		//printf("回数：%d partition：%d p:%d r:%d\n\n", kaisu, q, p, r);
		kaisu++;
		Quicksort(A, Order, p, q-1);
		Quicksort(A, Order, q+1, r);
	}
	return 0;
}



int isStable( int *in, int *out, int N )
{
    int i = 0;
    int j = 0;
    int a = 0;
    int b = 0;

    for ( i = 0; i < N; i++ ) {
        for ( j = i + 1; j < N; j++ ) {
            for ( a = 0; a < N - 1; a++ ) {
                for ( b = a + 1; b < N; b++ ) {
                    if ( in[i] == in [j] ) {
                        if ( in[i] == out[b] && in[j] == out[a] ) {

                            return -1;
                        }
                    }
                }
            }
        }
    }
    return 0;
}

#include<stdio.h>
#define MAX 100000
#define SENTINEL 2000000000

struct Card{
    char suit;
    int value;
};

struct Card L[MAX/2+2],R[MAX/2+2];

void merge(struct Card A[], int n, int left, int mid, int right){
    int i,j,k;
    int n1=mid-left;
    int n2=right-mid;
    for(i=0;i<n1;i++) L[i]=A[left+i];
    for(i=0;i<n2;i++) R[i]=A[mid+i];
    L[n1].value=R[n2].value=SENTINEL;
    i=j=0;
    for(k=left;k<right;k++){
        if(L[i].value<=R[j].value) A[k]=L[i++];
        else A[k]=R[j++];
    }
}

void mergeSort(struct Card A[], int n, int left, int right){
    int mid;
    if(left+1<right){
        mid=(left+right)/2;
    mergeSort(A,n,left,mid);
    mergeSort(A,n,mid,right);
    merge(A,n,left,mid,right);
    }
}

int partition(struct Card A[], int n, int p, int r){
    int i,j;
    struct Card t,x;
    x=A[r];
    i=p-1;
    for(j=p;j<r;j++){
        if(A[j].value<=x.value){
            i++;
            t=A[i];
            A[i]=A[j];
            A[j]=t;
        }
    }
    t=A[i+1];
    A[i+1]=A[r];
    A[r]=t;
    return i+1;
}

void quickSort(struct Card A[], int n, int p, int r){
    int q;
    if(p<r){
        q=partition(A,n,p,r);
        quickSort(A,n,p,q-1);
        quickSort(A,n,q+1,r);
    }
}

