void merge(int *array, char *cards, int p, int q, int r){
	int n1 = q-p+1;
	int n2 = r-q;
	int left[n1 + 1];
	int right[n2 + 1];
	char leftcard[n1];
	char rightcard[n2];

	for(int i = 0; i < n1; ++i){
		left[i] = array[p + i];
		leftcard[i] = cards[p + i];
	}
	left[n1] = INT_MAX;
	for(int i = 0; i < n2; ++i){
		right[i] = array[q + 1 + i];
		rightcard[i] = cards[q + 1 + i];
	}
	right[n2] = INT_MAX;
	int i=0, j=0;
	for(int k = p; k <= r; ++k){
		if(left[i] <= right[j]){
			array[k] = left[i];
			cards[k] = leftcard[i];
			++i;
		}else{
			array[k] = right[j];
			cards[k] = rightcard[j];
			++j;
		}
	}
}
void mergeSort(int *array, char *cards, int p, int r){
	if(p < r){
		int q = (p+r)/2;
		mergeSort(array, cards, p, q);
		mergeSort(array, cards, q+1, r);
		merge(array, cards, p, q, r);
	}
}
void swap(int p, int r){
	int tmpnum = numbers[p];
	char tmpcard = cards[p];

	numbers[p] = numbers[r];
	cards[p] = cards[r];

	numbers[r] = tmpnum;
	cards[r] = tmpcard;
}
int partition(int p, int r){
	int x = numbers[r];
	int i = p - 1;
	for(int j = p; j < r; ++j){
		if(numbers[j] <= x){
			++i;
			swap(i, j);			
		}
	}
	swap(i+1, r);
	return i + 1;
}

void quickSort(int p, int r){
	if(p < r){
		int q = partition(p, r);
		quickSort(p, q - 1);
		quickSort(q + 1, r);
	}
