void QuickS(int zero,int set){
  int point;

  if(zero<set){
    point=Par(zero,set);

    QuickS(zero,point-1);

    QuickS(point+1,set);
    }
}

int Par(int zero,int set){
  int init;
  int j;
  Tarot last,temp;

  last=Qui[set];
  init=zero-1;

  for(j=zero;j<set;j++){

    if(last.Num>=Qui[j].Num){
      init+=1;
      temp=Qui[init];
      Qui[init]=Qui[j];
      Qui[j]=temp;
    }
  }

  temp=Qui[init+1];
  Qui[init+1]=Qui[set];
  Qui[set]=temp;

  return init+1;
}

