    Left[i]=Mer[lside+i];
  }

  for(i=0;i<Rrenge;i++){
    Right[i]=Mer[center+i];
  }

  Left[Lrenge].Num=Gard;
  Right[Rrenge].Num=Gard;

  jud1=0;
