int partition(int *A, int p, int r){
  int i, j, x, a;
  char b;
  x = A[r-1];
  i = p-1;
  for(j = p; j < r-1; j++){
    if(A[j] <= x){
      i += 1;
      a = A[i];
      A[i] = A[j];
      A[j] = a;
      b = B1[i];
      B1[i] = B1[j];
      B1[j] = b;
