      i = i+1;
      exchange(A[i], A[j]);
    }
  }
  exchange(A[i+1], A[r]);
  return i+1;
}

void Quicksort(int A[], int p, int r) {
  int q;
  if(p < r) {
    q = Partition(A,p,r);
    Quicksort(A,p,q-1);
    Quicksort(A,q+1,r);
  }
}

void Bubblesort(int A[], int n) {
  int i,j;
  for(i = n; i >= 2; --i) {
    for(j = 2; j <= i; ++j) {
      if(B[A[j-1]] > B[A[j]])
	exchange(A[j-1], A[j]);
    }
  }
}

