//Merge_Sortから送られてきたデータを結合する。
void Merge(char MC[], int MN[],int left,int mid,int right){

    int n1 = mid - left + 1;
    int n2 = right - mid;
    int LN[n1 + 1];
    int RN[n2 + 1];
    int LC[n1 + 1];
    int RC[n2 + 1];

    int i,j,k;

    for(i = 1;i <= n1;i++){
      LN[i] = MN[left + i - 1];
      LC[i] = MC[left + i - 1];
    }

    for(i = 1;i <= n2;i++){
      RN[i] = MN[mid + i];
      RC[i] = MC[mid + i];
    }

    LN[n1+1] = 1000000000;
    RN[n2+1] = 1000000000;

    i = 1;
    j = 1;

    for(k = left;k <= right;k++){
      if(LN[i] <= RN[j]){
	MN[k] = LN[i];
	MC[k] = LC[i++];
      }
      else{
	MN[k] = RN[j];
	MC[k] = RC[j++];
      }
    }
}


