  char mk; // mark
  int order; // original order
} card_t;

void swap(card_t *a_p, card_t *b_p){
  card_t k;
  k    = *a_p;
  *a_p = *b_p;
  *b_p = k;
}


int prt(card_t* a_p, int p, int r ){
  int j;
  int x = a_p[r].num;
  int i = p-1;

  for( j = p ; j <= (r-1) ; j++){
    if( a_p[j].num <= x){
      i++;
      swap((a_p+i) ,(a_p+j));
    }
  } 
  swap( (a_p+i+1) ,(a_p+r));

  return i+1;
}

void qsort(card_t* a_p, int p, int r){
  int q;
  if( p < r ){
    q = prt(a_p, p, r);
    qsort(a_p, p, q-1);
    qsort(a_p, q+1, r);
  }
}


