}

int partition(Card Array[], int pIndex, int rIndex) {
    Card x = Array[rIndex];
    int i = pIndex;

    for (int j = pIndex; j < rIndex; j++)
        if (Array[j].val <= x.val)
            swap(Array, i++, j);

    swap(Array, i, rIndex);
    return i;
}

