void Merge(int *B, char *D,int left,int mid,int right){
  int n1, n2, i, j, k, *L, *R;
  char *RC, *LC;
  n1 = mid - left;
  n2 = right - mid;
  L = malloc(sizeof(int)*(n1+1));
  R = malloc(sizeof(int)*(n2+1));
  LC = malloc(sizeof(char)*(n1+1));
  RC = malloc(sizeof(char)*(n2+1));
  for(i = 0; i < n1; i++){
    L[i] = B[left + i];
    LC[i] = D[left + i];
  }
  for(i = 0; i < n2; i++){
    R[i] = B[mid + i];
    RC[i] = D[mid + i];
  }
  L[n1] = SENTINEL;
  R[n2] = SENTINEL;
  LC[n1] = '\0';
  RC[n2] = '\0';
  i = 0;
