void Bubblesort(int *A, char *B, int n){
  int i, j, x;
  char c;
  for(i = 0; i < n; i++){
    for(j = n-1; j > i; j--){
      if(A[j] < A[j-1]){
	x = A[j];
	A[j] = A[j-1];
	A[j-1] = x;
	c = B[j];
	B[j] = B[j-1];
	B[j-1] = c;
      }
    }
  }
}
