    }
    L[n1].value = INFTY;
    R[n2].value = INFTY;
    i = 0; j = 0;
    for(int k = left; k < right; k++){
        if(L[i].value <= R[j].value){
            A[k] = L[i];
            i++;
        }else{
            A[k] = R[j];
            j++;
        }
    }
}

