int IsStable(int Arr[MAX], int Order[MAX], int num ) 
{
	int i = 0;
	int a = 0;
	int b = 0;
	int Storage[MAX2][MAX2] = {};
	int num_for_store = 0;

	for ( a = 0; a < MAX2; a++ ) {
	    for ( b = 0; b < MAX2; b++ ) {
	        Storage[a][b] = -1;
	    }
	}

	num_for_store = Store(Arr, Order, Storage, num);


	for ( i = 0; i < num_for_store; i++ ) {
		for ( a = 0; Storage[i][a] >= 0; a++ ) {
			for ( b = a + 1; Storage[i][b] >= 0; b++ ) {
				if ( Order[Storage[i][a]] > Order[Storage[i][b]] ) {
					return -1;
				}
			}
		}
	}

	return 0;
}

int Store(int Arr[MAX], int Order[MAX], int Storage[MAX2][MAX2], int num )
{
	int i = 0;
	int j = 0;
	int a = 0;
	int b = 0;
	int num_for_store = 0;

	for ( i = 0; i < num; i++ ) {
		if ( Judge_Include(Storage, num_for_store, i) < 0 ) {
			continue;
		}

		for ( j = i+1; j < num; j++ ) {
			if ( Judge_Include(Storage, num_for_store, j) < 0 ) {
				continue;
			}

			if ( Arr[Order[i]] != Arr[Order[j]] ) {
				continue;
			}

			Insert(Arr, Order, i, Storage, num_for_store ,num);
			num_for_store++;
		}
	}

	return num_for_store;
}

int Judge_Include(int Storage[MAX2][MAX2], int num_for_store, int a)
{
	int i = 0;
	int j = 0;

	for ( i = 0; i < num_for_store; i++ ) {
		for ( j = 0; Storage[i][j] >= 0; j++ ) {
			if ( Storage[i][j] == a ) {
				return -1;
			}
		}
	}

	return 0;
}

void Insert(int Arr[MAX], int Order[MAX], int i, int Storage[MAX2][MAX2], int num_for_store, int num ) 
{
	int j = 0;
	int k = 0;

	for ( j = 0; j < num; j++ ) {
		if ( Arr[Order[j]] == Arr[Order[i]] ) {
			Storage[num_for_store][k] = j;
			k++;
		}
	}
}

