	char c;
	data *A;
	mymalloc(A,n);
	for(i=0;i<n;i++){
		scanf(" %c %ld",&c,&j);
		A[i].key=j;
		A[i].order=i;
		A[i].suit=c;
	}
	return A;
}

void swap(data *i,data *j){
	data tmp;
	tmp=*i;
	*i=*j;
	*j=tmp;
}

long partition(data *A,long p,long r){
	long i,j,x;
	x=A[r].key;
	i=p;
	for(j=p;j<r;j++){
		if(A[j].key<=x){
			swap(&A[i],&A[j]);
			i++;
		}
	}
	swap(&A[i],&A[r]);
	return i;
}

void quickSort(data *A, long p, long r){
	long q;
	if(p<r){
		q=partition(A,p,r);
		quickSort(A,p,q-1);
		quickSort(A,q+1,r);
	}
}

int checkStab(data *A,long n){
	long i,k1,k2,o1,o2;
