	o1=A[0].order;
	for(i=1;i<n;i++){
		k2=A[i].key;
		o2=A[i].order;
		if(k1==k2&&o1>o2){
			return 1;
		}
		k1=k2;
		o1=o2;
	}
	return 0;
}


