int Partition(Card A[], int p, int r)
{
  int x;
  int i, j;

  i = p - 1;
  x = A[r].value;

  for (j = p; j < r; j++)
  {
    if (A[j].value <= x)
    {
      i++;
      swap_v(A, i, j);
      swap_p(A, i, j);
    }
  }

  swap_v(A, i + 1, r);
  swap_p(A, i + 1, r);

  return i + 1;
}

void MergeSort(Card A[], int left, int right)
{
  int mid;

  if (left + 1 < right)
  {
    mid = (left + right) / 2;

    MergeSort(A, left, mid);
    MergeSort(A, mid, right);
    Merge(A, left, mid, right);
  }
}

void Merge(Card A[], int left, int mid, int right)
{
  Card *L, *R;
  int n1, n2;
  int i, j, k;

  n1 = mid - left;
  n2 = right - mid;

  L = (Card *)malloc(sizeof(Card) * (n1 + 1));
  R = (Card *)malloc(sizeof(Card) * (n2 + 1));

  for (i = 0; i < n1; i++)
    L[i] = A[left + i];

  for (i = 0; i < n2; i++)
    R[i] = A[mid + i];

  L[n1].value = INT_MAX;
  R[n2].value = INT_MAX;
  i = 0;
  j = 0;

  for (k = left; k < right; k++)
  {
    if (L[i].value <= R[j].value)
    {
      A[k] = L[i];
      i++;
    }

    else
    {
      A[k] = R[j];
      j++;
    }

  }

}

