  int i, j;
  struct Card t, x;

  x = A[r];
  i = p - 1;
  for ( j = p; j <= r-1; j++ ){
    if ( A[j].value <= x.value ){
      i++;
      t = A[i];
      A[i] = A[j];
      A[j] = t;
    }
  }
  t = A[i+1];
  A[i+1] = A[r];
  A[r] = t;

  return i+1;
}

void quickSort(struct Card A[], int p, int r){

  int q;

  if ( p < r ){
    q = partition(A, p, r);
    quickSort(A, p, q - 1);
    quickSort(A, q + 1, r);
  }
}

