    int x = A[r-1].d;
    int i = p-1, j;
    for( j = p; j < r-1; j++ ){
        if( A[j].d <= x ){
            i++;
            swapCard(&A[i], &A[j]);
        }
    }
    swapCard(&A[i+1], &A[r-1]);
    return i+1;
}

