        if(A[j].value <= x){
            i++;
            t1 = A[i].value;
            A[i].value = A[j].value;
            A[j].value = t1;
            *t2 = *A[i].suit;
            *A[i].suit = *A[j].suit;
            *A[j].suit = *t2;
        }

    }


    t1 = A[i + 1].value;
    A[i + 1].value = A[r].value;
    A[r].value = t1;
    *t2 = *A[i + 1].suit;
    *A[i + 1].suit = *A[r].suit;
