int partition(card *A, int p, int r)
{
  int x, i, j;
  card for_change;

  x = A[r].num;
  i = p - 1;

  for(j = p ; j < r ; j++){
    if(A[j].num <= x){
      i++;
      for_change = A[i];
      A[i] = A[j];
      A[j] = for_change; }
  }

  for_change = A[i+1];
  A[i+1] = A[r];
  A[r] = for_change;

  return ++i;
}

void quicksort(card *A, int p, int r)
{
