void M(Card A[],int l,int m,int r){
  Card R[MAX/2+2],L[MAX/2+2];
  int i,j,k;
  int n1,n2;
  n1 = m - l;
  n2 = r - m;

  for(i=0;i<n1;i++){
    L[i] = A[l+i];
  }
  for(i=0;i<n2;i++){
    R[i] = A[m+i];
  }
  L[n1].v = INF;
  R[n2].v = INF;
  i = 0;
  j = 0;

  for(k=l;k<r;k++){
    if(L[i].v <= R[j].v){
      A[k] = L[i++];
    }else{
      A[k] = R[j++];
    }
  }
}



void Ms(Card A[],int l,int r){
  int m;
  if(l + 1 < r){
    m = (l+r)/2;
    Ms(A,l,m);
    Ms(A,m,r);
    M(A,l,m,r);
  }
}


int P(Card A[],int p,int r){
  Card tmp,x;
  int i,j;

  x = A[r];
  i = p - 1;
  for(j=p;j<r;j++){
    if(A[j].v <= x.v){
      i++;
      tmp = A[i];
      A[i] = A[j];
      A[j] = tmp;
    }
  }
  tmp = A[i+1];
  A[i+1] = A[r];
  A[r] = tmp;

  return i + 1;
}

void Qs(Card A[],int p,int r){
  int q;
  if(p<r){
    q = P(A,p,r);
    Qs(A,p,q-1);
    Qs(A,q+1,r);
  }
}

#include <stdio.h>

struct elem{
    int i;
    int v;
};

int partition(
        struct elem* ary,
        int p, int r)
{
    int i =0;
    int j = 0;
    struct elem x, buf;
    x = ary[r];
    i = p;
    for (j = p; j < r; j++) {
        if (ary[j].v <= x.v) {
            buf = ary[j];
            ary[j] = ary[i];
            ary[i] = buf;
            i++;
        }
    }
    buf = x;
    ary[r] = ary[i];
    ary[i] = buf;
    return i;
}

void quick_arg_sort_impl(
        struct elem *ary,
        const int p,
        const int r
        )
{
    int q = 0;
    if (p < r) {
        q = partition(ary, p, r);
        quick_arg_sort_impl(ary, p, q -1);
        quick_arg_sort_impl(ary, q + 1, r);
    }
}

void quick_arg_sort(
        const int *ary,
        const  int ary_size,
        struct elem *sorted
        )
{
    int i = 0;
    for (i = 0; i < ary_size; i++) {
        sorted[i].i = i;
        sorted[i].v = ary[i];
    }
    /* TODO: ゼロ埋め処理*/
    quick_arg_sort_impl(sorted, 0, ary_size - 1);
}

