void quickSort(member *A,int p,int r){
  int q;
  if(p < r){
    q = partition(A,p,r);
    quickSort(A,p,q-1);
    quickSort(A,q+1,r);
  }
}
int partition(member *A,int p,int r){
  int i,j;
  member x;
  x = A[r];
  i = p-1;
  for(j=p;j<r;j++){
    if(A[j].n <= x.n){
      i++;
      swap(&A[i],&A[j]);
    }
  }
  swap(&A[i+1],&A[r]);
  return i+1;
}

void swap(member *x,member *y){
  member r;
  r=*x;
  *x=*y;
  *y=r;
}

void bubbleSort(member *B,int n){
  int flag=1,i;
  while(flag){
    flag=0;
    for(i=n-1;i>0;i--){
      if(B[i].n<B[i-1].n){
	swap(&B[i],&B[i-1]);
	flag=1;
      }
    }
  }
}

