  int n2 = right - mid;
  card L[n1+1],R[n2+1];
  int k,i,j;
  for (i=0;i<n1;i++) {
  	L[i].a = A[left + i].a;
  	L[i].b = A[left + i].b;
  }
  for (i=0;i<n2;i++) {
  	R[i].a = A[mid + i].a;
  	R[i].b = A[mid + i].b;
  }
  L[n1].b = SENTINEL;//EOF
  R[n2].b = SENTINEL;//EOF
  i = 0;
  j = 0;

  for(k=left;k<right;k++){//iが左の要素番号,jが右の要素番号
    if(L[i].b<=R[j].b){//左が小さい場合
      A[k].a = L[i].a;
      A[k].b = L[i].b;
      i=i+1;
    }else{ //右が小さい場合
      A[k].a = R[j].a;
       A[k].b = R[j].b;
      if(L[i].b!=SENTINEL) cnt+=(n1-i);//SENTINELと比較する場合を除いて左側の未ソート部分の要素数をcntに加算
      j = j + 1;
    }
  }
}

