    int i,j,x;
    trump temp;
    x = card[r].num;
    i = p-1;
    for(j=p; j<r; j++){
        if(card[j].num <= x){
            i = i+1;
            temp = card[i];
            card[i] = card[j];
            card[j] = temp;

        }
