      A[k].suzi = L[i].suzi;
      A[k].mozi = L[i].mozi;
      i = i + 1;
    }
    else{
      A[k].suzi = R[j].suzi;
      A[k].mozi = R[j].mozi;

      j = j + 1;
    }
  }
}

