void Quicksort(int p, int r){
  int q;

  if(p < r){
    q = Partition(p, r);
    Quicksort(p, q - 1);
    Quicksort(q + 1, r);
  }
}

int Partition(int p, int r){
  int i, j, x;
  card y;

  x = A[r].value;
  i = p - 1;

  for(j = p; j < r-1; j++){
    if(A[j].value <= x){
      i++;
      y = A[i];
      A[i] = A[j];
      A[j] = y;
    }
  }

  y = A[i+1];
  A[i+i] = A[r];
  A[r] = y;

  return i+1;

}

