  int n1;
  int n2;

  n1=mid-left;
  n2=right-mid;

  for(i=0;i<n1;i++) L[i]=B[left+i];
  for(i=0;i<n2;i++) R[i]=B[mid+i];

  L[n1].A=INF;
  R[n2].A=INF;

  i=0;
