void Quicksort(char *m,int *n,int p,int r){
  int q;
  if(p < r){
    q = Partition(m,n,p,r);
    Quicksort(m,n,p,q-1);
    Quicksort(m,n,q+1,r);
  }

}

int Partition(char *m,int *n,int p,int r){
  int i,j,x,box;

  x=n[r];
  j=p-1;

  for(i=p;i<r;i++){
    if( n[i] <= x){
      j++;
      swap(m,n,j,i);
    }
  }
  swap(m,n,j+1,r);

  return j+1;
}

void swap(char *m,int *n,int p,int q){
  int box;
  char box2;

  box2 = m[p];
  m[p]=m[q];
  m[q]=box2;

  box = n[p];
  n[p]=n[q];
  n[q]=box;
}

void Bublesort(char *m2,int *n2,int n){
  int i,j;
  for(i=0;i<n;i++)
    for(j=n-1;j>=i+1;j--)
      if(n2[j] < n2[j-1]) swap(m2,n2,j,j-1);

}

int Check(char *m,char *m2,int *n,int *n2,int a){
  int flg=1,i;

  for(i=0;i<a;i++){
    if(m[i] != m2[i] || n[i] != n2[i]){
      flg = 0;
      break;
    }
  }
  return flg;
}

