int partition(list *A,int p,int r)
{
    list x,temp;
    int i,j;

    x=A[r];
    i=p-1; //i=-1
    for(j=p;j<=r-1;j++) //j=0
    {
        if(A[j].num<=x.num)
        {
            i=i+1;
            swap(A,i,j); //A[i]とA[j]を交換
        }
    }
    swap(A,i+1,r); //A[i+1]とA[r]を交換
    return i+1; //pivotの添え字を返す
}

void swap(list *A,int i,int j)
{
    list temp;
    temp=A[i];
    A[i]=A[j];
    A[j]=temp;
    return;
}

