    int i, j;
    int x;

    x = a[r].v;
    i = p-1;


    for( j=p; j<r; j++ ){

        if( a[j].v <= x ){
            i++;
            swap( &a[i], &a[j] );
        }
    }
    i++;
    swap( &a[i], &a[r] );


    return i;

}

