  x.suit = a[r].suit;
  x.num = a[r].num;
  i = p-1;

  for(j = p; j < r; j++){
    if(a[j].num <= x.num){
      i++;
      tmp = a[i];
      a[i] = a[j];
      a[j] = tmp;
    }
  }
  tmp = a[i+1];
  a[i+1] = a[r];
  a[r] = tmp;

  return i+1;
}

void quick(card *a, int p, int r){
  int q;
  if(p < r){
    q = part(a, p, r);
    quick(a, p, q-1);
    quick(a, q+1, r);
  }
}

isStable(card *in, card *out, int n){
  int i, j, k, l;
  for(i = 0 ; i < n; i++)
    for(j = i+1; j < n; j++)
      for(k = 0; k < n; k++)
        for(l = k+1; l < n; l++)
          if(in[i].num == in[j].num && in[i].suit == out[l].suit && in[j].suit == out[k].suit)
            return 0;
  return 1;
}

