int partition(card *A,int p,int r) /* p = 要素の始め、r = 要素の終わり */
{
  int x,i,j;
  card stack;

  x = A[r].number; /* xはpartitionの基準 */
  i = p - 1;

  for(j = p;j <= r - 1;j++){
    if(A[j].number <= x){
      i = i + 1;
      stack = A[i];
      A[i] = A[j];
      A[j] = stack;
    }
  }
  stack = A[i + 1];
  A[i + 1] = A[r];
  A[r] = stack;

  return i+1; /* 次のpartitionの基準となる値を返す */
}

void quicksort(card *A,int p,int r){
  int q;
  if(p < r){
    q = partition(A,p,r);
    quicksort(A,p,q-1);
    quicksort(A,q+1,r);
  }
}

