			i++;
			swapOfInt(&card1[i].num, &card1[j].num);
			swapOfChar(&card1[i].c, &card1[i].c);
		}
	}
	swapOfInt(&card1[i + 1].num, &card1[r].num);
	swapOfChar(&card1[i + 1].c, &card1[r].c);
	return i + 1;
}

