typedef struct { char c; int a; int id; } DATA;

int partition(DATA *a, int lo, int hi)
{
    int i, j;
    int key;
    DATA t;

    key = a[hi].a, i = lo-1;
    for (j = lo; j < hi; j++) {
        if (a[j].a <= key) i++, t = a[i], a[i] = a[j], a[j] = t;
    }
    t = a[++i], a[i] = a[hi], a[hi] = t;
    return i;
}

void quick_sort(DATA *a, int lo, int hi)
{
