bool isStable(struct card A[], struct card B[], int N){
    for(int i = 0; i < N; i++){
        if(*B[i].suit = *A[i].suit) return false;
    }
    return true;
}

void BubbleSort(struct card B[], int N){
    int i,j,t1;
    char t2[1];
    for(i = 0; i < N; i++){
        for(j = N-1; j > i; j--){
            if( B[j].value < B[j-1].value){
                t1 = B[j].value;
                *t2 = *B[j].suit;
                B[j].value = B[j-1].value;
                *B[j].suit = *B[j-1].suit;
                B[j-1].value = t1;
                *B[j-1].suit = *t2;
            } 

        }

    }
}

