  Record temp,temp2;
  i = p - 1;
  for(j=p;j<r;j++){
    if(A[j].number <= x){
      i++;
      temp = A[i];
      A[i] = A[j];
      A[j] = temp;
    }
  }
  temp2 = A[i+1];
