int nextInt(void) {
  int v = 0;
  while (*ptr < '0' || *ptr > '9') ++ptr;
  while (*ptr >= '0' && *ptr <= '9') {
    v = v * 10 + (int)(*ptr - '0');
    ++ptr;
  }
  return v;
}

char nextSuit(void) {
  while (*ptr < 'A' || *ptr > 'Z') ++ptr;
  return *ptr;
}

