void *qp(CC *lon, CC *pan){
  CC pores = *(pan-1);
  CC *p = lon-1;
  for(CC *w = lon; w!=pan-1;++w){
    if(w->y<=pores.y){
      p++;
      CC bum = *p;
      *p = *w;
      *w = bum;
    }
  }
  CC bum = *++p;
  *p=pores;
  *(pan-1)=bum;
  return p;
}

