// Partition function
int Partition(Card A[], int p, int r){
  int x, i, j;
  // i is <, j is |

  // Set x, i
  x = A[r].num;
  i = p - 1;

  // Partition
  for(j = p; j < r; j++){

    if(A[j].num <= x){
      i++;
      Exchange(&A[i], &A[j]);
    }
  }
  Exchange(&A[i + 1], &A[r]);

  return i + 1;
}

// QuickSort function
void QuickSort(Card A[], int p, int r){
  int q;

  if(p < r){
    q = Partition(A, p, r);
    QuickSort(A, p, q - 1);
    QuickSort(A, q + 1, r);
  }
}

void Exchange(Card *a, Card *b){
    Card t = *a;
    *a = *b;
    *b = t;
}

