void quick(int p,int r){
  int q;
  if(p < r){
    q = partition(p, r);
    quick(p, q-1);
    quick(q+1, r);
  }
}

int partition(int p,int r){
  int i,j;
  data put,x;
  x = a[r];
  i = p - 1;
  for(j = p;j < r;j++){
    if(a[j].num <= x.num){
      i++;
      put = a[i];
      a[i] = a[j];
      a[j] = put;
    }
  }
    put = a[i+1];
    a[i+1] = a[r];
    a[r] = put;
    return i+1;
}

void merge(int left,int mid,int right){
