    }
  }
}


void mergesort(int left,int right){
  int mid,i,c=0;
  if(left + 1 < right){
    mid = (left + right)/ 2;
    mergesort(left, mid);
    mergesort(mid, right);
    merge(left, mid, right);
    c++;
  }
}

