int partition(card A[], int p, int r){
	int x=A[r].num;
	int i=p-1,j;
	for(j=p;j<r;j++){
		if(A[j].num<=x){
			i++;
			swap(&(A[i]),&(A[j]));
		}
	}
	swap(&(A[i+1]),&(A[r]));
	return i+1;
}

void swap(card *a,card *b){
	card tmp;
	tmp=*a;
	*a=*b;
	*b=tmp;
}

void quickSort(card A[],int p,int r){
	if(p<r){
		int q = partition(A,p,r);
		quickSort(A,p,q-1);
		quickSort(A,q+1,r);
	}
}

