                arr[k] = l[i];
                i = i + 1;
            } else {
                arr[k] = r[j];
                j = j + 1;
            }
        }
        return count;
    }

    int mergeSort(Card[] arr, int left, int right, int count) {
        if (left + 1 < right) {
            int mid = (left + right) / 2;
            int x = mergeSort(arr, left, mid, count);
            int x2 = mergeSort(arr, mid, right, count);
            count = count + x + x2 + merge(arr, left, mid, right);
        }
        return count;
    }
