	static void quickSort(Card[] A, int p, int r) {
		if(p < r) {
			int q = partition_num(A, p, r);
			quickSort(A, p, q-1);
			quickSort(A, q+1, r);
		}
	}

	static int partition_num(Card[] A, int p, int r) {
		int x = A[r].num;
		int i = p-1;
		Card temp;
		for(int j=p; j<=r-1; j++) {
			if(A[j].num <= x) {
				i++;
				temp = A[j];
				A[j] = A[i];
				A[i] = temp;
			}
		}
		temp = A[r];
		A[r] = A[i+1];
		A[i+1] = temp;

		return i+1;
	}

