	private static void QuickSsort(int[] a, char[] m, int[] sq, int st, int ed) {
		if (st >= ed)
			return;
		int v = Q2sort(a, m, sq, st, ed);
		QuickSsort(a, m, sq, st, v - 1);
		QuickSsort(a, m, sq, v + 1, ed);
	}

	private static int Q2sort(int[] a, char[] m, int[] sq, int st, int ed) {
		int x = a[ed];
		int i = st - 1;
		for (int j = st; j < ed; j++)
			if (a[j] <= x) {
				i++;
				int tmp = a[j];
				a[j] = a[i];
				a[i] = tmp;
				char t = m[j];
				m[j] = m[i];
				m[i] = t;
				tmp = sq[j];
				sq[j] = sq[i];
				sq[i] = tmp;
			}
		int tmp = a[i + 1];
		a[i + 1] = a[ed];
		a[ed] = tmp;
		char t = m[i + 1];
		m[i + 1] = m[ed];
		m[ed] = t;
		tmp = sq[i + 1];
		sq[i + 1] = sq[ed];
		sq[ed] = tmp;

		return i + 1;
	}

}

