	public static void quicksort(String[] st,int[] a,int p,int r){
		if(p < r){
			int q = partition(st,a,p,r);
			quicksort(st,a,p,q-1);
			quicksort(st,a,q+1,r);
		}
	}

	public static int partition(String[] st,int[] a ,int p,int r){
		int x = a[r];
		int i = p-1;
		for (int j = p; j<r ; j++ ) {
			if (a[j] <= x)  {
				i++;
				int work = a[i];
				a[i] = a[j];
				a[j] = work;

				String workst = st[i];
				st[i] = st[j];
				st[j] = workst;
			}
		}
		int num = a[i+1];
		a[i+1] = a[r];
		a[r] = num;

		String str = st[i+1];
		st[i+1] = st[r];
		st[r] = str;
		return i+1;
	}

