    private void solv() {
        Scanner input = new Scanner(System.in);

        int n = input.nextInt();
        Card[]A = new Card[n];
        for(int i = 0; i < n; i++) {
            String mark = input.next();
            int no = input.nextInt();
            A[i] = new Card(mark, no);
        }
        Card[] B = Arrays.copyOf(A, A.length);
        for (int i = 0; i < B.length; i++) {
            for (int j = B.length - 1; i < j; j--) {
                if (B[j].no < B[j-1].no) {
                    Card temp = B[j];
                    B[j] = B[j-1];
                    B[j-1] = temp;
                }
            }
        }

        qs(A, 0, A.length - 1);

        boolean stable = true;
        for (int i = 0; i < A.length; i++) {
            if (A[i].mark.equals(B[i].mark) && A[i].no == B[i].no) {
            } else {
                stable = false;
                break;
            }
        }

        System.out.println(stable ? "Stable" : "Not stable");
        for (Card c : A) System.out.println(c);
    }

    private int partition(Card[] A, int p, int r) {
        Card x = A[r];
        int i = p - 1;
        Card temp;
        for (int j = p; j < r; j++) {
            if (A[j].no <= x.no) {
                i = i + 1;
                temp = A[i];
                A[i] = A[j];
                A[j] = temp;
            }
        }
        temp = A[i+1];
        A[i+1] = A[r];
        A[r] = temp;
        return i+1;
    }

    private void qs(Card[] A, int p, int r) {
        if (p < r) {
