            if(i != A.length-1){
                System.out.print("\n");
            }
        }
    }

    public static boolean judge(Cards[]A){
        for(int i=0;i<A.length;i++){
            for(int j=0;j<A.length;j++){
                if(A[i].num == A[j].num && A[i].index > A[j].index){
                    return false;
                }
            }
        }
        return true;
    }

    public static int partition(Cards[]A,int p,int r){
        int x = A[r].num;
        int i= p -1;
        for(int j= p;j<r;j++){
            if(A[j].num <= x){
                i++;
                int tmp = A[i].num;
                A[i].num = A[j].num;
                A[j].num = tmp;

                char ss = A[i].symbol;
                A[i].symbol = A[j].symbol;
                A[j].symbol = ss;
            }
        }

        int change = A[r].num;
        A[r].num = A[i+1].num;
        A[i+1].num = change;

        char sc = A[r].symbol;
        A[r].symbol = A[i+1].symbol;
        A[i+1].symbol = sc;

        return i+1;
    }

    public static void quicks(Cards[]A,int p,int r){
        if(p < r){
            int q = partition(A,p,r);
            quicks(A,p,q-1);
            quicks(A,q+1,r);
        }
    }
}

