		// TODO Auto-generated method stub
		if(low<high){
			int q=partition(A,low,high);
			quicksort(A, low, q-1);
			quicksort(A, q+1, high);
		}
	}

	private static int partition(Card[] A, int low, int high) {
		// TODO Auto-generated method stub
		int x=A[high].value;
