    for(int i = 0; i < n; i++){
      bl.append(C[i]).append(' ').append(A[i]).append("\n");
    }
    System.out.print(bl);
  }
  static int partition(int A[],String C[], int p, int r){
    int x = A[r];
    int i = p-1;
    int tmp;
    String s;
    for(int j =p; j<r; j++){
      if(A[j]<=x){
        i = i+1;
        tmp = A[i];
        A[i] = A[j];
        A[j] = tmp;
        s = C[i];
        C[i] = C[j];
        C[j] = s;
      }
    }
    tmp = A[i+1];
    A[i+1] = A[r];
    A[r] = tmp;
    s = C[i+1];
    C[i+1] = C[r];
    C[r] = s;
    return i+1;
  }

  static void quicksort(int A[], String C[], int p, int  r){
    if(p<r){
      int q = partition(A, C, p, r);
      quicksort(A, C, p, q-1);
      quicksort(A, C, q+1,r);
    }
  }


  //mergesortと比較
  static void merge(int A[],String S[], int left, int mid, int right){
    int n1 = mid - left;
    int n2 = right - mid;
    int L[] = new int[n1+1];
    int R[] = new int[n2+1];
    String Ls[] = new String[n1+1];
    String Rs[] = new String[n2+1];
    for(int i = 0; i<n1;i++){
      L[i] = A[left+i];
            Ls[i] = S[left+i];
    }
    for(int i =0; i<n2; i++){
      R[i] = A[i+mid];
      Rs[i] = S[i+mid];
    }
    L[n1] = (int)Double.POSITIVE_INFINITY;
    R[n2] = (int)Double.POSITIVE_INFINITY;
    int i = 0;
    int j = 0;
    for(int k = left; k<right; k++){
      if(L[i]<=R[j]){
        A[k] = L[i];
        S[k] = Ls[i++];
      }else{
        A[k] = R[j];
        S[k] = Rs[j++];
      }
    }
  }

  static void mergesort(int A[],String S[], int n, int left, int right){
    if(left+1<right){
      int mid = (left+right)/2;
      mergesort(A,S, n, left, mid);
      mergesort(A,S, n, mid, right);
      merge(A,S, left, mid, right);
    }
  }
}

import java.util.Scanner;

public class Main {
	private int[] a;
	private String[] ori;
	private String[] se;

	private Scanner sc;

	public static void main(String[] args) {
		new Main();
	}

	public Main() {
		sc = new Scanner(System.in);
		int lim = Integer.parseInt(sc.nextLine());

		a = new int[lim];
		ori = new String[lim];
		se = new String[lim];
		for (int i = 0; i < lim; i++) {
			ori[i] = sc.nextLine();
			se[i] = ori[i];
			a[i] = Integer.parseInt(se[i].split(" ")[1]);
		}
		quickSort(0, (lim - 1));

		boolean flag = true;
		int scope = a[0];
		for (int i = 0; i < lim; i++) {
			for (int j = 0; j < lim; j++) {
				if (se[i].equals(ori[j]) && (i != (lim - 1))) {
					if (scope == a[i + 1]) {
						i++;
					} else {
						break;
					}
				}
			}

			if (i != (lim - 1)) {
				if (scope == a[i + 1]) {
					flag = false;
					break;
				}
				scope = a[i + 1];
			}
		}
		if (flag) System.out.println("Stable");
		else System.out.println("Not stable");

		StringBuilder sb = new StringBuilder();
		for (int i = 0; i < lim; i++) {
			sb.append(se[i] + "\n");	
		}
		System.out.print(sb);
	}

	private void quickSort(int p, int r) {
		if (p < r) {
			int q = partition(p, r);
			quickSort(p, (q - 1));
			quickSort((q + 1), r);
		}

	}

	private int partition(int p, int r) {
		int x = a[r];
		int i = p - 1;

		int tmp;
		String stmp;

		for (int j = p; j < r; j++) {
			if (a[j] <= x) {
				i = i + 1;

				tmp = a[i];
				stmp = se[i];

				a[i] = a[j];
				se[i] = se[j];

				a[j] = tmp;
				se[j] = stmp;
			}
		}

		tmp = a[i + 1];
		stmp = se[i + 1];

		a[i + 1] = a[r];
		se[i + 1] = se[r];

		a[r] = tmp;
		se[r] = stmp;
		return (i + 1);
	}
}

