                if(check[i] > check[i+1]){
                    return false;
                }
            }
        }
        return true;
    }

    static void quickSort(int[] A, int p, int r) {
        if (p < r) {
            int q = partition(A, p, r);
            quickSort(A, p, q - 1);
            quickSort(A, q + 1, r);
        }
    }

    static int partition(int[] A, int p, int r) {
        int x = A[r];
        int i = p - 1;
        for (int j = p; j < r; j++) {
            if (A[j] <= x) {
                i++;
                swap(A, i, j);
            }
        }
        swap(A, i + 1, r);
        return i + 1;
    }

    static void swap(int[] A, int x, int y) {
        int tmp = A[x];
        A[x] = A[y];
        A[y] = tmp;

        String tmps = cards[x];
        cards[x] = cards[y];
        cards[y] = tmps;

        tmp = check[x];
        check[x] = check[y];
        check[y] = tmp;
    }

}

