			quickSort(p, (q - 1));
			quickSort((q + 1), r);
		}

	}

	private int partition(int p, int r) {
		int x = a[r];
		int i = p - 1;

		int tmp;
		String stmp;

		for (int j = p; j < r; j++) {
			if (a[j] <= x) {
				i = i + 1;

				tmp = a[i];
				stmp = se[i];

				a[i] = a[j];
				se[i] = se[j];

				a[j] = tmp;
