                A[i] = A[j];
                A[j] = tmp;
            }
        }

        Cards change = A[r];
        A[r] = A[i+1];
        A[i+1] = change;

        return i+1;
    }

    public static void quicks(Cards[]A,int p,int r){
        if(p < r){
            int q = partition(A,p,r);
            quicks(A,p,q-1);
            quicks(A,q+1,r);
        }
    }
}

