    static int partition (Card[] a, int p, int r) {
	int x = a[r].num;
	int i = p - 1;
	Card tmp;
	for (int j = p; j < r; j++) {
	    if (a[j].num <= x) {
		i = i + 1;
		tmp = a[j];
		a[j] = a[i];
		a[i] = tmp;
	    }
	}
	tmp = a[i+1];
	a[i+1] = a[r];
	a[r] = tmp;
	return i+1;
    }
}
