        }
    }
    public static int partition(String [] A, int p, int r){
        String X = A[r];
        int x = Integer.parseInt(A[r].substring(2, 3));
        int i = p;
        for(int j = p; j < r; j++){
            if(Integer.parseInt(A[j].substring(2, 3)) <= x){
                String hold = A[i];
                A[i] = A[j];
                A[j] = hold;
                i = i++;
            }
        }
        A[r] = A[i];
        A[i] = X;
        return i;
    }

    public static void quicksort(String [] A, int p, int r){
        if(p < r){
            int q = partition(A, p, r);
            quicksort(A, p, q - 1);
            quicksort(A, q + 1, r);
        }
    }
}

