	static int Partition (String[] str, int[] array, int p, int r) {
		int x = array[r];
		int i = p - 1;
		int temp;
		String strtemp;
		String strx = str[r];

		for (int j = p; j < r; j++) {
			if (array[j] <= x) {
				i++;
				temp = array[j];
				array[j] = array[i];
				array[i] = temp;

				strtemp = str[j];
				str[j] = str[i];
				str[i] = strtemp;
			}
		}

		array[r] = array[i + 1];
		array[i + 1] = x;

		str[r] = str[i + 1];
		str[i + 1] = strx;

		return i + 1;
	}

	static boolean isStable(String[] str, String[] array, int[] number) {
