		for ( int i = 0; i < n - 1; i++ ) {
			for ( int j = i + 1; j < n - 1; j++) {
				if (number[i] == number[j]) {
					for ( int a = 0; a < n ; a++) {
						if ( str[i] == array[a]) {
							for (int b = 0; b < n ; b++) {
								if (str[j] == array[b]) {
									if ( a > b ) {
										return false;
									}
								}
							}
						}
					}
				}
			}
		}

		return true;
	}

