            }
        }
		System.out.println(message);
		output();
		//後処理
		br.close();
	}

	//クイックソート
	public static void quicksort(int par, int rim){
		int q;
		if ( par < rim ){
			q = partition(par, rim);
			quicksort(par, q - 1);
			quicksort(q + 1, rim);
		}
	}

	//パーティション
	public static int partition(int par,int rim){
		card work;
		int x = array[rim].num;
		int i = par - 1;
		//ソート処理
		for (int j = par ; j < rim ; j ++ ){
			if ( array[j].num <= x ) {
				work = array[++i];
				array[i] = array[j];
				array[j] = work;
			}
		}
		//最後に入れ替え
		work = array[++i];
		array[i] = array[rim];
		array[rim] = work;
		return i;
	}

	//出力
	public static void output(){
		StringBuilder sb = new StringBuilder("");
		for (int i = 0; i < num; i++) {
			sb.append(array[i].mark).append(" " + array[i].num).append("\n"); 
		}
