class Main {
    static Card[] A;

    static int partition(int l, int r){
        int i = l-1;

        for (int j = l; j < r; j++){
            if (A[j].n <= A[r].n){
                i++;
                // swap
                Card temp = A[j];
                A[j] = A[i];
                A[i] = temp;
            }
        }
        i++;
        Card temp = A[r];
        A[r] = A[i];
        A[i] = temp;
        return i;
    }

    static void quickSort(int l, int r){
        if (l < r){
            int q = partition(l,r);
            quickSort(l,q-1);
            quickSort(q+1,r);
        }
    }

    static String stable(Card[] A, Card[] B){
        for (int i = 0; i < A.length; i++) {
            if (!A[i].c.equals(B[i].c)){
                return "Not stable";
            }
        }
        return "Stable";
    }



    public static void main(String[] args) {
        MyScanner sc = new MyScanner();
        int n = sc.nextInt();
        A = new Card[n];

        for (int i = 0; i < n; i++)
            A[i] = new Card(sc.next(),sc.nextInt());

        Card[] B = new Card[n];
        for (int i = 0; i < n; i++)
            B[i] = A[i];

        Arrays.sort(B,(Card a, Card b) -> b.n - a.n);

        quickSort(0,n-1);

        System.out.println(stable(A,B));

        for (int i = 0; i < n; i++)
            System.out.println(A[i].c + ' ' + A[i].n);

    }

    static class Card{
        String c;
        int n;
        Card(String c, int n){
            this.c = c;
            this.n = n;
        }
    }

    /**
     * MyScanner is a user-defined fast I/O class.
     * Source: https://algocoding.wordpress.com/2015/04/23/fast-io-methods-for-competitive-programming/
     */

    static class MyScanner {
        BufferedReader br;
        StringTokenizer st;

        public MyScanner() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        String next() {
            while (st == null || !st.hasMoreElements()) {
                try {
                    st = new StringTokenizer(br.readLine());
                } catch (IOException e) {
                    e.printStackTrace();
                }
            }
            return st.nextToken();
        }

        int nextInt() { return Integer.parseInt(next()); }
        long nextLong() { return Long.parseLong(next()); }
        double nextDouble() { return Double.parseDouble(next()); }

        String nextLine(){
            String str = "";
            try {
                str = br.readLine();
            } catch (IOException e) {
                e.printStackTrace();
            }
            return str;
        }
    }
}

import java.util.*;
import java.io.*;

public class Main {
	public static void main(String[] args) {
		Scanner scanner = new Scanner(System.in);

		int n = scanner.nextInt();
		char[] S = new char[n];
		int[] A = new int[n];

		for (int i = 0; i < n; i ++) {
			S[i] = scanner.next().charAt(0);
			A[i] = scanner.nextInt();
		}

		scanner.close();

		char[] T = S.clone();
		int[] B = A.clone();

		quickSort(S, A, 0, n - 1);
		mergeSort(T, B, 0, n);

		if(Arrays.equals(A, B) && Arrays.equals(S, T)) {
			System.out.println("Stable");
		} else {
			System.out.println("Not stable");
		}

		for (int i = 0; i < n; i ++) {
			System.out.println(S[i] + " " + A[i]);
		}
	}

	public static int partition (char[] S, int[] A, int p, int r) {
		int x = A[r];
		int i = p - 1;

		for (int j = p; j < r; j++) {
			if (A[j] <= x) {
				i ++;
				char tempc = S[i];
				S[i] = S[j];
				S[j] = tempc;
				int temp = A[i];
				A[i] = A[j];
				A[j] = temp;
			}
		}

		char tempc = S[++ i];
		int temp = A[i];
		S[i] = S[r];
		A[i] = A[r];
		S[r] = tempc;
		A[r] = temp;

		return i;
	}

	public static void quickSort(char[] S, int[] A, int p, int r) {
		if (p < r) {
			int q = partition(S, A, p, r);
			quickSort(S, A, p, q - 1);
			quickSort(S, A, q + 1, r);
		}
	}

	public static int merge(char[] T, int[] A, int left, int mid, int right) {
		int count = 0;

		int n1 = mid - left;
		int n2 = right - mid;

		int[] L = new int[n1 + 1];
		char[] LT = new char[n1];
		int[] R = new int[n2 + 1];
		char[] RT = new char[n2];

		System.arraycopy(A, left, L, 0, n1);
		L[n1] = Integer.MAX_VALUE;
		System.arraycopy(T, left, LT, 0, n1);
		System.arraycopy(A, mid, R, 0, n2);
		R[n2] = Integer.MAX_VALUE;
		System.arraycopy(T, mid, RT, 0, n2);

		int i = 0;
		int j = 0;

		for (int k = left; k < right; k ++) {
			count ++;
			if (L[i] <= R[j]) {
				A[k] = L[i];
				T[k] = LT[i];
				i ++;
			} else {
				A[k] = R[j];
				T[k] = RT[j];
				j ++;
			}
		}

		return count;
	}

	public static int mergeSort(char[] T, int[] A, int left, int right) {
		int count = 0;

		if (left + 1 < right) {
			int mid = (left + right) / 2;
			count += mergeSort(T, A, left, mid);
			count += mergeSort(T, A, mid, right);
			count += merge(T, A, left, mid, right);
		}

		return count;
	}
}

