					if (scope == a[i + 1]) {
						i++;
					} else {
						break;
					}
				}
			}
			if (i != (lim - 1)) {
				if (scope == a[i + 1]) {
					flag = false;
					break;
				}
			}
		}
		if (flag) System.out.println("Stable");
