	public static void main(String args[]) {
		//実行処理
		run();
	}

	//実質メイン
	public static void run(){ 
		Scanner scanner = new Scanner(System.in);
		num = scanner.nextInt();//要素数
		array = new long[num];
		long[] bubble = new long[num];
		//配列作成
		makeDeck(num,scanner);
		//ソート処理
		bubble = bubbleSort();
		quicksort(0, num - 1 );
		//出力
		if( Arrays.equals( bubble , array ) ) {
			System.out.println("Stable");
		}else {
			System.out.println("Not stable");
		}
		output();
		//後処理
		scanner.close();
	}

	//クイックソート
	public static void quicksort(int par, int rim){
		int q;
		if ( par < rim ){
			q = partition(par, rim);
			quicksort(par, q - 1);
			quicksort(q + 1, rim);
		}
	}

	//パーティション
	public static int partition(int par,int rim){
		long[] numArray = new long[num];
		long[] dig = new long[num];
		for(int i = 0; i < num; i ++){
			dig[i] = array[i] / 100000000;
			numArray[i] = array[i] % 100000000;
		}
		long work = 0;
		long sub = 0;
		long x = numArray[rim];
		int i = par - 1;

		//ソート処理
		for (int j = par ; j < rim ; j ++ ){
			if ( numArray[j] <= x ) {
				work = numArray[++i];
				numArray[i] = numArray[j];
				numArray[j] = work;
				sub = dig[i];
				dig[i] = dig[j];
				dig[j] = sub;
			}
		}
		//最後に入れ替え
		work = numArray[++i];
		numArray[i] = numArray[rim];
		numArray[rim] = work;
		sub = dig[i];
		dig[i] = dig[rim];
		dig[rim] = sub;
		for(int k = 0; k < num; k ++){
			array[k] = (dig[k] * 100000000)+  numArray[k];
		}
		return i;
	}

	//安定判断用バブルソート
	public static long[] bubbleSort(){ 
		long[] numArray = new long[num];
		long[] dig = new long[num];
		long[] out = new long[num];

		for(int i = 0; i < num; i ++)
		{
			dig[i] = array[i] / 100000000;
			numArray[i] = array[i] % 100000000;
		}
		//バブルソート処理
		for (int i = 0; i < num - 1; i++) {
				for (int j = num - 1; j > i; j--) {
					if (numArray[j - 1] > numArray[j]) {
						long work = numArray[j - 1];
						numArray[j - 1] = numArray[j];
						numArray[j] = work;
						long sub = dig[j - 1];
						dig[j - 1] = dig[j];
						dig[j] = sub;
					}
				}
			}
		for(int i = 0; i < num; i ++)
		{
			out[i] = (dig[i] * 100000000)+  numArray[i];
		}
		return out;
	}

	//山作り
