            if (this.number > card.number) return 1;
            return 0;
        }

        @Override
        public String toString() {
            return this.suit + " " + String.valueOf(this.number);
        }

        @Override
        public boolean equals(Object obj) {
            if (obj == this) return true;
            if (!(obj instanceof Card)) return false;
            Card c = (Card) obj;
            return this.suit.equals(c.suit) && this.number == c.number;
        }
    }

    void solve() {
        int n = io.nextInt();
        Card[] A = new Card[n];
        for (int i = 0; i < n; i++) {
            String suit = io.next();
            int number = io.nextInt();
            A[i] = new Card(suit, number, i);
        }

        Card[] B = A.clone();
        quickSort(A, 0, A.length - 1);
        boolean isStable = true;
        for (int i = 1; i < A.length - 1; i++) {
            if (A[i - 1].number == A[i].number && A[i - 1].id > A[i].id) {
                isStable = false;
                break;
            }
        }
        System.out.println(isStable ? "Stable" : "Not stable");
        for (Card a : A) {
            System.out.println(a.toString());
        }
    }

    int partition(Card[] A, int p, int r) {
        Card x = A[r];
        int i = p - 1;
        for (int j = p; j < r; j++) {
            if (x.compareTo(A[j]) >= 0) {
                i += 1;
                swap(A, i, j);
            }
        }
        swap(A, i + 1, r);
        return i + 1;
    }

    void quickSort(Card[] A, int p, int r) {
        if (p < r) {
            int q = partition(A, p, r);
            quickSort(A, p, q - 1);
            quickSort(A, q + 1, r);
        }
    }

    void bubbleSort(Card[] c) {
        int n = c.length;
        for (int i = 0; i < n; i++)
            for (int j = n - 1; j > i; j--) {
                if (c[j - 1].compareTo(c[j]) > 0) {
                    Card tmp = c[j - 1];
                    c[j - 1] = c[j];
                    c[j] = tmp;
                }
            }
    }

    void swap(Card[] A, int idx1, int idx2) {
        Card tmp = A[idx1];
        A[idx1] = A[idx2];
        A[idx2] = tmp;
    }

