class sort{

	public static int partition(int A[],String AO[],int p,int r){

		int x = A[r];
		int i = p-1;
		int j = 0;
		int tre;
		String treO;

		for(j=p;j<r;j++){

			if(A[j] <= x){

				i = i + 1;
				tre = A[i];
				A[i] = A[j];
				A[j] = tre;
				treO = AO[i];
				AO[i] = AO[j];
				AO[j] = treO;

			}

		}

		tre = A[i + 1];
		A[i + 1] = A[r];
		A[r] = tre;
		treO = AO[i+1];
		AO[i+1] = AO[r];
		AO[r] = treO;

		return i+1;

	}

	public static void quicksort(int A[],String AO[],int p,int r){

		int q = 0;

		if(p < r){

			q = partition(A, AO, p, r);
			quicksort(A, AO, p, q-1);
			quicksort(A, AO, q+1, r);

		}

	}
}

