	//クイックソート
	public static void quicksort(int par, int rim){
		int q;
		if ( par < rim ){
			q = partition(par, rim);
			quicksort(par, q - 1);
			quicksort(q + 1, rim);
		}
	}

	//パーティション
	public static int partition(int par,int rim){
		int[] numArray = new int[num];
		int[] dig = new int[num];
		for(int i = 0; i < num; i ++){
			dig[i] = array[i] / 100;
			numArray[i] = array[i] % 100;
		}
		int work = 0;
		int sub = 0;
		int x = numArray[rim];
		int i = par - 1;

		//ソート処理
		for (int j = par ; j < rim ; j ++ ){
			if ( numArray[j] <= x ) {
				work = numArray[++i];
				numArray[i] = numArray[j];
				numArray[j] = work;
				sub = dig[i];
				dig[i] = dig[j];
				dig[j] = sub;
			}
		}
		//最後に入れ替え
		work = numArray[++i];
		numArray[i] = numArray[rim];
		numArray[rim] = work;
		sub = dig[i];
		dig[i] = dig[rim];
		dig[rim] = sub;
		for(int k = 0; k < num; k ++){
			array[k] = (dig[k] * 100)+  numArray[k];
		}
		return i;
	}

	//安定判断用バブルソート
	public static int[] bubbleSort(){ 
		int[] numArray = new int[num];
		int[] dig = new int[num];
		int[] out = new int[num];

		for(int i = 0; i < num; i ++)
		{
			dig[i] = array[i] / 100;
			numArray[i] = array[i] % 100;
		}
		//バブルソート処理
		for (int i = 0; i < num - 1; i++) {
				for (int j = num - 1; j > i; j--) {
					if (numArray[j - 1] > numArray[j]) {
						int work = numArray[j - 1];
						numArray[j - 1] = numArray[j];
						numArray[j] = work;
						int sub = dig[j - 1];
						dig[j - 1] = dig[j];
						dig[j] = sub;
					}
				}
			}
		for(int i = 0; i < num; i ++)
		{
			out[i] = (dig[i] * 100)+  numArray[i];
		}
		return out;
	}

