    void swap(Card[] A, int a, int b) {
        Card tmp = A[a];
        A[a] = A[b];
        A[b] = tmp;
    }
    int partition(Card[] A, int p, int r) {
        int x = A[r].n;
        int i = p - 1;
        for (int j = p; j < r; j++) {
            if (A[j].n <= x) {
                i++;
                swap(A, i, j);
            }
        }
        swap(A, i+1, r);
        return i+1;
    }
    void quickSort(Card[] a, int p, int r) {
        if (p < r) {
            int q = partition(a, p, r);
            quickSort(a, p, q-1);
            quickSort(a, q+1, r);
        }
    }
    void printCards(Card[] a) {
        for (int i = 0; i < a.length; i++) {
            System.out.println(a[i]);
        }
