        if (a.n < b.n) {
            return true;
        } else if (a.n == b.n) {
            //return a.s.compareTo(b.s) <= 0;
            return a.m < b.m;
        } else {
            return false;
        }
    }
    boolean isStable(Card[] a) {
        boolean ret = true;
        for (int i = 1; i < a.length; i++) {
            if (compare(a[i-1], a[i])) {
                ret = false;
                break;
            }
        }
        return ret;
    }
