    Card tmp;
    x = A[r].value;
    i = p-1;
    for(j=p; j<r; j++){
        if(A[j].value<=x){
        i++;
        tmp = A[i]; A[i] = A[j]; A[j] = tmp;
        }
    }
    tmp = A[i+1]; A[i+1] = A[r]; A[r] = tmp;
    return i+1;
    }

    public static void quickSort(Card[] A, int n, int p, int r){
    int q;
    if(p < r){
        q = partition(A, n, p, r);
        quickSort(A, n, p, q - 1);
        quickSort(A, n, q + 1, r); 
    }
