public class Main {
	private static void quicksort(card a[],int start,int end){
		int i=start,j=end,pivot=a[(i+j)/2].num;
		if (start>=end){return;}
		for (;i<=j;){
			for (;a[i].num<pivot;i++){};
			for (;a[j].num>pivot;j--){};
			if (i<=j){
				card tmp=a[i];
				a[i]=a[j];
				a[j]=tmp;
				i++;
				j--;
			}
		}
		quicksort(a,start,j);
		quicksort(a,i,end);
	}
