	public void sort(int[] A, int p, int r) {
		if(p < r) {
			q = partition(A, p, r);
			sort(A, p, q-1);
			sort(A, q+1, r);
		}
	}

	public int partition(int[] A, int p, int r) {
		int swap;
		String note;
		int x = A[r];
		i = p-1;
		for(int j=p; j<r; j++) {
			if(A[j] <= x) {
				i++;
				swap = A[i];
				A[i] = A[j];
				A[j] = swap;

				note = card[i];
				card[i] = card[j];
				card[j] = note;
			}
		}
		swap = A[i+1];
		A[i+1] = A[r];
		A[r] = swap;

		note = card[i+1];
		card[i+1] = card[r];
		card[r] = note;

		return i+1;
	}

