				kari = c[i];
				c[i] = c[j];
				c[j] = kari;

			}

		}

		kari = c[i + 1];
		c[i + 1] = c[r - 1];
		c[r - 1] = kari;

		return i;
	}

	public static void quicksort(Card[] c, int p, int r) {
		if (p < r - 1) {
			int q = partition(c, p, r);
			quicksort(c, p, q);
			quicksort(c, q + 1, r);
		}
	}
}

