		Card[] copy = Arrays.copyOf(cards, n);
		quickSort(cards, 0, n-1);
		mergeSort(copy, 0, n);

		boolean stable = true;
		for (int i = 0; i < n; i++) {
			if(!cards[i].equals(copy[i])) {
				stable = false;
				break;
			}
		}

		if(stable) {
