		for (int j = p; j < r; j++) {
			if (c[j].number <= x) {
				i++;
				t = c[i];
				c[i] = c[j];
				c[j] = t;
			}
		}
		t = c[r];
		c[r] = c[i + 1];
		c[i + 1] = t;
		return i + 1;
	}	
