class Solve {
	private int n;
	private Card[] C;

	public Solve(final int n, final Card[] C)
	{
		this.n = n;
		this.C = C;
	}

	public void solve()
	{
		Card[] C = this.C.clone();

		int[] orderMap = new int[100001];

		Arrays.fill(orderMap, 0);

		for(int i=0; i < n; i++)
		{
			orderMap[C[i].v] = (orderMap[C[i].v] << 7 | C[i].c);
		}

		quickSort(C, 0, n - 1);

		int v = C[0].v;
		int hash = C[0].c;

		boolean stable = true;

		for(int i=1; i < n + 1; i++)
		{
			if(i == n)
			{
				if(hash != orderMap[C[n-1].v]) stable = false;
			}
			else if(C[i].v != v)
			{
				if(hash != orderMap[v])
				{
					stable = false;
					break;
				}
				else
				{
					v = C[i].v;
					hash = v;
				}
			}
			else
			{
				hash = (hash << 7 | C[i].c);
			}
		}

		if(stable) System.out.println("Stable");
		else System.out.println("Not stable");

		StringBuilder sb = new StringBuilder();

		for(int i=0; i < n; i++)
		{
			sb.append(C[i].toString() + "\n");
		}

		System.out.print(sb.toString());
	}

	public void quickSort(Card[] C, final int p, final int r)
	{
		if(p < r)
		{
			int q = partition(C, p, r);

			quickSort(C, p, q - 1);
			quickSort(C, q + 1, r);
		}
	}

	public int partition(Card[] C, int p, final int r)
	{
		int x = C[r].v;
		int i = p - 1;

		for(int j=p; j < r; j++)
		{
			if(C[j].v <= x)
			{
				++i;
				Card tmp = C[j];
				C[j] = C[i];
				C[i] = tmp;
			}
		}
		Card tmp = C[r];
		C[r] = C[i + 1];
		C[i + 1] = tmp;

		return i + 1;
	}
}
class ContestScanner {
	BufferedReader reader;
