		this.t=t;
	}
}
public class Main{
	static boolean i(S a[]) {
		for(int i=0;i<a.length-1;i++) {
			if(a[i].b==a[i+1].b&&a[i].t>a[i+1].t) {
				return true;
			}
		}
		return false;
	}
	static int q(S a[],int low,int high) {
		 int i=low-1;
	    long key = a[high].b;
	    for(int j=low;j<high;j++) {
	    	if(a[j].b<=key) {
	    		i++;
	    		S temp = a[i];
	    		a[i] = a[j];
	    		a[j] = temp;
	    	}	
	    }
	    S temp=a[i+1];
	    a[i+1]=a[high];
	    a[high]=temp;
	    return i+1;
	}
	static void sort(S a[],int low,int high){
		if(low<high) {
			int q=q(a,low,high);
			sort(a,low,q-1);
			sort(a,q+1,high);
		}
	}
