            for(int j=p;j<r;j++)
            {
                if(A[j].CompareTo(x)<=0)
                {
                    i++;
                    if (i != j)
                    {
                        T t = A[i];
                        A[i] = A[j];
                        A[j] = t;
                    }
                }

            }
            T tmp = A[i + 1];
            A[i + 1] = A[r];
            A[r] = tmp;

            return i+1;
        }
        static bool isStable( card[] sortCards)
        {
            for(int i=0;i<sortCards.Length-1;i++)
            {
                if (sortCards[i].CompareTo(sortCards[i + 1]) == 0 && sortCards[i].pos > sortCards[i + 1].pos)
                    return false;
            }
            return true;
        }

        class card: IComparable<card>
        {
            public char color { set; get; }
            public int num { set; get; }
            public int pos { set; get; }

            public card(string s, int i)
            {
                string[] str = s.Split(' ');
                color = s[0];
                num = int.Parse(str[1]);
                pos = i;
            }

            public int CompareTo(card other)
            {
                return num-other.num;
            }

            public override string ToString()
            {
                return color + " " + num;
            }
        } 

    }
