using System;

class Quick_Sort {

    public struct MarkAndNumber {
        public char mark;
        public int number;
    }

    public static void Main() {

        int n = int.Parse(Console.ReadLine());

        MarkAndNumber[] one = new MarkAndNumber[n];
        MarkAndNumber[] two = new MarkAndNumber[n];

        for(int i = 0; i < n; i++) {
            string[] str = Console.ReadLine().Split(' ');
            one[i].mark = two[i].mark = str[0][0];
            one[i].number = two[i].number = int.Parse(str[1]);
        }

        QuickSort(one, 0, n - 1);
        MergeSort(two, 0, n);

        if(Stable(one, two, n)) Console.WriteLine("Stable");
        else Console.WriteLine("Not stable");

        foreach (MarkAndNumber item in one) {
            Console.WriteLine(item.mark + " " + item.number);
        }
    }

    public static bool Stable(MarkAndNumber[] one, MarkAndNumber[] two, int n) {
        for(int i = 0; i < n; i++) {
            if(one[i].mark != two[i].mark) {
                return false;
            }
        }
        return true;
    }

    public static void MergeSort(MarkAndNumber[] one, int left, int right) {
        if(right > 1 + left) {
            int mid = (right + left) / 2;
            MergeSort(one, left, mid);
            MergeSort(one, mid, right);
            Merge(one, left, mid, right);
        }
    }

    public static void Merge(MarkAndNumber[] one, int left, int mid, int right) {

        int number1 = mid - left;
        int number2 = right - mid;

        MarkAndNumber[] Right = new MarkAndNumber[number2 + 1];
        MarkAndNumber[] Left = new MarkAndNumber[number1 + 1];

        for(int i = 0; i < number1; i++) Left[i] = one[left + i];
        for(int i = 0; i < number2; i++) Right[i] = one[mid + i];

        int max = int.MaxValue;
        Left[number1].number = Right[number2].number = max;

        int w = left;
        for(int i = 0, j = 0; w < right; w++) {

            if(Left[i].number <= Right[j].number) {
                one[w] = Left[i];
                i++;
            } else {
                one[w] = Right[j];
                j++;
            }
        }
    }

    public static void QuickSort(MarkAndNumber[] one, int n, int m) {
        if(n < m) {

            int num = Devide(one, n, m);
            QuickSort(one, n, num - 1);
            QuickSort(one, num + 1, m);

        }
    }

    public static int  Devide(MarkAndNumber[] one, int n, int m) {
        int oneNumber = one[m].number, i = n - 1;

        for(int j = n; j < m; j++) {
            if(one[j].number <= oneNumber) Swap(ref one[++i], ref one[j]);
        }

        Swap(ref one[i + 1], ref one[m]);

        return 1 + i;
    }

    public static void Swap<T>(ref T one, ref T two) {
        T tmp = one;
        one = two;
        two = tmp;
    }
}

