		}
		static void QuickSort ( Card[] array, int leftIndex, int rightIndex )
		{
			if (leftIndex < rightIndex)
			{
				int index = Partition (array, leftIndex, rightIndex);
				QuickSort (array, leftIndex, index - 1);
				QuickSort (array, index + 1, rightIndex);
			}
		}
		static int Partition ( Card[] array, int leftIndex, int rightIndex )
		{
			int baseValue = array[rightIndex].Count;
			int index = leftIndex - 1;

			for (int lp = leftIndex; lp < rightIndex; lp++)
			{
				if (array[lp].Count <= baseValue)
				{
					index++;

					var tmp = array[lp];
					array[lp] = array[index];
					array[index] = tmp;
				}
			}

			var tmp2 = array[index + 1];
			array[index + 1] = array[rightIndex];
			array[rightIndex] = tmp2;

			return index + 1;
		}
	}

