	public static void BubbleSort(Card[] A)
	{
		bool flag = true;

		while(flag) {
			flag = false;

			for(int i = A.Length -1; i > 0; i--) {
				if(A[i-1].CompareTo(A[i]) > 0) { 
					Card.Swap(ref A[i], ref A[i-1]);
					flag = true;
				}
			}
		}
