using System;

class Program{
    class Card{
        public int value;
        public char suit;
        public Card(char suit, int value){
            this.suit=suit;
            this.value=value;
        }
    }

    static void Swap(Card[] A, int a, int b){
        var tmp=A[a];
        A[a]=A[b];
        A[b]=tmp;
    }

    static int Partition(Card[] A, int p, int r){
        var x=A[r-1].value;
        var i=p-1;
        for(var j=p; j<r-1; j++){
            if(A[j].value<=x){
                i++;
                Swap(A, i, j);
            }
        }
        Swap(A, i+1, r-1);
        return i+1;
    }

    static void QuickSort(Card[] A, int p, int r){
        if(p+1<r){
            var q=Partition(A, p, r);
            QuickSort(A, p, q);
            QuickSort(A, q, r);
        }
    }

    static void Merge(Card[] A, int left, int mid, int right){
        var n1=mid-left;
        var n2=right-mid;
        var L=new Card[n1+1];
        var R=new Card[n2+1];
        for(var i=0; i<n1; i++){
            L[i]=A[left+i];
        }
        for(var i=0; i<n2; i++){
            R[i]=A[mid+i];
        }
        L[n1]=new Card('X', 1000*1000*1000+1);
        R[n2]=new Card('X', 1000*1000*1000+1);
        var l=0;
        var j=0;
        for(var k=left; k<right; k++){
            if(L[l].value<=R[j].value){
                A[k]=L[l];
                l++;
            } else{
                A[k]=R[j];
                j++;
            }
        }
    }

    static void MergeSort(Card[] A, int left, int right){
        if(left+1<right){
            var mid=(left+right)/2;
            MergeSort(A, left, mid);
            MergeSort(A, mid, right);
            Merge(A, left, mid, right);
        }
    }

