            B[i]=new Card(s[0][0], int.Parse(s[1]));
        }

        QuickSort(A, 0, n);
        MergeSort(B, 0, n);
        var isStable=true;
        for(var i=0; i<n; i++){
            if(A[i].suit!=B[i].suit){
                isStable=false;
                break;
            }
        }

        var sout=new System.Text.StringBuilder();
