                if (dict.ContainsKey(A[i].Item2))
                    dict[A[i].Item2].Add(A[i].Item1);
                else
                    dict[A[i].Item2] = new List<string>() { A[i].Item1 };
            }

            QuickSort(A, 0, n - 1);

            var isStable = true;
            for (var i = 0; i < n; i++)
            {
                if (A[i].Item1 != dict[A[i].Item2][0])
                {
                    isStable = false;
                    break;
                }
                dict[A[i].Item2].RemoveAt(0);
            }

            Console.WriteLine(isStable ? "Stable" : "Not stable");

            foreach (var a in A)
            {
                Console.WriteLine($"{a.Item1} {a.Item2}");
            }
        }

        static void QuickSort(Tuple<string, int>[] A, int p, int r)
        {
            if (p < r)
            {
                var q = Partition(A, p, r);
                QuickSort(A, p, q - 1);
                QuickSort(A, q + 1, r);
            }
        }

        static int Partition(Tuple<string, int>[] A, int p, int r)
        {
            var x = A[r];
            var i = p - 1;
            for (var j = p; j < r; j++)
            {
                if (A[j].Item2 <= x.Item2)
                {
                    i++;
                    Swap(ref A[i], ref A[j]);
                }
            }

            Swap(ref A[i + 1], ref A[r]);

            return i + 1;
        }

        public static void Swap<T>(ref T one, ref T two)
        {
            var temp = one;
            one = two;
            two = temp;
        }
    }
