		public static int Partition(Card[] c, int p, int r)
		{
			Card tmp = new Card();
			int x = c[r].num;
			int i = p - 1;
			for (int j = p; j < r; j++)
			{
				if (c[j].num <= x)
				{
					i++;
					tmp.mark = c[i].mark;
					tmp.num = c[i].num;
					c[i].mark = c[j].mark;
					c[i].num = c[j].num;
					c[j].mark = tmp.mark;
					c[j].num = tmp.num;
				}
			}
			tmp.mark = c[i + 1].mark;
			tmp.num = c[i + 1].num;
			c[i + 1].mark = c[r].mark;
			c[i + 1].num = c[r].num;
			c[r].mark = tmp.mark;
			c[r].num = tmp.num;
			return i + 1;
		}

		public static void QuickSort(Card[] c, int p, int r)
		{
			if (p < r)
			{
				int q = Partition(c, p, r);
				QuickSort(c, p, q - 1);
				QuickSort(c, q + 1, r);
			}
		}

		public static void MergeSort(Card[] a, int left, int right)
		{
			if (left + 1 < right)
			{
				int mid = (left + right) / 2;
				MergeSort(a, left, mid);
				MergeSort(a, mid, right);
				Merge(a, left, mid, right);
			}
		}
		public static void Merge(Card[] a, int left, int mid, int right)
		{
			int n1 = mid - left;
			int n2 = right - mid;
			Card[] L = new Card[n1 + 1];
			Card[] R = new Card[n2 + 1];
			for (int l = 0; l < n1; l++)
			{
				L[l] = new Card(a[left + l].mark, a[left + l].num);
			}
			for (int l = 0; l < n2; l++)
			{
				R[l] = new Card(a[mid + l].mark, a[mid + l].num);
			}
			L[n1] = new Card(' ', int.MaxValue);
			R[n2] = new Card(' ', int.MaxValue);
			int i = 0, j = 0;
			for (int k = left; k < right; k++)
			{
				if (L[i].num <= R[j].num)
				{
					a[k].mark = L[i].mark;
					a[k].num = L[i].num;
					i++;
				}
				else
				{
					a[k].mark = R[j].mark;
					a[k].num = R[j].num;
					j++;
				}
			}
		}
	}
