                {
                    if(arr[i].InputOrder > arr[k].InputOrder)
                    {
                        isStable = false;
                        break;
                    }
                }
                if (!isStable) break;
            }
            Console.WriteLine(isStable ? "Stable" : "Not stable");
            Console.WriteLine(string.Join<Card>("\n", arr));
        }

         private static void QuickSort<T>(ref T[] arr, int p, int r) where T : IComparable<T>
        {
            if(p < r)
            {
                var q = Partition(ref arr, p, r);
                QuickSort(ref arr, p, q - 1);
                QuickSort(ref arr, q + 1, r);
            }
        }

        private class Card : IComparable<Card>
        {
            public int Number { private set; get; }
            public string Suit { private set; get; }
            public int InputOrder { private set; get; }

            public Card(int n, string s, int o)
            {
                Number = n;
                Suit = s;
                InputOrder = o;
            }

            public int CompareTo(Card other)
            {
                if (Number < other.Number) return -1;
                if (Number > other.Number) return 1;
                return 0;
            }

            public override string ToString()
            {
                return $"{Suit} {Number}";
            }
        }

        private static int Partition<T>(ref T[] arr, int p, int r) where T : IComparable<T>
        {
            var x = arr[r];
            var i = p - 1;
            for(var k = p; k < r; ++k)
            {
                if(arr[k].CompareTo(x) < 1)
                {
                    ++i;
                    Swap(ref arr[i], ref arr[k]);
                }
            }
            Swap(ref arr[i + 1], ref arr[r]);
            return i + 1;
        }

        private static void Swap<T>(ref T v1, ref T v2)
        {
            var tmp = v1;
            v1 = v2;
            v2 = tmp;
        }
    }
}

