                QuickSort(A, p, q - 1);
                QuickSort(A, q + 1, r);
            }
        }

        static int Partition(Card[] A, int p, int r)
        {
            int x = A[r].Number;
            int i = p - 1;
            Card t;
            for (int j = p; j < r; j++)
            {
