    class Program
    {
        public const int INF = 2000000000;
        public const int MAX = 100000;
        public static int n;
        public static Card[] arr_l = new Card[MAX];
        public static Card[] arr_r = new Card[MAX];

        static void Main(string[] args)
        {
            Program.n = int.Parse(Console.ReadLine());
            Card[] arr_q = new Card[n];
            Card[] arr_m = new Card[n];

            for (int i = 0; i < n; i++)
            {
                string[] instr = Console.ReadLine().Split(' ');
                int ii = int.Parse(instr[1]);

                arr_q[i] = new Card(instr[0], ii);
                arr_m[i] = new Card(instr[0], ii);
            }

            for (int i= 0;i < (n/2)+3;i++)
            {
                arr_r[i] = new Card();
                arr_l[i] = new Card();
            }



            QuickSort(arr_q, 0, n - 1);
            MergeSort(arr_m, 0, n);


            String ans = "Stable";
            for (int i= 0; i < n; i++)
            {
                if (arr_m[i].mark != arr_q[i].mark) { ans = "Not stable";break; }
