            {
                Console.WriteLine(arr_q[i].mark + " " + arr_q[i].num);
            }

            Console.ReadLine();

        }

        static void MergeSort(Card[] arr , int l,int r)
        {
            if (l + 1 < r)
            {
                int mid = (l + r) / 2;
                MergeSort(arr,l,mid);
                MergeSort(arr, mid, r);
                Sort(arr,l,mid,r);
            }
        }

        static void Sort(Card[] arr ,int l,int mid,int r)
        {
            int i, j = 0, k=0, a = mid -l,b = r - mid;

            for (i = 0; i < a; i++)
            {
                arr_l[i].mark = arr[l + i].mark;
                arr_l[i].num = arr[ l + i].num;
            }
            for (i = 0; i < b; i++)
            {
                arr_r[i].mark = arr[mid + i].mark;
                arr_r[i].num  = arr[mid + i].num;
            }
            arr_l[a].num = INF; arr_r[b].num = INF;

            for (int m = l; m < r; m++)
            {
                 if (arr_l[j].num <= arr_r[k].num )
                {
                    arr[m].num = arr_l[j].num;
                    arr[m].mark = arr_l[j].mark;
                    j++;
                }
                else
                {
                    arr[m].num = arr_r[k].num;
                    arr[m].mark = arr_r[k].mark;
                    k++;
                }
            }
        }

        static void QuickSort(Card[] arr, int p, int r)
        {
            if (p < r)
            {
                int q = Part(arr , p, r);
                QuickSort(arr, p, q - 1);
                QuickSort(arr, q + 1, r);
            }
        }

        static int Part(Card[] arr, int p, int r)
        {
            Card x = arr[r];
            Card t;
            int j, i = p - 1;
            for (j = p; j < r; j++)
            {
                if (arr[j].num <= x.num)
                {
                    i++;
                    t = arr[i];arr[i] = arr[j];arr[j] = t;
                }
            }
            t = arr[r]; arr[r] = arr[i+1]; arr[i+1] = t;
            return i + 1;
        }
    }
}

