            2   x = A[r]
            3   i = p-1
            4   for j = p to r-1
            4     if A[j] <= x
            5       i = i+1
            6       A[i] ??¨ A[j] ?????????
            7   A[i+1] ??¨ A[r] ?????????
            8   return i+1
         **/

        int x = A[r].IntValue;
        int i = p - 1;
        for (int j = p; j <= r - 1; j++)
        {
            if (A[j].IntValue <= x)
            {
                i++;
                InputItem.Replace(A[i], A[j]);
            }
        }
        InputItem.Replace(A[i + 1], A[r]);
        return i + 1;
    }


