			int x = c[r].num;
			int i = p - 1;
			for (int j = p; j < r; j++)
			{
				if (c[j].num <= x)
				{
					i++;
					tmp.mark = c[i].mark;
					tmp.num = c[i].num;
					c[i].mark = c[j].mark;
					c[i].num = c[j].num;
					c[j].mark = tmp.mark;
					c[j].num = tmp.num;
				}
			}
			tmp.mark = c[i + 1].mark;
			tmp.num = c[i + 1].num;
			c[i + 1].mark = c[r].mark;
			c[i + 1].num = c[r].num;
			c[r].mark = tmp.mark;
			c[r].num = tmp.num;
			return i + 1;
