    static void Swap(Card[] A, int a, int b){
        var tmp=A[a];
        A[a]=A[b];
        A[b]=tmp;
    }

    static int Partition(Card[] A, int p, int r){
        var x=A[r-1].value;
        var i=p-1;
        for(var j=p; j<r-1; j++){
            if(A[j].value<=x){
                i++;
                Swap(A, i, j);
            }
        }
        Swap(A, i+1, r-1);
        return i+1;
    }

    static void QuickSort(Card[] A, int p, int r){
        if(p+1<r){
            var q=Partition(A, p, r);
            QuickSort(A, p, q-1);
            QuickSort(A, q, r);
        }
    }

    static void Merge(Card[] A, int left, int mid, int right){
        var n1=mid-left;
        var n2=right-mid;
        var L=new Card[n1+1];
        var R=new Card[n2+1];
        for(var i=0; i<n1; i++){
            L[i]=A[left+i];
        }
