        for (int i = 0; i < n; i++) {
            Console.WriteLine(quick[i].ToString());
        }

        #region Flush
#if !DEBUG
        Console.Out.Flush();
        sw.Close();
#endif
        #endregion
    }

    private static void QuickSort(Card[] cards, int p, int r) {
        if (p < r) {
            var q = Partition(cards, p, r);
            QuickSort(cards, p, q - 1);
            QuickSort(cards, q + 1, r);
        }
    }

    private static int Partition(Card[] cards, int p, int r) {
        var x = cards[r].Value;
        var i = p - 1;
        for (int j = p; j < r; j++) {
            if (cards[j].Value <= x) {
                i++;
                cards.Swap(i, j);
            }
        }

        cards.Swap(i + 1, r);
        return i + 1;   // 基準位置
    }

    private static void MergeSort(Card[] cards, int left, int right) {
        if (right - left >= 2) {
            var mid = (right + left) / 2;
            MergeSort(cards, left, mid);
            MergeSort(cards, mid, right);
            Merge(cards, left, mid, right);
        }
    }

    private static void Merge(Card[] cards, int left, int mid, int right) {
        var n1 = mid - left;
        var n2 = right - mid;

        var lArr = new Card[n1 + 1];
        var rArr = new Card[n2 + 1];

        for (int i = 0; i < n1; i++) {
            lArr[i] = cards[left + i];
        }
        lArr[n1] = new MaxCard();

        for (int i = 0; i < n2; i++) {
            rArr[i] = cards[mid + i];
        }
        rArr[n2] = new MaxCard();

        int l = 0, r = 0;
        for (int i = left; i < right; i++) {
            if (lArr[l].Value <= rArr[r].Value) {
                cards[i] = lArr[l];
                l++;
            } else {
                cards[i] = rArr[r];
                r++;
            }
        }
    }
}

