    }
}

/// <summary>組み合わせ</summary>
class ModCombination {
    private int mod;
    private int[] fac;
    private int[] finv;
    private int[] inv;

    public ModCombination(int max, int mod = 1000000007) {
        this.mod = mod;
        fac = new int[max]; // modが法のn!の列

        inv = new int[max]; // indexの逆元の列
        finv = new int[max]; // modを法とした、invの累積の累積

        fac[0] = 1; fac[1] = 1;
        finv[0] = 1; finv[1] = 1;
        inv[1] = 1;

        for (int i = 2; i < max; i++) {
            fac[i] = (int)(Math.BigMul(fac[i - 1], i) % mod);  // factorを求める
            var s = Math.BigMul(inv[mod % i], mod / i) % mod;
            inv[i] = (int)(mod - s);　 // iに対する逆元を求める
            finv[i] = (int)(Math.BigMul(finv[i - 1], inv[i]) % mod);
        }
    }
    /// <summary>nCk</summary>
    public int Calculation(int n, int k) {
        if (n < k) return 0;
        if (n < 0 || k < 0) return 0;

        return (int)(Math.BigMul(fac[n], (int)(Math.BigMul(finv[k], finv[n - k]) % mod)) % mod);
    }
}

/// <summary>あまりを計算するためのintのラッパー</summary>
struct ModInt {
    int Value { get; }
    int Mod { get; }

    public override string ToString() {
        return Value.ToString();
    }

    public static explicit operator ModInt(long value) {
        return new ModInt(value);
    }

    public ModInt(long value, int mod = 1000000007) {
        this.Value = (int)(value % mod);
        this.Mod = mod;
    }

    public static explicit operator int(ModInt modInt) {
        return modInt.Value;
    }

    private static void CheckNotEqualMod(ModInt item1, ModInt item2) {
        if (item1.Mod != item2.Mod) {
            throw new Exception("mod not equal");
        }
    }

    public static ModInt operator +(ModInt item1, ModInt item2) {
        CheckNotEqualMod(item1, item2);
        long value = item1.Value + item2.Value;
        return new ModInt(value, item1.Mod);
    }

    public static ModInt operator *(ModInt item1, ModInt item2) {
        CheckNotEqualMod(item1, item2);
        long value = Math.BigMul(item1.Value, item2.Value);
        return new ModInt(value, item1.Mod);
    }

    public static ModInt operator -(ModInt item1, ModInt item2) {
        CheckNotEqualMod(item1, item2);
        long value = item1.Value - item2.Value;
        if (value < 0) {
            value += item1.Mod;
        }
        return new ModInt(value, item1.Mod);
    }

    public static ModInt operator +(ModInt item1, int item2) {
        return item1 + new ModInt(item2, item1.Mod);
    }

    public static ModInt operator *(ModInt item1, int item2) {
        return item1 * new ModInt(item2, item1.Mod);
    }

    public static ModInt operator -(ModInt item1, int item2) {
        return item1 - new ModInt(item2, item1.Mod);
    }


    public override int GetHashCode() {
        return this.Value;
    }

    public override bool Equals(object obj) {
        if (obj == null || this.GetType() != obj.GetType()) {
            return false;
        }

        var modIntObj = (ModInt)obj;
        return modIntObj.Value == this.Value;
    }

    public static bool operator ==(ModInt item1, ModInt item2) {
        return item1.Value == item2.Value;
    }

    public static bool operator !=(ModInt item1, ModInt item2) {
        return !(item1 == item2);
    }

    public static bool operator ==(ModInt item1, int item2) {
        return item1.Value == item2;
    }

    public static bool operator !=(ModInt item1, int item2) {
        return !(item1.Value == item2);
    }

    public static bool operator >=(ModInt item1, ModInt item2) {
        return item1.Value >= item2.Value;
    }

    public static bool operator <=(ModInt item1, ModInt item2) {
        return item1.Value <= item2.Value;
    }

    public static bool operator >=(ModInt item1, int item2) {
        return item1.Value >= item2;
    }

    public static bool operator <=(ModInt item1, int item2) {
        return item1.Value <= item2;
    }

    public static bool operator >(ModInt item1, ModInt item2) {
        return item1.Value > item2.Value;
    }

    public static bool operator <(ModInt item1, ModInt item2) {
        return item1.Value < item2.Value;
    }

    public static bool operator >(ModInt item1, int item2) {
        return item1.Value >= item2;
    }

    public static bool operator <(ModInt item1, int item2) {
        return item1.Value <= item2;
    }
}

using System;

namespace ALDS1_6_C
{
    public static class Sort
    {
        public delegate void SwapperAction<T>(ref T a, ref T b);
        public static void QuickSort<T>(this T[] a, SwapperAction<T> swapper) where T : IComparable
        {
            QuickSort(a, 0, a.Length - 1, swapper);
        }

        private static void QuickSort<T>(T[] a, int s, int t, SwapperAction<T> swapper) where T : IComparable
        {
            if (s < t)
            {
                int mid = Partition(a, s, t, swapper);
                QuickSort(a, s, mid - 1, swapper);
                QuickSort(a, mid + 1, t, swapper);
            }
        }
        private static int Partition<T>(T[] a, int s, int t, SwapperAction<T> swapper) where T : IComparable
        {
            int p = s;
            T x = a[t];
            for (int i = s; i < t; ++i)
            {
                if (a[i].CompareTo(x) <= 0) swapper.Invoke(ref a[p++], ref a[i]);
            }
            swapper.Invoke(ref a[p], ref a[t]);
            return p;
        }
    }
    class Program
    {
        class Card : IComparable
        {
            public int num;
            public char kind;
            public int oldPos;
            public int CompareTo(object obj)
            {
                return num.CompareTo((obj as Card).num);
            }
            public override string ToString()
            {
                return kind.ToString() + " " + num; 
            }

            public static Card Parse(string str)
            {
                var strs = str.Split(' ');
                return new Card() { kind = strs[0][0], num = int.Parse(strs[1]) };
            }

            public static void Swapper(ref Card a, ref Card b)
            {
                Card t = a;
                a = b;
                b = t;
            }
        }
        static void Main(string[] args)
        {
            var n = int.Parse(Console.ReadLine());
            var cards = new Card[n];
            for (int i = 0; i < n; i++)
            {
                cards[i] = Card.Parse(Console.ReadLine());
                cards[i].oldPos = i;
            }
            cards.QuickSort(Card.Swapper);
            Console.WriteLine(IsStatble(cards) ? "Stable" : "Not stable");
            foreach (var card in cards) Console.WriteLine(card);
        }

        static bool IsStatble(Card[] cards)
        {
            Card pre = null;
            foreach (var card in cards)
            {
                if (pre == null) pre = card;
                else if (card.num != pre.num) pre = null;
                else if (card.oldPos < pre.oldPos) return false;
                else pre = card;
            }
            return true;
        }
    }
