        private int num;

        public Card(string suit, int num)
        {
            this.suit = suit;
            this.num = num;
        }

        public bool IsLarger(Card targetCard)
        {
            return targetCard.num <= this.num;
        }

        public override bool Equals(object obj)
        {
            if (obj == null || this.GetType() != obj.GetType())
            {
                return false;
            }

            Card targetCard = (Card)obj;

            return this.suit == targetCard.suit && this.num == targetCard.num;
        }

        public override string ToString()
        {
            return string.Format("{0} {1}", this.suit, this.num);
        }
    }
