        static void Sort<T>(T[] A, int p, int r) where T:IComparable<T>
        {
            if (p >= r) return;
            int x = Partition(A, p, r);
            Sort(A, p, x - 1);
            Sort(A, x + 1, r);

        }
        static int Partition<T>(T [] A, int p, int r)where T:IComparable<T>
        {
            T x = A[r];
            int i = p - 1;
            for(int j=p;j<r;j++)
            {
                if(A[j].CompareTo(x)<=0)
                {
                    i++;
                    if (i != j)
                    {
                        T t = A[i];
                        A[i] = A[j];
                        A[j] = t;
                    }
                }

            }
            T tmp = A[i + 1];
            A[i + 1] = A[r];
            A[r] = tmp;

            return i+1;
        }
        static bool isStable( card[] sortCards)
        {
            for(int i=0;i<sortCards.Length-1;i++)
            {
                if (sortCards[i].CompareTo(sortCards[i + 1]) == 0 && sortCards[i].pos > sortCards[i + 1].pos)
                    return false;
            }
            return true;
