function partition(A,p,r) {
	let x = A[r].num;
	let i = p - 1;
	let tmp;
	for (let j = p; j < r; j++) {
		if (A[j].num <= x) {
			i++;
			tmp=A[i]; A[i]=A[j]; A[j]=tmp;
		}
	}
	i++;
	tmp=A[i]; A[i]=A[r]; A[r]=tmp;

	return i;
}

function quickSort(A,p,r) {
	if (p >= r) return;
	let q = partition(A,p,r);
	quickSort(A,p,q-1);
	quickSort(A,q+1,r);
}

