function partition(A, p, r) {
    let lower = p - 1;
    const x = A[r];

    for (let i = p; i < r; i++) {
        if (A[i].num <= x.num) {
            lower++;
            let t = A[lower];
            A[lower] = A[i];
            A[i] = t;
        }
    }

    t = A[lower + 1];
    A[lower + 1] = A[r];
    A[r] = t;
    return lower + 1;
}


