function sort(A, p, r) {
  if (r - p >= 2) {
    q = partition(A, p, r);
    sort(A, p, q);
    sort(A, q+1, r);
  }
}

function partition(A, p, r) {
  var x, i, j, tmp;
  x = A[r - 1].number;
  i = p;
  for (j = p; j < r - 1; j++) {
    if (A[j].number <= x) {
      tmp = A[i];
      A[i] = A[j];
      A[j] = tmp;
      i++;
    }
  }
  tmp = A[i];
  A[i] = A[r - 1];
  A[r - 1] = tmp;
  return i;
}

function get_doubled_numbers(ary) {
  var numbers, res, i, cur, cnt;
  numbers = ary.map(function (x) { return x.number; });
  numbers.sort(function (a, b) { return a - b; });
  res = [];
  cur = 0;
  cnt = 0;
  for (i in numbers) {
    if (numbers[i] !== cur) {
      if (cnt >= 2) res.push(cur);
      cur = numbers[i];
      cnt = 1;
    } else {
      cnt++;
    }
  }
  if (cnt >= 2) res.push(cur);
  return res;
}

