def partition(a, p, r)
  x = a[r]
  i = p - 1
  p.upto(r - 1) do |j|
    if a[j] <= x
      i += 1
      a[i], a[j] = a[j], a[i]
    end
  end
  a[i+1], a[r] = a[r], a[i+1]
  i+1
end

