class QuickSort

  class Card
    attr_accessor :mark, :number

    def initialize(mark, number)
      @mark = mark
      @number = number
    end

  end

  # Example:
  # a ::= [ "D 3", "H 2", "D 1" ]
  def initialize(a)
    @cards = []
    @stable = true
    a.each do |pair|
      mark, number = pair.split
      @cards << Card.new(mark, number.to_i)
    end
  end

  def solve(p, r)
    if p < r
      q = partition(p, r)
      solve(p, q-1)
      solve(q+1, r)
    end
  end

  def dump
    puts @stable ? "Stable" : "Not stable"
    @cards.each do |card|
      puts "#{card.mark} #{card.number}"
    end
  end

  private

    def partition(p, r)
      x = @cards[r].number
      i = p - 1
      (p..r-1).each do |j|
        if @cards[j].number <= x
          i += 1
          @cards[i], @cards[j] = @cards[j], @cards[i]
          @stable = stable_swap?(i, j)
        end
      end
      @cards[i+1], @cards[r] = @cards[r], @cards[i+1]
      @stable = stable_swap?(i+1, r)
      return i+1
    end

    def stable_swap?(i, j)
      if i != j &&
         @cards[i].mark != @cards[j].mark &&
         @cards[i].number == @cards[j].number
         return false
      end
      return true
    end

end

