// return 1 if x > y
// return -1 if x < y
// return 0 if x == y
func compare(x, y card) int {
	if x.number > y.number {
		return 1
	} else if x.number < y.number {
		return -1
	} else {
		return 0
	}
}

func isSame(x, y []card) bool {
	if len(x) != len(y) {
		return false
	}
	for i := 0; i < len(x); i++ {
		if x[i] != y[i] {
			return false
		}
	}
	return true
}

func partition(cards []card) int {
	n := len(cards)
	pos := 0
	pivot := cards[n-1]
	for i := 0; i < n-1; i++ {
		if compare(cards[i], pivot) <= 0 {
			cards[i], cards[pos] = cards[pos], cards[i]
			pos++
		}
	}
	cards[pos], cards[n-1] = pivot, cards[pos]
	return pos
}

func quickSort(cards []card) {
	if len(cards) <= 1 {
		return
	}
	p := partition(cards)
	quickSort(cards[:p])
	quickSort(cards[(p+1):])
}

func mergeSort(cards []card) []card {
	SENTINEL := card{mark: "X", number: 1000000001} // for merge sort
	if len(cards) == 1 {
		return []card{cards[0]}
	}
	mid := len(cards) / 2
	leftCards := append(mergeSort(cards[:mid]), SENTINEL)
	rightCards := append(mergeSort(cards[mid:]), SENTINEL)

	var li, ri, i int
	newCards := make([]card, len(cards))
	for i < len(cards) {
		if compare(leftCards[li], rightCards[ri]) <= 0 {
			newCards[i] = leftCards[li]
			li++
		} else {
			newCards[i] = rightCards[ri]
			ri++
		}
		i++
	}
	return newCards
}

