func partition(a []Card, p, r int) int {
	x := a[r]
	i := p - 1
	m := make(map[int]int, 0)
	for j := p; j < r; j++ {
		if a[j].i <= x.i {
			i++
			m[a[i].i]--
			a[i], a[j] = a[j], a[i]
			continue
		}
		_, ok := m[a[j].i]
		if ok {
			m[a[j].i]++
		} else {
			m[a[j].i] = 1
		}
	}
	a[i+1], a[r] = a[r], a[i+1]
	m[a[i+1].i]--
	for _, c := range m {
		if c > 1 {
			stable = false
			break
		}
	}
	return i + 1
}

func quickSort(a []Card, p, r int) {
	if p >= r {
		return
	}
	q := partition(a, p, r)
	quickSort(a, p, q-1)
	quickSort(a, q+1, r)
}

