func isLTE(a, b card) bool {
	return a.number <= b.number
}

func isEQU(a, b card) bool {
	return a.suit == b.suit && a.number == b.number
}

func areEQU(a, b []card) bool {
	lenA := len(a)
	if lenA != len(b) {
		return false
	}
	for i, ca := range a {
		if isEQU(ca, b[i]) {
			continue
		} else {
			return false
		}
	}
	return true
}

func partition(ar []card, p, r int) int {
	x := ar[r]
	i := p - 1
	for j := p; j <= r-1; j++ {
		if isLTE(ar[j], x) {
			i++
			ar[i], ar[j] = ar[j], ar[i]
		}
	}
	ar[i+1], ar[r] = ar[r], ar[i+1]
	return i + 1
}

func qsort(ar []card, p, r int) {
	if p < r {
		q := partition(ar, p, r)
		qsort(ar, p, q-1)
		qsort(ar, q+1, r)
	}
}

