	leftCards := mergeSort(cards[:mid])
	rightCards := mergeSort(cards[mid:])

	var li, ri, i int
	newCards := make([]card, len(cards))
	for li < len(leftCards) && ri < len(rightCards) {
		if compare(leftCards[li], rightCards[ri]) <= 0 {
			newCards[i] = leftCards[li]
			li++
		} else {
			newCards[i] = rightCards[ri]
			ri++
		}
		i++
	}
	for i < len(cards) {
		if li == len(leftCards) {
			newCards[i] = rightCards[ri]
			ri++
		} else {
			newCards[i] = leftCards[li]
			li++
		}
		i++
	}
	return newCards
}

func main() {
	sc := bufio.NewScanner(os.Stdin)
	sc.Split(bufio.ScanWords)

	n, err := nextInt(sc)
	if err != nil {
		panic(err)
	}
	cards := make([]card, n)

	for i := 0; i < n; i++ {
		mark := nextText(sc)
		number, err := nextInt(sc)
		if err != nil {
			panic(err)
		}
		cards[i] = card{mark: mark, number:number}
	}

	sortedByMerge := mergeSort(cards)
	quickSort(cards)

	if isSame(sortedByMerge, cards) {
		fmt.Println("Stable")
	} else {
		fmt.Println("Not stable")
	}

	for i := 0; i < n; i++ {
		fmt.Printf("%s %d\n", cards[i].mark, cards[i].number)
	}
}

func nextText(sc *bufio.Scanner) string {
	sc.Scan()
	return sc.Text()
}

func nextInt(sc *bufio.Scanner) (int, error) {
	return strconv.Atoi(nextText(sc))
}

