		b[i].Suit = s[0]
		a[i].Value, _ = strconv.Atoi(s[1])
		b[i].Value, _ = strconv.Atoi(s[1])
	}

	mergeSort(a, n, 0, n)
	quickSort(b, n, 0, n-1)

	for i := 0; i < n; i++ {
		if a[i].Suit != b[i].Suit {
			isStable = false
		}
	}

	if isStable {
