// [p, r) の半開区間に注意
func partition(A []*Card, n, p, r int) int {
	x := A[r]
	i := p - 1 // p == 0 のとき i == -1 からスタートする
	// 半開区間でなめる
	for j := p; j < r; j++ {
		if A[j].val <= x.val {
			i++
			A[i], A[j] = A[j], A[i]
		}
	}
	A[i+1], A[r] = A[r], A[i+1]
	return i + 1
}

