// ----- Quick Sort -----
func partition(xs []card, p int, r int) int {
	x := xs[r]
	as := xs[:len(xs)-1]
	i := p - 1 // 前パーティションの最後の要素のポインタ
	j := p
	for j < len(as) {
		target := as[j]
		if target.value <= x.value {
			i++
			as[j] = as[i]
			as[i] = target
		}
		j++
	}
	xs[r] = xs[i+1]
	xs[i+1] = x
	return i + 1
}

func quickSort(l []card, p int, r int) {
	if p < r {
		q := partition(l, p, r)
		quickSort(l, p, q-1)
		quickSort(l, q+1, r)
	}
}

