type Card struct {
	suit string
	num  int
}

func (c *Card) String() string {
	return fmt.Sprintf("%s %d", c.suit, c.num)
}

type cards []*Card

func (cs cards) String() string {
	var buf bytes.Buffer
	sep := ""
	for _, v := range cs {
		buf.WriteString(fmt.Sprintf("%s%s", sep, v))
		sep = " "
	}
	return buf.String()
}

func merge(left, right []*Card) {
	a := append(left, right...)
	tmpl := make([]*Card, len(left)+1)
	tmpr := make([]*Card, len(right)+1)
	copy(tmpl, left)
	copy(tmpr, right)
	tmpl[len(tmpl)-1] = &Card{"?", 1000000001}
	tmpr[len(tmpr)-1] = &Card{"?", 1000000001}
	i, j := 0, 0
	for k := 0; k < len(a); k++ {
		if tmpl[i].num <= tmpr[j].num {
			a[k] = tmpl[i]
			i++
		} else {
			a[k] = tmpr[j]
			j++
		}
	}
}

func mergeSort(a []*Card) {
	if len(a) > 1 {
		mid := len(a) / 2
		left := a[:mid]
		right := a[mid:]
		mergeSort(left)
		mergeSort(right)
		merge(left, right)
	}
}

/*
なぜピボットを最後尾にするかといえば，
それはpartitionのアルゴリズムが，
最後尾がピボットだとやりやすいからである．
uickSortを最後尾以外の要素をピボットにするには，
quickSort開始時に，任意のピボットを最後尾の要素と入れ替えておけばいい.
*/
func partition(a []*Card) int {
	x := a[len(a)-1]
	i := -1
	for j := 0; j < len(a)-1; j++ {
		if a[j].num <= x.num {
			i++
			a[i], a[j] = a[j], a[i]
		}
	}
	a[i+1], a[len(a)-1] = a[len(a)-1], a[i+1]
	return i + 1
}
func quickSort(a []*Card) {
	if len(a) > 1 {
		q := partition(a)
		quickSort(a[:q])
		quickSort(a[q+1:])
	}
}
func sliceEq(a, b []*Card) bool {
	if len(a) != len(b) {
		return false
	}
	for i := 0; i < len(a); i++ {
		if !(a[i].num == b[i].num && a[i].suit == b[i].suit) {
			return false
		}
	}
	return true
}

