func quickSort(cards []Card) {
	if len(cards) > 1 {
		q := partition(cards, 0, len(cards)-1)
		quickSort(cards[:q])
		quickSort(cards[q+1:])
	}
}

func partition(cards []Card, p int, r int) int {
	k := p - 1
	v := cards[r].value
	for i := p; i < r; i++ {
		if cards[i].value <= v {
			k++
			cards[i], cards[k] = cards[k], cards[i]
		}
	}
	cards[r], cards[k+1] = cards[k+1], cards[r]
	return k
}

func mergeSort(elems []Card) ([]Card, int) {
	length := len(elems)
	if length == 1 {
		return elems, 0
	}
	mid := length / 2
	left, countL := mergeSort(elems[:mid])
	right, countR := mergeSort(elems[mid:])
	sorted, countS := merge(left, right)
	return sorted, (countL + countR + countS)
}

func merge(xs, ys []Card) ([]Card, int) {
	sorted := make([]Card, 0)
	count := 0
	for len(xs) > 0 && len(ys) > 0 {
		if xs[0].value <= ys[0].value {
			sorted = append(sorted, xs[0])
			xs = xs[1:]
		} else {
			sorted = append(sorted, ys[0])
			ys = ys[1:]
		}
		count++
	}
	if len(xs) > 0 {
		sorted = append(sorted, xs...)
		count += len(xs)
	} else if len(ys) > 0 {
		sorted = append(sorted, ys...)
		count += len(ys)
	}
	return sorted, count
}

