func nextInt(sc *bufio.Scanner) int {
	sc.Scan()
	n, err := strconv.Atoi(sc.Text())
	if err != nil {
		panic(err)
	}
	return n
}

func nextStr(sc *bufio.Scanner) string {
	sc.Scan()
	return sc.Text()
}

func main() {
	sc := bufio.NewScanner(os.Stdin)
	sc.Split(bufio.ScanWords)
	n := nextInt(sc)
	l := make([]card, n)
	for i := 0; i < n; i++ {
		l[i] = card{
			label: nextStr(sc),
			value: nextInt(sc),
		}
	}
	origin := make([]card, n)
	copy(origin, l)

	quickSort(l, 0, n-1)
	l2 := mergeSort(origin)

	count := 0
	for i := range l {
		if l[i] == l2[i] {
			count++
		} else {
			break
		}
	}
	if count == n {
		fmt.Println("STABLE")
	} else {
		fmt.Println("UNSTABLE")
	}
	for _, x := range l {
		fmt.Printf("%s %d\n", x.label, x.value)
	}
}

