)

const SENTINEL = 2000000000

type Card struct {
	mark string
	number int
}

/***********************************************************************
関数merge:
	引数:
		配列A = 内部的にleftからmid-1までとmidからrightまでの二つに分かれている
		n = Aの長さ
		left = 統合される対象の配列のAにおける先頭インデックス
		mid = 統合される対象の配列のAにおける末尾インデックス
		right = 統合される対象の配列Aにおける末尾インデックス
***********************************************************************/
func merge(A []Card, n, left, mid, right int) {
	n1 := mid - left
	L := make([]Card, n1+1)
	n2 := right - mid
	R := make([]Card, n2+1)
	for i := 0; i < n1; i++ {
		L[i] = A[left+i]
	}
	for i := 0; i < n2; i++ {
		R[i] = A[mid+i]
	}
	L[n1].number, R[n2].number = SENTINEL, SENTINEL
	i, j := 0 ,0
	for k := left; k < right; k++ {
		if L[i].number <= R[j].number {
			A[k] = L[i]
			i++
			continue
		}
		A[k] = R[j]
		j++
	}
}

/***********************************************************************
関数mergeSort:
	引数:
		配列A = 内部的にleftからmid-1までとmidからrightまでの二つに分かれている
		n = Aの長さ
		left = 統合される対象の配列のAにおける先頭インデックス
		right = 統合される対象の配列Aにおける末尾インデックス
***********************************************************************/
func mergeSort(A []Card, n, left, right int) {
	mid := 0
	if left+1 < right {
		mid = (left + right)/2
		mergeSort(A, n, left, mid)
		mergeSort(A, n, mid, right)
		merge(A, n, left, mid, right)
	}
}

/***********************************************************************
関数partation:
	引数:
		配列A = 分割される対象となる配列を部分として含む配列
		n = Aの長さ
		p = 分割される対象となる配列の先頭インデックス
		r = 分割される対象となる配列の末尾インデックス
***********************************************************************/
func partation(A []Card, n, p, r int) int {
	last := A[r]
	i := p - 1
	for j := p; j < r; j++ {
		if A[j].number <= last.number {
			i++
			A[i], A[j] = A[j], A[i]
		}
	}
	A[i+1], A[r] = A[r], A[i+1]
	return i+1
}

/***********************************************************************
関数quickSort:
	引数:
		配列A =ソートされる対象となる配列を部分として含む配列
		n = Aの長さ
		p = ソートされる対象となる配列の先頭インデックス
		r = ソートされる対象となる配列の末尾インデックス
***********************************************************************/
func quickSort(A []Card, n, p, r int) {
	q := 0
	if p < r {
		q = partation(A, n, p, r)
		quickSort(A, n, p, q-1)
		quickSort(A, n, q, r)
	}
}

func solve(reader io.Reader) string {
	scanner := bufio.NewScanner(reader)
	scanner.Scan()
	n, _ := strconv.Atoi(scanner.Text())
	A, B := make([]Card, n), make([]Card, n)
	for i := range A {
		scanner.Scan()
		info := strings.Split(scanner.Text(), " ")
		A[i].mark = info[0]
		A[i].number, _ = strconv.Atoi(info[1])
		B[i].mark, B[i].number = A[i].mark, A[i].number
	}

	mergeSort(A, n, 0, n)
	quickSort(A, n, 0, n-1)

	var memo bytes.Buffer
	if reflect.DeepEqual(A, B) {
		memo.WriteString("Stable\n")
	} else {
		memo.WriteString("Not stable\n")
	}

	for i := range B {
		memo.WriteString(B[i].mark + " " + strconv.Itoa(B[i].number) + "\n")
	}
	return strings.TrimRight(memo.String(), "\n")
}

func main() {
	fmt.Println(solve(os.Stdin))
}

