}

func main() {

	sc := bufio.NewScanner(os.Stdin)
	sc.Scan()
	n, _ := strconv.Atoi(sc.Text())

	var A []card
	for {
		sc.Scan()
		instr := sc.Text()
		if instr == "" {
			break
		}
		in2 := strings.Split(instr, " ")
		mark := in2[0]
		val, _ := strconv.Atoi(in2[1])
		A = append(A, card{mark, val})

	}

	qA := append([]card{}, A...)
	mA := append([]card{}, A...)

	quickSort(qA, 0, n-1)

	if reflect.DeepEqual(mergeSort(mA), qA) {
		fmt.Println("Stable")
	} else {
		fmt.Println("Not stable")
	}

	for _, m := range qA {
		fmt.Printf("%v %v", m.mark, m.val)
		fmt.Println()
	}

}

func quickSort(A []card, p int, r int) { // infinite loop for #5 http://judge.u-aizu.ac.jp/onlinejudge/review.jsp?rid=3964211#3
	if p < r {
		q := partition(A, p, r)
		quickSort(A, p, q-1)
		quickSort(A, q+1, r)
	}

	return
}

func partition(A []card, p int, r int) int {
	x := A[r].val
	i := p
	for j := p; j < r; j++ {
		if A[j].val <= x {
			A[i], A[j] = A[j], A[i]
			i++
		}
	}
	A[i], A[r] = A[r], A[i]
	return i
}

func mergeSort(val []card) []card {
	length := len(val)
	if length == 1 {
		return val
	}

	var mid int
	if len(val)%2 == 0 {
		mid = length / 2
	} else {
		mid = length/2 + 1
	}
	left := val[:mid]
	right := val[mid:len(val)]

	lr := mergeSort(left)
	rr := mergeSort(right)

	return merge(lr, rr)
}

var count int

func merge(a1 []card, a2 []card) []card {
	var result []card
	a1Idx := 0
	a2Idx := 0
	for {
		a1done := len(a1) <= a1Idx
		a2done := len(a2) <= a2Idx
		if a1done && a2done {
			return result
		} else if a1done {
			result = append(result, a2[a2Idx])
			a2Idx++
			continue
		} else if a2done {
			result = append(result, a1[a1Idx])
			a1Idx++
			continue
		}
		count++
		if a1[a1Idx].val <= a2[a2Idx].val {
			result = append(result, a1[a1Idx])
			a1Idx++
		} else {
			result = append(result, a2[a2Idx])
			a2Idx++
		}
	}
}

