	SENTINEL := card{mark: "X", number: 1000000001} // for merge sort
	if len(cards) == 1 {
		return []card{cards[0]}
	}
	mid := len(cards) / 2
	leftCards := append(mergeSort(cards[:mid]), SENTINEL)
	rightCards := append(mergeSort(cards[mid:]), SENTINEL)

	var li, ri, i int
	newCards := make([]card, len(cards))
	for i < len(cards) {
		if compare(leftCards[li], rightCards[ri]) <= 0 {
