func compare(x, y card) int {
	if x.number > y.number {
		return 1
	} else if x.number < y.number {
		return -1
	} else {
		return 0
	}
}

func isSame(x, y []card) bool {
	if len(x) != len(y) {
		return false
	}
	for i := 0; i < len(x); i++ {
		if x[i] != y[i] {
			return false
		}
	}
	return true
}

func partition(cards []card) int {
	n := len(cards)
	pos := 0
	pivot := cards[n-1]
	for i := 0; i < n-1; i++ {
		if compare(cards[i], pivot) < 0 {
			cards[i], cards[pos] = cards[pos], cards[i]
			pos++
		}
	}
	cards[pos], cards[n-1] = pivot, cards[pos]
	return pos
}

func quickSort(cards []card) {
	if len(cards) <= 1 {
		return
	}
	p := partition(cards)
	quickSort(cards[:p])
	quickSort(cards[(p+1):])
}

func mergeSort(cards []card) []card {
	if len(cards) <= 1 {
		return cards
	}
	mid := len(cards) / 2
	leftCards := mergeSort(cards[:mid])
	rightCards := mergeSort(cards[mid:])

	var li, ri, i int
	newCards := make([]card, len(cards))
	for li < len(leftCards) && ri < len(rightCards) {
		if compare(leftCards[li], rightCards[ri]) <= 0 {
			newCards[i] = leftCards[li]
			li++
		} else {
			newCards[i] = rightCards[ri]
			ri++
		}
		i++
	}
	for i < len(cards) {
		if li == len(leftCards) {
			newCards[i] = rightCards[ri]
			ri++
		} else {
			newCards[i] = leftCards[li]
			li++
		}
		i++
	}
	return newCards
}

func main() {
	sc := bufio.NewScanner(os.Stdin)
	sc.Split(bufio.ScanWords)

