	if err != nil {
		panic(err)
	}
	copied := make([]Card, len(cards))
	copy(copied, cards)
	quickSort(cards)
	sortedByMerge, _ := mergeSort(copied)
	if isEqualCards(cards, sortedByMerge) {
		fmt.Println("Stable")
	} else {
		fmt.Println("Not stable")
	}
	for _, card := range cards {
		fmt.Printf("%s %d\n", card.mark, card.value)
	}
}

func quickSort(cards []Card) {
	if len(cards) > 1 {
		q := partition(cards, 0, len(cards)-1)
		quickSort(cards[:q])
		quickSort(cards[q+1:])
	}
}

func partition(cards []Card, p int, r int) int {
	// fmt.Printf("before: %v\n", cards)
	k := p - 1
	v := cards[r].value
	for i := p; i < r; i++ {
		if cards[i].value <= v {
			k++
			cards[i], cards[k] = cards[k], cards[i]
		}
	}
	k++
	cards[r], cards[k] = cards[k], cards[r]
	// fmt.Printf("after: %v\n", cards)
	return k
}

func mergeSort(elems []Card) ([]Card, int) {
	length := len(elems)
	if length == 1 {
		return elems, 0
	}
	mid := length / 2
	left, countL := mergeSort(elems[:mid])
	right, countR := mergeSort(elems[mid:])
	sorted, countS := merge(left, right)
	return sorted, (countL + countR + countS)
}

func merge(xs, ys []Card) ([]Card, int) {
	sorted := make([]Card, 0)
	count := 0
	for len(xs) > 0 && len(ys) > 0 {
		if xs[0].value <= ys[0].value {
			sorted = append(sorted, xs[0])
			xs = xs[1:]
		} else {
			sorted = append(sorted, ys[0])
			ys = ys[1:]
		}
		count++
	}
	if len(xs) > 0 {
		sorted = append(sorted, xs...)
		count += len(xs)
	} else if len(ys) > 0 {
		sorted = append(sorted, ys...)
		count += len(ys)
	}
	return sorted, count
}

func nextInt(sc *bufio.Scanner) (int, error) {
	sc.Scan()
	return strconv.Atoi(sc.Text())
}

func nextText(sc *bufio.Scanner) string {
	sc.Scan()
	return sc.Text()
}

func nextCard(sc *bufio.Scanner) (Card, error) {
	mark := nextText(sc)
	value, err := nextInt(sc)
	if err != nil {
		panic(err)
	}
	return Card{mark, value}, nil
}

func nextCards(n int, sc *bufio.Scanner) ([]Card, error) {
	ns := make([]Card, n)
	for i, _ := range ns {
		x, err := nextCard(sc)
		if err != nil {
			return nil, err
		}
		ns[i] = x
	}
	return ns, nil
}

func isEqualCards(x []Card, y []Card) bool {
	if len(x) != len(y) {
		return false
	}
	for i := 0; i < len(x); i++ {
		if !x[i].Equal(y[i]) {
			return false
		}
	}
	return true
}

