	n := nextInt(sc)
	l := make([]card, n)
	for i := 0; i < n; i++ {
		l[i] = card{
			label: nextStr(sc),
			value: nextInt(sc),
		}
	}
	origin := make([]card, n)
	copy(origin, l)

	quickSort(l, 0, n-1)
	l2 := mergeSort(origin)

	count := 0
	for i := range l {
		if l[i] == l2[i] {
