func quickSort(A []Card, p int, r int) {
	if p < r {
		q := partition(A, p, r)
		quickSort(A, p, q-1)
		quickSort(A, q+1, r)
	}
}

func partition(A []Card, p int, r int) int {
	x := A[r]
	i := p - 1
	for j := p; j < r; j++ {
		if A[j].num <= x.num {
			i++
			t := A[i]
			A[i] = A[j]
			A[j] = t
		}
	}
	t := A[i+1]
	A[i+1] = A[r]
	A[r] = t
	//i+1がパーティションになっている
	return i + 1
}

func mergeSort(A []Card, left int, right int) int {
	if left+1 < right {
		//fmt.Println(A[left:right])
		mid := (left + right) / 2
		//左半分に対して、マージソート
		a := mergeSort(A, left, mid)
		//右半分に対して、マージソート
		b := mergeSort(A, mid, right)
		//↑をマージ
		c := merge(A, left, mid, right)
		return a + b + c
	} else {
		return 0
	}
}

func merge(A []Card, left int, mid int, right int) int {
	//A[left:right]を、midで2つに分ける
	n1 := mid - left
	n2 := right - mid
	L := make([]Card, n1)
	R := make([]Card, n2)

	for i := 0; i < n1; i++ {
		L[i] = A[left+i]
	}
	for i := 0; i < n2; i++ {
		R[i] = A[mid+i]
	}
	L = append(L, Card{"", 1000000000})
	R = append(R, Card{"", 1000000000})
	i := 0
	j := 0

	for k := left; k < right; k++ {
		if L[i].num <= R[j].num {
			A[k] = L[i]
			i++
		} else {
			A[k] = R[j]
			j++
		}
	}

	return right - left
}

