let sentinel = ('Z', max_int)

let merge_sort a cmp =
  let merge l m r =
    let ni = m - l in
    let nj = r - m in
    let init_ary n p =
      Array.init (n + 1) (fun i -> if i = n then sentinel else a.(p + i))
    in
    let ai = init_ary ni l in
    let aj = init_ary nj m in
    let rec doit i j k =
      if k < r then begin
        if cmp ai.(i) aj.(j) <= 0 then (a.(k) <- ai.(i); doit (i + 1) j (k + 1))
        else (a.(k) <- aj.(j); doit i (j + 1) (k + 1))
      end
    in
    doit 0 0 l
  in
  let rec doit l r =
    if (l + 1) < r then begin
      let m = (l + r) / 2 in
      doit l m;
      doit m r;
      merge l m r
    end
  in
  doit 0 (Array.length a)

