    let aj = init_ary nj m in
    let rec doit i j k =
      if k = r then ()
      else begin
        if cmp ai.(i) aj.(j) <= 0 then (a.(k) <- ai.(i); doit (i + 1) j (k + 1))
        else (a.(k) <- aj.(j); doit i (j + 1) (k + 1))
      end
    in
    doit 0 0 l
  in
  let rec doit l r =
    if (l + 1) < r then begin
      let m = (l + r) / 2 in
      doit l m;
      doit m r;
      merge l m r
    end
  in
  doit 0 (Array.length a)

