import std.algorithm, std.conv, std.range, std.stdio, std.string;
import std.typecons;

void main()
{
  auto n = readln.chomp.to!size_t;

  auto ai = new card[](n);
  foreach (i; n.iota) {
    auto rd = readln.chomp.splitter(' ');
    auto suite = rd.front; rd.popFront;
    auto value = rd.front.to!int;
    ai[i] = card(suite, value);
  }

  auto stable = true;
  quicksort(ai, 0, n - 1, stable);

  writeln(stable ? "Stable" : "Not stable");
  foreach (a; ai)
    writefln("%s %d", a.suite, a.value);
}

size_t partition(ref card[] ai, size_t p, size_t r, ref bool stable)
{
  auto x = ai[r];
  auto i = p - 1;

