def merge(nums, left, mid, right):
    l = nums[left:mid] + [('_', 9999999999)]
    r = nums[mid:right] + [('_', 9999999999 )]
    l_cur = 0
    r_cur = 0
    for i in range(right - left):
        if l[l_cur][1] > r[r_cur][1]:
            nums[left + i] = r[r_cur]
            r_cur = r_cur + 1
        else:
            nums[left + i] = l[l_cur]
            l_cur = l_cur + 1


