    if end - begin <= 1:
        return

    piv = A[end - 1].value
    left, right = begin, begin

    for i in range(begin, end - 1):
        if A[i].value <= piv:
            if i - left > 0:
                A[left], A[i] = A[i], A[left]
            left += 1

    A[left], A[end - 1] = A[end - 1], A[left]

    QuickSort(A, begin, left)
    QuickSort(A, left + 1, end)

