def merge(A, left, mid, right):
    n1 = mid - left
    n2 = right - mid
    L = [None for _ in range(n1+1)]
    R = [None for _ in range(n2+1)]
    for i in range(n1):
        L[i] = A[left + i]
    for i in range(n2):
        R[i] = A[mid + i]

    L[n1] = math.inf
    R[n2] = math.inf

    i = 0
    j = 0

    for k in range(left, right):
        try:
            v1 = int(L[i][2:])
        except:
            v1 = L[i]

        try:
            v2 = int(R[j][2:])
        except:
            v2 = R[j]

        if v1 <= v2:
            A[k] = L[i]
            i += 1
        else:
            A[k] = R[j]
            j += 1


def merge_sort(A, left, right):
    if left + 1 < right:
        mid = (left + right) // 2
        merge_sort(A, left, mid)
        merge_sort(A, mid, right)
        merge(A, left, mid, right)

    return A


