def partition(a: list, left: int, right: int) :
    std = a[right].number
    j = left - 1
    for i, v in enumerate(a[left:right]):
        idx = i + left
        if a[idx].number <= std:
            j += 1
            a[j], a[idx] = a[idx], a[j]

    j += 1
    a[j], a[right] = a[right], a[j]
    return j

