    n1 = mid - left
    n2 = right - mid

    L = []
    R = []
    for i in range(n1):
        L.append(a[left+i])
    for i in range(n2):
        R.append(a[mid+i])

    inf = 1 << 32
    L.append(Card("Z", inf))
    R.append(Card("Z", inf))

    i = 0
    j = 0
    for k in range(left, right, 1):
        if L[i].number <= R[j].number:
            a[k] = L[i]
            i += 1
        else:
            a[k] = R[j]
            j += 1

