fn scan<T: std::str::FromStr>() -> T {
    let mut s = String::new();
    std::io::stdin().read_line(&mut s).unwrap();
    s.trim().parse().ok().unwrap()
}

fn scan_cards(n: usize) -> Vec<Card> {
    let mut vec: Vec<Card> = Vec::new();
    for _ in 0..n {
        let s: String = scan();
        let mut it = s.split_whitespace();
        let a: char = it.next().unwrap().to_string().chars().collect::<Vec<char>>()[0];
        let b: i64 = it.next().unwrap().parse().ok().unwrap();
        let c = Card{ suit: a, value: b };
        vec.push(c);
    }
    vec
}

#[derive(Clone, Copy)]
struct Card {
    suit: char,
    value: i64,
}

fn merge(a: &mut Vec<Card>, left: usize, mid: usize, right: usize) {
    let mut l: Vec<Card> = Vec::new();
    let mut r: Vec<Card> = Vec::new();
    for i in left..mid {
        l.push(a[i]);
    }
    for i in mid..right {
        r.push(a[i]);
    }
    let c = Card{ suit: 'z', value: std::i64::MAX };
    l.push(c);
    r.push(c);
    let mut i: usize = 0;
    let mut j: usize = 0;
    for k in left..right {
        if l[i].value <= r[j].value {
            a[k] = l[i];
            i += 1;
        } else {
            a[k] = r[j];
            j += 1;
        }
    }
}

fn merge_sort(a: &mut Vec<Card>, left: usize, right: usize) {
    if left + 1 < right {
        let mid = (left + right) / 2;
        merge_sort(a, left, mid);
        merge_sort(a, mid, right);
        merge(a, left, mid, right);
    }
}

fn partition(a: &mut Vec<Card>, p: usize, r: usize) -> usize {
    let x = a[r];
    let mut i = p;
    for j in p..r {
        if a[j].value <= x.value {
            a.swap(i, j);
            i += 1;
        }
    }
    a.swap(i, r);
    i
}

fn quick_sort(a: &mut Vec<Card>, p:usize, r: usize) {
    if p < r {
        let q = partition(a, p, r);
        quick_sort(a, p, q - 1);
        quick_sort(a, q + 1, r);
    }
}

fn main() {
    let n: usize = scan();
    let mut a: Vec<Card> = scan_cards(n);
    let mut b = a.clone();
    merge_sort(&mut a, 0, n);
    quick_sort(&mut b, 0, n - 1);

    let mut stable = true;
    for i in 0..n {
        if a[i].suit != b[i].suit {
            stable = false;
            break;
        }
    }

    if stable {
        println!("Stable");
    } else {
        println!("Not stable");
    }

    for i in 0..n {
        println!("{} {}", b[i].suit, b[i].value);
    }
}

/* マージソートの実装(安定か不安定かチェックするため) */

fn merge<T: Ord + Clone>(series: &mut Vec<T>, left: usize, mid: usize, right: usize) {
    let ls = series[left..mid].to_vec();
    let rs = series[mid..right].to_vec();

    let mut li = 0;
    let mut ri = 0;
    for i in left..right {
        if ls.len() <= li {
            series[i] = rs[ri].clone();
            ri += 1;            
        } else if rs.len() <= ri {
            series[i] = ls[li].clone();
            li += 1;
        } else if ls[li] > rs[ri] {
            series[i] = rs[ri].clone();
            ri += 1;
        } else {
            series[i] = ls[li].clone();
            li += 1;
        }
    }
}

fn merge_sort<T: Ord + Clone>(series: &mut Vec<T>, left: usize, right: usize) {
    if left + 1 < right {
        let mid = (left + right) / 2;
        merge_sort(series, left, mid);
        merge_sort(series, mid, right);
        merge(series, left, mid, right);
    }
}

/* partitionの実装 */

fn swap<T: Clone>(series: &mut Vec<T>, i: usize, j: usize) {
    let tmp = series[i].clone();
    series[i] = series[j].clone();
    series[j] = tmp;
}

fn partition<T: Ord + Clone>(series: &mut Vec<T>, p: usize, r: usize) -> usize {
    let x = series[r].clone();
    let mut i = p;
    for j in p..r {
        if series[j] <= x {
            swap(series, i, j);
            i += 1;
        }
    }
    swap(series, i, r);
    return i;
}

