struct Answer {
    is_stable: bool,
    v: Vec<Card>,
}

trait IntoQuiz {
    fn into_quiz(self) -> Quiz;
}

impl<I: Input> IntoQuiz for I {
    fn into_quiz(mut self) -> Quiz {
        let n: usize = self.parse_next().unwrap();
        let mut v = Vec::new();
        for _i in 0..n {
            let suit: Suit = self.parse_next().unwrap();
            let number: u32 = self.parse_next().unwrap();
            v.push(Card { suit, number });
        }
        Quiz { n, v }
    }
}

mod solver{
    pub fn partition<T>(a: &mut[T], p: usize, r: usize) -> usize 
    where T: Ord + Copy + Clone
    {
        let x = a[r];
        let mut i = p;
        for j in p..r {
            if a[j] <= x {
                a.swap(i, j);
                i += 1;
            }
        }
        a.swap(i, r);
        i
    }

    pub fn qsort<T>(a: &mut[T], p: usize, r: usize) 
    where T: Ord + Copy + Clone
    {
        dprintln!("qsort p:{}, r:{}", p, r);

        if p < r {
            let q = partition(a, p, r);
            qsort(a, p, q-1);
            qsort(a, q+1, r);
        }
    }
}

impl Quiz {
    fn solve(self) -> Answer {
        use solver::*;

        let mut res_v = self.v.clone();
        let len = res_v.len();

        qsort(&mut res_v[..], 0, len-1); 

        let is_stable = Quiz::is_stable(&self.v, &res_v[..]);


        Answer{ 
            is_stable: is_stable,
            v: res_v, 
        }
    }

    fn is_stable(org: &[Card], sorted: &[Card]) -> bool {
        for e2 in sorted.iter() {
            let num = e2.number;
            let fa1 = org.iter().filter(|x| x.number == num).map(|x| x.suit);
            let fa2 = sorted.iter().filter(|x| x.number == num).map(|x| x.suit);
            let mut zip = fa1.zip(fa2);
            if zip.any(|(e1,e2)| e1 != e2) {
                return false;
            }
        }
        return true;
    }
}

impl Answer {
    fn print(self) {
        if self.is_stable {
            println!("Stable");
        } else {
            println!("Not stable");
        }
        for e in self.v {
            println!("{}", e);
        }
    }
}

