fn solve(input: &str) -> String {
    let mut iterator = input.split_whitespace();

    let n: usize = iterator.next().unwrap().parse().unwrap();
    let mut a: Vec<Card> = Vec::with_capacity(n);
    for _i in 0..n {
        a.push(
            Card {
                suit: iterator.next().unwrap().chars().next().unwrap(),
                number: iterator.next().unwrap().parse().unwrap(),
            }
        )
    }

    let mut b = a.clone();

    quick_sort(&mut a, 0, n as isize - 1);

    b.sort_by_key(|c| c.number);

    let mut is_stable = true;
    for i in 0..n {
        if a[i].suit != b[i].suit {
            is_stable = false;
            break;
        }
    }

    let mut ans = if is_stable {
        String::from("Stable\n")
    } else {
        String::from("Not stable\n")
    };

    for i in 0..n {
        let card = &a[i];
        ans += &format!("{} {}\n", card.suit, card.number);
    }

    return ans.trim().to_string();
}

