        quick_sort(a, q as isize + 1, r);
    }
}

fn partition(a: &mut Vec<Card>, p: usize, r: usize) -> usize {
    let x = a[r].number;
    let mut i: isize = p as isize - 1;
    for j in p..r {
        if a[j].number <= x {
            i += 1;
            a.swap(i as usize, j)
        }
    }
    a.swap(i as usize + 1, r);
    i as usize + 1
}

