fn qsort<T: std::cmp::PartialOrd + Copy + std::fmt::Debug>(a: &mut Vec<T>, l: usize, r: usize) {
    if l + 1 >= r {
        return;
    }
    // let p = (r + l) / 2;
    let p = r - 1;
    let e = a[p];
    a.swap(p, r - 1);
    let mut b = l;
    for i in l..r - 1 {
        if a[i] <= e {
            a.swap(i, b);
            b += 1;
        }
    }
    a.swap(b, r - 1);
    qsort(a, l, b);
    qsort(a, b + 1, r);
}

fn msort<T: std::cmp::PartialOrd + Copy + std::fmt::Debug>(a: &mut Vec<T>, l: usize, r: usize) {
    if l + 1 >= r {
        return;
    }
    let m = (l + r) / 2;
    msort(a, l, m);
    msort(a, m, r);
    // merge
    let mut b0 = l;
    let mut b1 = m;
    let mut res = vec![];
    while !(b0 == m && b1 == r) {
        if b0 == m {
            res.push(a[b1]);
            b1 += 1;
        } else if b1 == r {
            res.push(a[b0]);
            b0 += 1;
        } else {
            if a[b0] <= a[b1] {
                res.push(a[b0]);
                b0 += 1;
            } else {
                res.push(a[b1]);
                b1 += 1;
            }
        }
    }
    for i in l..r {
        a[i] = res[i - l];
    }
}

